pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space.
    let post = post_residual as u32;
    let class = post / 10; // integer division into decade classes
    let rem = post % 10;

    // Reward small post-residuals strongly (tight fit), with harmonic decay.
    let tight_bonus = 40.0 * (-post as f64 / 30.0).exp();
    score -= tight_bonus;

    // Exact fill is ideal.
    if post == 0 {
        score -= 100.0;
    }

    // Penalize "dead zone" residuals: leftovers too small for typical items.
    // Dead space classes: 1..=9 and 11..=19 (can't hold most items >= 20).
    if post > 0 && post < 20 {
        score += 25.0 + 20.0 * (20 - post) as f64;
    }

    // Harmonic coupling with next item: if the next item fits exactly into
    // post_residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 60.0;
        } else if post >= next_item_size {
            // next item still fits: mild reward proportional to leftover quality
            score -= 10.0 * (1.0 - (post - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: penalize more if this bin becomes near-empty-class
            let gap = (next_item_size - post) as f64;
            score += 0.3 * gap;
        }
        // Modulo harmony: next item's decade class matching post class
        let next_class = next_item_size / 10;
        if next_class == class && post >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a bin is only attractive when the item
    // fits poorly everywhere else or many bins are open with fragmented space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with decent fits.
        score += 45.0;
        // But if this is the last fitting bin (no alternatives), new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // If open bins are highly fragmented (low mean residual but many bins),
        // starting fresh with a full bin is valuable for future large items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 20.0 + 15.0 * progress;
        }
        // Late in stream, consolidation into fewer bins matters more.
        if progress > 0.8 && open_bins_count > 0 {
            score += 10.0 * progress;
        }
    }

    // Mild penalty for spreading across too many bins when this bin is roomy.
    if open_bins_count > 4 && bin_residual > 50 && !is_new_bin {
        score += 5.0;
    }

    // Small tie-breaker: prefer bins whose residual is closest to item size
    // in a modular (capacity-fraction) sense.
    let frac = (bin_residual as f64 / cap - item_size as f64 / cap).abs();
    score += 3.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual).
    let mut score = post;

    // Penalize dead space that is too small to be useful for typical items,
    // scaled by how "orphaned" the leftover is.
    if post > 0.0 {
        let orphan = (1.0 - post / cap).exp() * (cap - post);
        score += 0.35 * orphan;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.9 * (nxt / cap) * (1.0 + post / cap);
        } else {
            // Wasted lookahead potential: leftover can't fit next item.
            score += 0.25 * (1.0 - post / cap);
        }
    } else {
        // Last item: pack as tightly as possible.
        score -= 0.5 * (item / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else or global space is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        let mut new_bin_score = cap - item; // waste of a fresh bin for this item
        // Early on, or when open bins are nearly full on average, new bin is fine.
        new_bin_score -= 0.8 * (1.0 - fragmentation);
        new_bin_score += 0.6 * progress * fragmentation;
        // If no bin can fit at all, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            new_bin_score -= 2.0;
        }
        // Lookahead synergy: a fresh bin can host many future items.
        if next_item_size > 0 {
            new_bin_score -= 0.4 * (next_item_size as f64 / cap);
        }
        score = score.min(new_bin_score);
    }

    // Mild penalty for spreading load across many bins when mean residual is high.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        score += 0.15 * (mean_residual / cap) * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap too small to ever hold a typical item (<= 10) is dead space.
        if post_residual <= 10 {
            score += 60.0 * (11.0 - pr);
        } else if post_residual <= 20 {
            score += 18.0 * (21.0 - pr) / 10.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Open bins pressure: many open bins -> prefer filling existing ones,
    // especially when this is the last chance bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 2.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // gap unusable for the known next item
    }

    // Slightly prefer bins with low residual already (consolidate space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: empty bin gets a moderate default so real bins
    // with decent fits win, but terrible fits (dead space) lose to it.
    if bin_residual == bin_capacity {
        score = 25.0 + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack that still fits the next item is "useful" residual.
            score -= 40.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // Dead space relative to the next item.
            score += 25.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let avg_fair = 100.0 - (item_size as f64);
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive if the next item also fits alongside here.
            if post_residual >= next_item_size {
                score -= 30.0;
            }
        }
        let _ = avg_fair;
    }

    // Slight preference for keeping residual away from awkward mid-range dead zones.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers are bad unless it was a perfect fit
        if post_residual <= 5 { score -= 100.0; }
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual: avoid making a bin an outlier
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless residual space is tight overall
    if bin_residual == bin_capacity {
        let tight = (mean_residual < item_size as f64 * 1.2) || fitting_bins_count == 0;
        if tight {
            score -= 150.0;
        } else {
            score += 250.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small post_residuals that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 25.0 / (1.0 + tightness * 3.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure against accumulating many open bins: encourage filling existing bins
    // when the stream is far along.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 1.2 * progress);

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * -0.3 + mean_residual * -0.05;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 25.0; // no open bin has room worth using -> open new bin
        }
    }

    // Mild preference toward bins below mean residual (consolidate emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let max_item = 100u32;
        if post_residual >= max_item {
            score -= 6.0; // still fully usable
        } else {
            let dead = (max_item - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item then fits very snugly.
            let nr = post_residual - next_item_size;
            score -= 4.0 * (1.0 - (nr as f64) / (bin_capacity as f64));
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual > 40 {
            score += 8.0; // but bad fits still get pushed toward new bins
        }
    }

    // New-bin candidate handling: opening a bin is attractive only when the item
    // is large or the stream is early / few bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by state.
        let mut new_bin_cost = 25.0;
        new_bin_cost += 15.0 * progress;          // late in stream, prefer existing bins
        new_bin_cost -= 2.0 * open_bins_count as f64; // more open bins => consolidate
        new_bin_cost -= 0.1 * mean_residual;      // high mean residual => reuse
        if item_size >= 60 { new_bin_cost -= 10.0; } // big items pack cleanly in fresh bins
        score += new_bin_cost;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class 0 (residual divisible by 10) is the most reusable slot size.
    let residual_class = (post_residual % 10) as f64;
    score += residual_class * 0.8;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Fractional capacity coupling: reward filling a large share of the bin.
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 15.0;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item exactly matches the post-residual (harmonic
    // pairing), this placement is perfect.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot use leftover: penalize large dead space.
            score += (post_residual as f64) * 0.15;
        }
        // Harmonic pairing on decade classes: next item fits a residual
        // rounded to the same class.
        if next_item_size / 10 == post_residual / 10 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - crowd * 2.0 - avg_tightness * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if post_residual >= item_size {
            score -= 5.0; // new bin can host the next item too
        }
    }

    // Late in the stream, tighten up: prefer closing bins well.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (10.0 - residual_class * 0.5);

    // Small tie-break noise-free deterministic nudge toward fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: reward closeness of match
            score -= 80.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space the next item cannot use
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow new bin if item is large and residuals are fragmented
        if item_size as f64 > mean_residual {
            score -= 250.0;
        }
    }

    // Late in stream: consolidate, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space penalty
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to residual (relative fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, mild spread ok.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.6 * pressure;

    // New-bin candidate: only attractive when item barely fits nowhere well
    // or residual too small to be useful.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let poor_options = (mean_residual - item_size as f64).max(0.0);
        score = 45.0 + 20.0 * (1.0 - tightness) - 0.5 * poor_options;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin if an existing bin is last chance
        }
        if next_item_size > 0 && next_item_size <= post_residual.min(bin_capacity - item_size) {
            score -= 10.0; // new bin can also host next item
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // next item won't fit here anyway; slight penalty for stranding
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it matches.
            let gap = (post_residual - next_item_size) as f64;
            score -= 80.0 - gap.min(80.0) * 0.5;
        } else {
            // Next item cannot fit: penalize dead space, worse for small leftovers.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5 + 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly penalize so we prefer reusing open bins,
    // but allow opening a new bin when the fit is very poor (handled above).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a new bin is more attractive early when few bins are open.
        score -= open_bins_count as f64 * 2.0;
    }

    // Late in the stream, tighten up: residual waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: chain bonus scaled by leftover waste
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 200.0 - 0.5 * chain_waste;
        } else {
            // next item won't fit after this placement: penalize small dead space
            let dead = next_item_size - post_residual;
            if dead <= 10 {
                score += 60.0 + 4.0 * dead as f64;
            } else {
                score += 20.0;
            }
        }
    }

    // Penalize small unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: keep it neutral-ish, only chosen when no good fit exists
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    // Mild preference for consolidating into fewer bins
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Penalize post residuals that are small but not usable by next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer minimal waste, i.e., tightest fit.
        score += 0.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when an existing bin gives a tight fit.
        if post_residual < 15 {
            score += 60.0;
        } else {
            score += 10.0;
        }
        // More open bins already -> new bin less costly in bookkeeping terms.
        score -= 0.5 * open_bins_count as f64;
    }

    // Progression: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are "dead". Penalize them super-linearly.
    // Items in [1,100]; treat post_residual <= 12 as effectively dead space.
    let dead_zone = 12.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Perfect-fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; encourage closing bins out by filling them tightly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin that should be consumed rather than left dangling.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual,
    // strongly favor this placement (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves further fragmentation: mild reward.
        let next_left = post_residual - next_item_size;
        score -= 8.0;
        if next_left < dead_zone as u32 {
            score += (dead_zone - next_left as f64) * 2.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use post_residual: the leftover is likely dead.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin
    // is costly, so strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Only
    // prefer it when no open bin offers a decent fit, i.e. when the best
    // achievable post_residual among open bins would be highly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (amortized over long streams).
        let stream_progress = step_index as f64 / (total_items.max(1) as f64);
        let amortized = 18.0 * (1.0 - 0.3 * stream_progress);
        // Opening is attractive if the current item is large and would leave
        // a clean residual for the (known) next item, or if open bins are tight.
        let clean_fit = if next_item_size > 0 && post_residual >= next_item_size { 6.0 } else { 0.0 };
        let tight_open_bins = if mean_residual < item_size as f64 { 5.0 } else { 0.0 };
        score = amortized - clean_fit - tight_open_bins + (100 - item_size.min(100)) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
