            }
            // MUT190: exact-multiple chain bonus — residual fits the next item an exact number of times
            if slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT190: lookahead coupling — current item + next item exactly fills residual
            let pair = item_size as f64 + nxt;
            if pr >= pair && pr - pair <= 3.0 {
