pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it decomposes into future-friendly chunks
    let pr = post_residual;
    if pr > 0 {
        // class by integer division thresholds on capacity fractions
        let class = match pr {
            0 => 0.0,
            x if x <= cap as u32 / 8 => -6.0,      // near-dead space: strongly penalize
            x if x <= cap as u32 / 4 => -3.0,
            x if x <= cap as u32 / 2 => 1.5,
            _ => 4.0,
        };
        score += class;

        // Modulo arithmetic: residuals that are multiples of common item sizes (10/20/25/50)
        // are reusable, reward them.
        let reusable = (pr % 10 == 0) as f64 * 3.0
            + (pr % 20 == 0) as f64 * 2.0
            + (pr % 25 == 0) as f64 * 2.0
            + (pr % 50 == 0) as f64 * 3.0;
        score -= reusable;

        // Exact fit reward
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: prefer leaving a good post_residual for it
            let after_next = pr - next_item_size;
            if after_next % 10 == 0 {
                score -= 6.0;
            }
            score += after_next as f64 * 0.2;
        } else {
            // next item cannot use this residual: penalize wasted potential
            score += (next_item_size - pr).min(40) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Stream progression: late in stream, consolidate harder (dead space matters more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

