        score += 25.0;
    }
    // Penalize medium dead space (11..30) more softly.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (existing bins); when few bins are open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure penalty.
        score += 5.0 + 6.0 * pressure;
        // If lookahead item is large and this bin would be nearly full,
        // opening a new bin may be fine; slight relief.
        if next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 4.0;
        }
    } else {
        // Existing bin: mild reward that grows with open-bin pressure.
        score -= 3.0 * pressure;
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Late in the stream, avoid leaving any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.

    // Aggressive 2-step lookahead: if the next item exactly fills the post residual,
    // strongly prefer this bin (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits in the leftover: mild reward, scaled by how well it fills.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * fill;
    } else if next_item_size > 0 {
        // Next item won't fit in leftover: penalize dead space relative to next item.
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Reward placing into bins below the mean residual (consolidating emptier bins,
    // keeping tightly packed bins available for small items).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize leaving very small unusable slivers (< 10, the min item size),
    // unless the next item exactly matches (already rewarded above).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: brand-new empty bin. Make it moderately attractive so it wins
    // only when open bins would waste a lot of space. Base post_residual for a new bin
    // is (C - item), which is already large; add a mild opening penalty that decays
    // as the stream progresses (early on, opening bins is cheap).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * (1.0 - 0.5 * progress);
        // If no open bin can fit the item, the new bin is the only option anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for keeping the number of open bins in check late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later items get more conservative treatment.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tightness = (fit_ratio * fit_ratio) * 40.0 - 20.0 * fit_ratio;
    score -= tightness * (0.6 + 0.8 * progress);

    // Penalize dead space: residuals too small for any plausible item (1..100).
    if post_residual < 10 {
        score -= 8.0; // tiny dead space is fine, bin is effectively closed
    } else if post_residual <= 25 {
        // awkward middle zone: mostly penalize, unless lookahead pairs well
        let pairs = (next_item_size as f64 - post_residual as f64).abs();
        score += 6.0 * (1.0 - (-pairs / 15.0).exp());
    }

    // Lookahead coupling: reward leaving exactly the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-gap / 20.0).exp();
        // If next item is large, avoid leaving a residual it can't use.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
            score += 4.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer filling existing bins when reasonable.
        score += 18.0;
        // Reward opening when many bins are open but mean residual is low (all cramped).
        let crowding = mean_residual / bin_capacity as f64;
        score -= 25.0 * (1.0 - crowding).max(0.0) * (open_bins_count as f64).ln().max(0.0) / 3.0;
        // Early in stream, opening fresh bins is cheap and flexible.
        score -= 10.0 * (1.0 - progress);
        // Large items prefer fresh bins when nothing fits well.
        if fit_ratio > 0.9 && item_size > 60 {
            score -= 14.0;
        }
        // Never open a new bin for a tiny item if anything else fits.
        if item_size < 30 && fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Mild reward for using bins that deviate from the mean (balance the pool).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Prefer bins with smaller residual when many bins are open (first-fit-like tightening).
        score += 0.08 * bin_residual as f64 * (open_bins_count as f64 / 20.0).min(1.0);
    }

    // Global waste-awareness: as mean residual grows, discourage squandering space.
    score += 0.03 * mean_residual * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) coupling
    let mut score = pr + norm_pr * pr * (1.0 + progress);

    // Smooth progress-coupled polynomial: early stream tolerates slack, late stream punishes it
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_poly * pr * 0.5;

    // Penalize dead space relative to mean residual (non-linear coupling)
    let dev = norm_pr - (mean_residual / cap);
    score += dev * dev * cap * 0.3;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= last_chance * pr * 0.6;

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (pr - nxt) * 0.2 + 2.0 * (1.0 - progress);
        } else {
            score += (nxt - pr) * 0.15;
        }
    } else {
        // Last item: strongly prefer filling bins tightly
        score -= pr * 1.5;
    }

    // Mild penalty for proliferating open bins with large slack
    score += (open_bins_count as f64).ln() * norm_pr * 3.0;

    // New-bin candidate bias: make empty bin moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score -= item_size as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division into capacity bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (post_residual / 10) as i64; // harmonic class: 0..10 decile of residual

    // Reward very tight fits (small post_residual), with non-linear emphasis.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for the lookahead item is likely wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // modulo-arithmetic flavor: penalty modulated by harmonic class of dead space
        let dead = next_item_size - post_residual;
        let class = dead % 10;
        score += 8.0 + (class as f64) * 1.5 + dead as f64 * 0.4;
    }

    // Penalize large leftover residuals that fall into "awkward" harmonic bands
    // (residuals that rarely admit typical items: 1..9 or 31..39 style gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: bin_residual == bin_capacity. Only attractive when no
    // open bin fits well (item is large relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let is_desperate = (bin_residual - item_size) > 0
            && (mean_residual < item_size as f64 * 0.9);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Harmonic threshold on next_item_size: big lookahead discourages new bin waste
        let lookahead_bad = next_item_size > 0 && (post_residual as u32) < next_item_size;
        let mut new_bin_penalty = 55.0;
        if is_desperate { new_bin_penalty -= 45.0; }
        if progress < 0.2 { new_bin_penalty -= 10.0; }
        if lookahead_bad { new_bin_penalty += 10.0; }
        score += new_bin_penalty;
    }

    // Mild preference to balance residuals toward the mean (harmonic centering).
    score += (pr - mean_residual).abs() * 0.15;

    // Slight preference for bins whose residual class matches item size class.
    let item_class = (item_size / 20) as i64;
    let resid_class = band / 2;
    if item_class == resid_class {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // gap too small for any plausible item (min size 1..100 stream, but
        // sub-10 gaps are statistically near-useless) -> strong penalty
        score += (10 - pr) as f64 * 12.0;
    } else if pr >= 10 && pr < 25 {
        // awkward mid gap: mildly penalized
        score += (25 - pr) as f64 * 3.0;
    }

    // Reward tight fits (post_residual small relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Exact or near-exact closure bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it uses the gap
        score -= (next_item_size as f64 / post_residual as f64) * 15.0;
    } else if next_item_size > post_residual {
        // next item cannot use this gap: penalize leaving a gap it almost fits
        if post_residual > 0 && (next_item_size - post_residual) <= 10 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate handling: an empty bin has no dead space yet; only
    // prefer it when no open bin offers a decent fit (residual barely fits).
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: modest, so poor fits in open bins lose to it
        score = 55.0 + open_bins_count as f64 * 1.5;
        if fitting_bins_count == 1 {
            // keep existing bin alive rather than opening a new one
            score += 40.0;
        }
        // early stream: opening bins is cheap, later: conserve
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual: avoid making a bin an outlier
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless residual space is tight overall
    if bin_residual == bin_capacity {
        let tight = (mean_residual < item_size as f64 * 1.2) || fitting_bins_count == 0;
        if tight {
            score -= 150.0;
        } else {
            score += 250.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near 0 is ideal.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residuals that are too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins are open
    // and the stream is progressing (consolidation pressure grows over time).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // But allow a new bin if current item is large and would leave tiny waste anyway
        if item_size >= 90 {
            score -= 20.0;
        }
    }

    // Mild bonus for bins below mean residual (prefer filling emptier bins,
    // keeping tight bins available for small items).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr)) * (1.0 + 0.5 * progress * progress);

    // Smooth coupling of post_residual with stream progress: tight fits rewarded more later
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Dead-space penalty: polynomial in post_residual vs next item lookahead
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * gap * gap / cap;
        // Reward residual that fits the next item smoothly
        let fit_next = if pr >= next_item_size as f64 { 1.0 - (pr - next_item_size as f64) / cap } else { 0.0 };
        score -= 20.0 * fit_next * fit_next;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    let scarcity = 1.0 / fitting_bins_count as f64;
    score -= 15.0 * scarcity * (1.0 + progress);

    // Penalize spreading residual far below mean residual (waste alignment), smooth coupling
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Mild penalty for opening new bins late in the stream when open bins exist
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (10.0 + 40.0 * progress * progress + 2.0 * open_bins_count as f64);

    // Small tie-breaker noise-free deterministic term
    score += 0.01 * (post_residual as f64).powi(3) / (cap * cap * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes 10..=20) are rewarded.
    let pr = post_residual;
    let mut usable = 0.0;
    if pr > 0 {
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { usable += 1.0; }
        }
    }
    score -= 6.0 * usable;

    // Perfect fill is ideal.
    if pr == 0 {
        score -= 40.0;
    } else if pr < 10 {
        // Dead space: too small for any item (min size 10... but items >=1 per
        // interface, so scale dead-zone by capacity fraction instead).
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the slack after the next placement
            let mut slack_usable = 0.0;
            for m in [10u32, 20, 25, 50].iter() {
                if slack % m == 0 { slack_usable += 1.0; }
            }
            score -= 4.0 * slack_usable;
            score += 0.05 * slack as f64;
        } else {
            // next item cannot fit here: mildly penalize tight leftovers
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Mean-residual anchor: bins below mean residual (fuller than average)
    // are preferred.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Integer-division threshold on post_residual: leftovers in [10, 20)
    // are "second-class" — often wasted; leftovers >= 50 are flexible.
    if pr >= 10 && pr < 20 {
        score += 5.0;
    }
    if pr >= 50 {
        score -= 3.0;
    }

    // Brand-new bin candidate: only attractive when current bin is hopeless
    // (tiny residual relative to capacity) or the item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 15.0 - desperation
            - 10.0 * progress
            - if next_item_size > 0 && next_item_size >= bin_residual { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Very small gaps are essentially dead space forever.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to capacity.
    score += 0.3 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - post_residual as f64);

    // Penalize bins whose residual is far above mean (poorly matched).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item would fit in post residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item cannot use the post residual, penalize creating such a gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 0.5 * post_residual as f64;
    }

    // New-bin candidate: make it attractive when fits are poor, unattractive when good fits exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 1.1 + open_bins_count as f64 * 2.0;
        // If only this bin can fit, opening is necessary.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
        // If next item is large, reserving fresh capacity helps.
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it matches.
            let gap = (post_residual - next_item_size) as f64;
            score -= 80.0 - gap.min(80.0) * 0.5;
        } else {
            // Next item cannot fit: penalize dead space, worse for small leftovers.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5 + 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly penalize so we prefer reusing open bins,
    // but allow opening a new bin when the fit is very poor (handled above).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a new bin is more attractive early when few bins are open.
        score -= open_bins_count as f64 * 2.0;
    }

    // Late in the stream, tighten up: residual waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many fitting bins -> prefer bins with smaller residual (waste-averse).
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; mild penalty for stranding space.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_options = if fitting_bins_count == 0 { 1.0 } else if fitting_bins_count == 1 { 0.5 } else { 0.0 };
        let open_bonus = (open_bins_count as f64).min(10.0) * 2.0;
        score += 30.0 - poor_options * 50.0 - large_item * 20.0 + open_bonus * (1.0 - progress) - mean_residual * 0.2;
    }

    // Time horizon: early on, be slightly greedy toward compact bins; late, favor any fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover space: residues modulo small moduli.
    let r10 = post_residual % 10;
    let r7 = post_residual % 7;
    let r5 = post_residual % 5;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // treat < 10 as nearly dead since typical items are large).
    if post_residual < 10 {
        score += 25.0;
    } else {
        // Reward "harmonic" leftovers divisible into common classes.
        if r10 == 0 { score -= 8.0; }
        if r5 == 0 { score -= 4.0; }
        if r7 == 0 { score -= 3.0; }
        // Odd/prime-ish residues are less reusable.
        if post_residual % 2 == 1 { score += 2.0; }
        if r10 != 0 && r5 != 0 && r7 != 0 { score += 4.0; }
    }

    // Lookahead coupling: does the leftover harmonically match the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 { score -= 18.0; }
            else if gap % 10 == 0 { score -= 12.0; }
            else if gap < 20 { score -= 6.0; }
            else { score += gap as f64 * 0.05; }
        } else {
            // Next item cannot use this leftover: leftover likely wasted.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is reasonable when the item
    // fits poorly everywhere (tight fits elsewhere are still better).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress > 0.5 {
        score += 3.0 * (open_bins_count as f64 - mean_residual / 10.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized dead space.
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            // Unusable sliver: penalize strongly (it's wasted capacity).
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Prefer tight fits: reward small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 15.0;

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and discourage spreading residual too thin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bins have poor fit or
    // post_residual in an open bin would be dead space.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + pressure;
        // If the item would leave a usable residual in an existing bin, keep it there.
        let usable_elsewhere = fitting_bins_count > 0
            && (post_residual >= 10 || post_residual == 0);
        score += if usable_elsewhere { base_penalty + 30.0 } else { base_penalty - 20.0 };
        // Lookahead: if next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= next_item_size as f64 * 0.3;
        }
    }

    // Lookahead coupling: if the residual left matches the next item well,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
    }

    // Slight preference for bins with below-mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits but leaves slack; reward proportionally to tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack.min(200.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize dead space left behind.
        let dead = (next_item_size - post_residual) as f64;
        score += dead.min(150.0);
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is a good compaction.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f).min(80.0) * 0.8;
    } else {
        score += (post_f - mean_residual).min(80.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (post_f.min(100.0));
    }

    // Late in the stream, prefer tighter packing (less room to recover later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_f * (0.3 + 0.5 * progress);

    // Very small dead space is excellent regardless of lookahead.
    if post_residual <= 5 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64 / 10.0).powf(1.6) };
        score += dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty scaled by wasted potential.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual < bin_capacity {
        score -= 5.0 * pressure.min(3.0);
    }

    // Mean-residual anchoring: bins with residual near mean are "typical"; prefer
    // placing into below-mean-residual bins (denser bins) to keep slack pooled.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // New-bin candidate logic: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced over time as stream matures.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 35.0 + 45.0 * progress;
        // If item is large relative to capacity, opening fresh is more acceptable.
        score -= 20.0 * fit_ratio;
        // If next item is large, a fresh bin gives room; reduce penalty.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If only one bin fits, opening is very costly (waste of a usable bin).
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Small stochastic-free tie-breaker based on bin tightness ordering.
    score += (bin_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: penalize large post-residual with smooth quartic coupling to progress
    let mut score = post * (1.0 + 2.0 * progress * (1.0 - x) * (1.0 - x));

    // Non-linear dead-space penalty: quadratic in x, amplified late in stream
    score += (x * x) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits smoothly: subtract for small x with cubic falloff
    score -= (1.0 - x).powi(3) * cap * 0.4;

    // Coupling with mean residual: prefer bins whose post-residual deviates
    // from the mean in a way that leaves usable space
    let dev = (post - mean_residual) / cap;
    score += 0.5 * dev * dev * cap * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - x);
    }

    // Lookahead: if next item fits in post-residual, reward smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = (post - nx) / cap;
            score -= (1.0 - slack * slack) * 3.0 * (1.0 + progress);
        } else {
            score += 2.0 * (nx - post) / cap * (1.0 + progress);
        }
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (1.0 - progress);
    }

    // Mild congestion term: many open bins -> prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals divisible by small harmonic denominators.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        else { score += 2.0; } // odd residuals pair poorly

        // Penalize "dead zone" residuals: too small for the smallest plausible item.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }

        // Integer-division tier on residual fraction of capacity.
        let tier = pr / 25; // 0..4 quarters
        score += tier as f64 * 2.0; // larger residual = better bin, lower score overall
    } else {
        score -= 40.0; // perfect fill: strongly favored
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            // exact harmonic match classes between next item and residual
            if pr % next_item_size == 0 { score -= 5.0; }
        } else {
            // next item won't fit here regardless; mild penalty for wasting capacity
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when mean residual across open bins is low
    // (open bins are nearly full) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_frac = mean_residual / cap;
        // new bin attractive if existing bins are crowded
        score -= (1.0 - mean_frac) * 8.0 + progress * 6.0;
        // discourage hoarding too many open bins
        score += open_bins_count as f64 * 1.5;
        // but if current item is large and would leave awkward residue elsewhere,
        // new bin is fine — neutral base already high (post_residual = capacity).
    }

    // Global pressure: when many bins are open with high mean residual,
    // encourage consolidating into existing bins.
    if mean_residual > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 { score -= 8.0; }
    else if fill > 0.7 { score -= 4.0; }
    else if fill < 0.3 { score += 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Dead-space shaping: small unusable gaps penalized hard, stronger late.
    if post_residual > 0 && post_residual < 10 {
        score += (60.0 - 20.0 * progress) * (10.0 - post_residual as f64);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 100.0;
    }

    // Non-linear tightness reward (quadratic fill), stronger early.
    let fill = item_size as f64 / cap;
    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    // Deviation from mean residual, penalized quadratically on the post-residual.
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * 20.0;

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 80.0;
        } else if nxt <= pr {
            let slack = 1.0 - (pr - nxt) / cap;
            score -= slack * 15.0 * (1.0 - progress);
        } else if pr > 0.0 {
            let gap = (nxt - pr) / cap;
            score += gap * (40.0 + 30.0 * progress);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.0 * norm_pr;
    }

    // Open-bin pressure grows with count and progress.
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: sigmoid pressure that relaxes when existing bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        let pressure = 1.0 / (1.0 + (mean_norm * 6.0).exp());
        score += 60.0 * pressure * (1.0 - 0.4 * progress);
        // Necessary opening when no other bin fits.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
        // Reserve fresh capacity for a large upcoming item.
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space with non-linear shaping, harder late in stream.
    let mut score = pr as f64;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Perfect fit is ideal.
