    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    let fill = item_size as f64 / cap;
    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead with tiered slack rewards (fine-grained near-perfect chain fits).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
