        score -= 10.0;
    }

    // Integer-division threshold coupling: does the next item fit into the
    // post residual? If yes, reward the "chain" potential; if the next item
    // nearly fits (within a small harmonic band), give partial credit.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 3.0;
            // bonus when next item exactly consumes a harmonic fraction
            if pr % next_item_size.max(1) == 0 && pr > 0 {
                score -= 1.5;
            }
        } else {
            let gap = next_item_size - pr;
            if gap <= 5 {
                score += 0.5; // near miss, mild penalty
            } else {
