        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish score. It should win only when all
    // existing placements leave ugly residues. Base it on capacity minus a
    // discount that grows with stream progress and open-bin scarcity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 - 3.0 * progress - (open_bins_count as f64).sqrt();
        // If the item exactly fills a fresh bin, opening is great.
        if post_residual == 0 {
            score -= 5.0;
