    let frac = post_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    if frac < mean_frac {
        score -= (mean_frac - frac) * 4.0;
    } else {
        score += (frac - mean_frac) * 2.0;
    }

    score
}

