        score -= 170.0;
    } else if post_residual <= 10 {
        score -= 48.0 + 34.0 * progress;
    } else if post_residual <= 20 {
        score -= 7.0 + 16.0 * progress;
    } else if post_residual <= 35 {
        score += 4.0 * progress;
    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    let fill = item_size as f64 / cap;
    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead chain-fit rewards with graded slack (combined with fine-grained residual tiers).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 600.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 12.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                score -= 45.0 * (1.0 - slack / cap);
            }
            // Chain anticipation: if the item after next also fits the remaining slack,
            // this bin can host a compact chain — reward proportional to anticipated fill.
            if slack >= 2.0 {
                let second = (nxt * 0.9).min(slack);
                if slack - second >= 0.0 {
                    score -= 8.0 * (1.0 - (slack - second) / cap) * (1.0 - 0.4 * progress);
                }
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (55.0 + 42.0 * progress);
        }
    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0 + 22.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.2 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread), crowd-scaled.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // New-bin candidate: additive gate so tight-fit rewards still compete.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.055 * (open_bins_count as f64).min(20.0);
        let mut new_score = 78.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 200.0;
        }
        if next_item_size > 60 {
            new_score -= 28.0;
        }
        if item_norm > 0.85 {
            new_score += 30.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 18.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            new_score += 14.0;
        }
        // Pair-compatibility: opening a fresh bin whose post-fit residual exactly hosts
        // the next item is a strong justification for a new bin.
        if next_item_size > 0 {
            let fresh_residual = bin_capacity.saturating_sub(item_size);
            if fresh_residual as f64 == next_item_size as f64 {
                new_score -= 120.0;
            } else if fresh_residual >= next_item_size {
                new_score -= 22.0 * (1.0 - (fresh_residual - next_item_size) as f64 / cap);
            }
        }
        score += new_score - cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capf = bin_capacity as f64;
    let pr = post_residual as f64;
