    let has_next = next_item_size > 0;
    // Harmonic alignment of the incoming item with decadal classes.
    let align = if item_size % 10 == 0 { 1.0 } else { 0.0 };

    // Residuals on harmonic (multiple-of-10) classes are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    if !is_new_bin {
        if post_residual == 0 {
            // Perfect fit: bin is sealed, best possible outcome.
            score -= 1000.0;
        } else {
            // Last chance: this is the only open bin that fits; using it
            // avoids opening a new bin entirely.
            if fitting_bins_count == 1 {
                score -= 150.0;
            }
            // Decadal items consolidate well into existing bins.
            score -= 3.0 * align;

            if has_next {
                if post_residual == next_item_size {
                    // Lookahead item will seal this bin exactly: two items, one bin.
                    score -= 400.0 * (1.0 - 0.5 * progress);
                } else if post_residual > next_item_size {
                    // Bin stays usable by the next item; reward, decaying late in stream.
                    score -= 60.0 * (1.0 - 0.5 * progress);
                    if next_item_size % 10 == 0 {
                        score -= 5.0;
                    }
                } else {
                    // Dead space relative to the lookahead item; penalize harder
                    // as the stream progresses (less time to recover residual).
                    score += (nis - pr) * (1.5 + progress) * (capf / 100.0);
