        // with stream progress, fragmentation (open bins), and available mean space.
        let mut penalty = 260.0 + 180.0 * progress + 2.0 * open_bins_count as f64 + 0.4 * mean_residual;
        if has_next && nis <= mean_residual {
            // Next item can likely be served by existing residuals, so a fresh
            // bin for the current item is somewhat more acceptable.
            penalty -= 100.0;
        }
        if !has_next {
            // Last item: never open a bin if anything fits.
            penalty += 200.0;
        }
        score += penalty;
    }

    score
}

