        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Reward a perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward gap that exactly fits the next item (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual <= 10 {
            score -= 25.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; grows with stream progress (sunk investment).
        score += 30.0 + 20.0 * (step_index as f64 / (total_items as f64).max(1.0));
        // If any other bin fits, opening a new bin is wasteful.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        // But if the item is huge relative to typical residual, a fresh bin is attractive.
        if (item_size as f64) > mean_residual {
            score -= 35.0;
        }
    }

    // Mild preference for bins below mean residual (balance residual distribution).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

