pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear waste shaping (quadratic + cubic, stronger late in stream)
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 50.0 + cube * 70.0) * (0.5 + progress);

    // Tiered near-fit rewards (tight fits dominate)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 4 {
        score -= 175.0;
    } else if post_residual <= 10 {
        score -= 50.0 + 36.0 * progress;
    } else if post_residual <= 20 {
        score -= 8.0 + 18.0 * progress;
    } else if post_residual <= 35 {
        score += 4.0 * progress;
    }

    // Lookahead chain-fit rewards with graded slack
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 650.0;
            } else if slack <= 4.0 {
                score -= 460.0 - 12.0 * slack;
            } else if slack <= 15.0 {
                score -= 250.0;
            } else if slack <= 40.0 {
                score -= 100.0 * (1.0 - slack / cap);
            } else {
                score -= 45.0 * (1.0 - slack / cap);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (55.0 + 42.0 * progress);
        }
    }

    // Last-chance bin handling
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0 + 22.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.2 * norm_pr;
    }

    // Outlier penalty vs mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Mean-residual coupling: prefer tighter bins
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: sigmoid pressure gate with item-size justification
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.055 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 200.0;
        } else if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: new bin necessary
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 30.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 18.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 14.0;
        }
        // Fresh-bin chain potential: soften penalty when bin can host next item exactly
        if next_item_size > 0 && (cap - item_size as f64 - next_item_size as f64).abs() < 1e-9 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Integer division thresholds on post_residual: treat residuals in
    // "dead zones" (tiny slivers) as near-useless; reward mid/large classes.
    let q16 = post_residual / (bin_capacity / 16); // 0..16 harmonic class
    let q8 = post_residual / (bin_capacity / 8);   // 0..8 coarse class
    match q16 {
        0 => score += 40.0,               // sliver: dead space, heavily penalize
        1 => score += 18.0,
        2 => score += 6.0,
        3 => score -= 4.0,
        4 => score -= 10.0,               // sweet spot ~ 1/4 capacity
        5 => score -= 12.0,
        6 => score -= 8.0,
        7 => score -= 6.0,
        8 => score -= 4.0,                // ~1/2 capacity
        _ => score -= 2.0,                // large residual: still flexible
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable.
    let mod_bonus = if post_residual % 10 == 0 {
        -6.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else if post_residual % 20 == 0 {
        -5.0
    } else {
        0.0
    };
    score += mod_bonus;

    // --- Lookahead coupling: next item's harmonic class vs post residual ---
    if next_item_size > 0 {
        let nq = next_item_size / (bin_capacity / 8); // 0..8 class of next item
        // Reward if post_residual can host the next item's class comfortably.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving a slack that lands in a good harmonic class
            let nq16 = (post_residual - next_item_size) / (bin_capacity / 16);
            let class_fit = match nq16 {
                0 => -14.0,
                1 => -8.0,
                2 => -4.0,
                3 | 4 => -10.0,
                5 | 6 => -8.0,
                _ => -5.0,
            };
            score += class_fit - slack * 0.05;
            // Exact or near-exact match for next item is gold.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: mild penalty scaled by how big next is.
            score += 4.0 + (nq as f64);
        }
    }

    // --- Tightness reward: small post_residual relative to residual used ---
    let tight = 1.0 - frac;
    score -= tight * tight * 12.0;

    // --- Last-chance bin: strongly favor using it over opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // Many options: be pickier, penalize mediocre fits less strongly? No—
        // with many alternatives, prefer the very best; add small spread noise
        // via deterministic class offsets to break ties toward tighter bins.
        score += (q8 as f64) * 0.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: only attractive when open bins are
        // fragmented (high mean residual spread) or this is a big item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_cost = 55.0
            + mean_residual * 0.25
            + open_bins_count as f64 * 1.5
            - (item_size as f64) * 0.3
            - progress * 5.0;
        score = new_bin_cost + (item_size as f64) * 0.1;
        // Opening a fresh bin right before a huge next item can be smart.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // --- Stream-phase modulation: early on, keep bins flexible; late, pack tight ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.75 {
        score -= (bin_residual - post_residual) as f64 * 0.05; // reward fuller use late
    } else if progress < 0.25 {
        score += pr * 0.02; // slightly discourage near-full bins early
    }

    // Mean-residual alignment: prefer bins whose residual tracks the fleet mean
    // (keeps future items placeable across many bins).
    score += (mean_residual - pr).abs() * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
