    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (11.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // New-bin candidate: additive gate so tight-fit rewards still compete.
    if bin_residual == bin_capacity {
