        let crowd = 1.0 + 0.055 * (open_bins_count as f64).min(20.0);
        let mut new_score = 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 30.0;
        }
        // Large items justify a fresh bin.
        if item_norm > 0.82 {
            new_score += 34.0;
        }
        // Item much larger than mean residual: opening a bin sized for it is efficient.
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.25 {
            new_score -= 20.0 * (ratio - 1.25).min(2.2);
        }
        // Small item while mean residual can host the next item: avoid fragmentation.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            new_score += 16.0;
        }
        // Additive blend: new-bin score competes with fit scores.
        score += new_score - cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

