    // A residual that cannot fit even the smallest plausible item (<= ~12) is dead space.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits: post_residual close to zero (but not dead) is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; with few bins, opening new ones is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (new bin costs a full capacity unit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly by default; only attractive when the
    // item fits badly everywhere else (large dead space would be created).
    if bin_residual == bin_capacity {
        let dead_elsewhere = post_residual as f64; // same value for empty bin = full residual
        let bad_fit_pressure = pressure + 55.0;
        score = bin_capacity as f64 * 0.9 + bad_fit_pressure;
        if next_item_size as f64 <= post_residual as f64 {
            // lookahead: next item could reuse this bin's future residual
            score -= 15.0;
        }
        let _ = dead_elsewhere;
    }

    // Lookahead bonus: if the next item fits into this bin's post-residual,
    // chaining placements reduces fragmentation.
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        score -= 12.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's an outlier worth closing out.
    let res = post_residual as f64;
    if res < mean_residual - 15.0 {
        score -= 8.0;
    } else if res > mean_residual + 15.0 {
        score += 6.0;
    }

    score
}

