pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: item + next item exactly fills the bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - chain_gap / bin_capacity as f64);
        if chain_gap == 0.0 {
            score -= 40.0; // exact two-item closure
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow here; mildly penalize tight fills that strand the bin.
        score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tightness of the current placement (small post residual is good).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: bins with less slack than average absorb items better.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in stream, be picky about creating fragmented bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 10.0 * (1.0 - progress);
    }

    // Prefer consolidating into fewer bins when many are open.
    if bin_residual < bin_capacity {
        score -= 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) increasingly hard.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Penalize dead space that is too small for the smallest plausible item,
    // scaled by how far we are into the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward this placement; otherwise penalize.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0 + 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins fit the item, prefer bins with smaller residual (best-fit).
    if fitting_bins_count > 1 {
        score += 0.03 * (bin_residual as f64 - mean_residual);
    }

    // Bin-count pressure: with many open bins, prefer filling existing ones.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this is effectively the last chance) or stream is early.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            score += 30.0; // an existing bin is the last chance; avoid opening new
        } else {
            score += 18.0 + 20.0 * progress;
        }
    }

    // Mild penalty for leaving residual near mean (avoid fragmenting evenly).
    score += 0.02 * ((post_residual as f64) - mean_residual).abs();

    score
}

