    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial coupling to progress.
    // Early in the stream, mild penalty on post_residual; late in stream, stronger
    // emphasis on compactness so residual space is exploited.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Cubic damping term: very small residuals are great, very large residuals bad.
    score += 0.35 * cap * pr_norm * pr_norm * pr_norm;

    // Lookahead coupling: reward residual that exactly matches the next item,
    // penalize residuals that are just barely too small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 12.0 * (-diff / 20.0) * (-diff / 20.0);
        } else {
            score += 4.0 + (-diff) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize opening a fresh bin, more so when existing
    // bins fit well and late in the stream; relax early when consolidation is cheap.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 25.0 + 20.0 * progress * fit_pressure - 10.0 * (1.0 - progress);
        // If no open bin fits, opening a new bin is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when mean residual is high, tolerate larger
    // post_residuals (space is abundant); when low, be stingy.
    score += 0.15 * (mean_residual - pr) * (1.0 - progress);

    score
}

