pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" residue classes (multiples of small sizes) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0; // residual aligns with common item granularity
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr <= 9 {
        score += 15.0; // dead space too small for any item
    }

    // Integer-division threshold: residual bucket via pr / 10
    let bucket = pr / 10;
    score -= (bucket as f64) * 2.0;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let n = next_item_size as f64;
            // harmonic coupling: reward proportional to how well next item divides residual
            if pr % next_item_size == 0 {
                score -= 10.0 + n * 0.1;
            } else {
                score += (pr - next_item_size) as f64 * 0.3;
            }
        } else {
            score += 8.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let tight = (post_residual as f64) <= 15.0;
        if tight {
            score += 40.0; // keep good fits in existing bins
        } else {
            score -= 5.0 + mean_residual * 0.05;
        }
    }

    // Progress-based gentle pressure to close bins early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let nxt = next_item_size as f64;

    let mut score = pr;

    // Tiered residual shaping (borrowed strength): tiny residuals rewarded hard.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 58.0 + 36.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Parent's non-linear shaping on large residuals (kept, softened).
    let quad = norm_pr * norm_pr;
    score += quad * 12.0 * (0.5 + progress);

    // Fill tightness reward, stronger early.
    score -= item_norm * item_norm * 22.0 * (1.0 - 0.5 * progress);

    // Lookahead anticipation (combined with fine-grained fitting).
    if next_item_size > 0 {
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 250.0 - 8.0 * progress;
            } else if slack <= 40.0 {
                score -= 102.0 * (1.0 - slack / cap);
            } else {
                score -= 45.0 * (1.0 - slack / cap);
            }
            // Leaving a second usable gap after next item fits.
            if slack >= mean_residual.min(cap * 0.5) && slack > 0.0 {
                score -= 30.0 * (slack / cap);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (55.0 + 40.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    // Spread balancing.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Fragmentation band penalty.
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    // New-bin candidate: sigmoid gate with refined couplings.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if item_norm > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= nxt && item_norm < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size > 0 && nxt > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            new_score -= 13.0 * item_norm;
        }
        score = new_score;
    } else {
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && nxt > pr {
            score += 6.5 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= nxt && pr - nxt <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && nxt < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Zero residual is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer reusing rather than opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 8.0 + 2.5 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 2.0 + 0.3 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 5.0;
    }

    // Prefer bins with residual close to mean (balanced usage).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the NEXT item: post_residual exactly matches lookahead size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            // lookahead still fits; favor tight leftovers
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0); // up to -40 when slack is 0
        } else {
            // lookahead CANNOT fit here: leftover is likely dead space
            let dead = post_residual as f64;
            // penalize dead space more if it's small (unusable), less if large (reusable later)
            if dead < 10.0 {
                score += 25.0; // tiny sliver, nearly unusable
            } else {
                score += 8.0; // moderate leftover, mildly wasteful given lookahead miss
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average when lookahead fits,
    // prefer looser-than-average bins when lookahead doesn't fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
        } else {
            score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // New empty bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; slightly reduced late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = score.max(post_residual as f64) + 20.0 - 10.0 * progress;
        // if lookahead is huge relative to item, a fresh bin keeps large contiguous space
        if next_item_size > 60 && item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual)
    score -= (post_residual as f64).powf(1.7) * 0.05;

    // Penalize waste proportional to fraction of capacity left over
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits into post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // penalize leaving residual that can't host the next item if it's dead space
            let dead = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += dead * 0.15;
        }
    }

    // Time horizon: early in stream, prefer keeping bins flexible (moderate residual);
    // late in stream, just fill tightly.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 10.0;

    // Global state: many open bins -> encourage consolidation into existing bins
    score += (open_bins_count as f64) * 0.8;

    // Compare against mean residual: bins with residual near mean are neutral;
    // much larger residual bins are better targets for big items.
    let res = bin_residual as f64;
    let dev = res - mean_residual;
    score -= (item_size as f64 / bin_capacity as f64) * dev * 0.2;

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin late in stream or when item is huge relative to residuals
        score -= t * 20.0;
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 15.0;
        }
    }

    // Slight preference to use emptier bins when item is small
    score += (item_size as f64) * (res / bin_capacity as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual shaped by progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += poly * cap * 0.6;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress) * cap * 0.4;

    // Penalize dead space relative to mean residual
    score += (pr - mean_residual) * (pr - mean_residual) / cap * 0.15;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for many open bins, eased by progress
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless post_residual is large and item tight
    if bin_residual == bin_capacity {
        score += 4.0 - 6.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit -> overwhelming preference
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Near-perfect fit bonus (dead space <= 10 is often reusable by small items)
    if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic class of post_residual: classify leftover into capacity-fraction buckets.
    // Leftovers in the "large item compatible" class (>= 60) are valuable; tiny slivers (1..10) are dead space.
    let pr = post_residual;
    if pr < 10 {
        // dead sliver: penalize proportionally to how dead it is
        score += (10 - pr) as f64 * 2.5;
    } else if pr < 20 {
        score += 5.0;
    } else if pr < 35 {
        // mid class: usable by medium items, mildly attractive
        score -= 8.0;
    } else if pr < 60 {
        // large-item-compatible class
        score -= 15.0;
    } else {
        // very roomy leftover: excellent
        score -= 22.0;
    }

    // Modulo-10 structure: residuals that are multiples of 10 align with common item sizes
    if pr % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly prefer this bin
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 120.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here regardless: this placement strands the bin
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good when current item
    // is large and no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins generally, more when many bins are open
        let mut nb = 60.0 + 2.0 * open_bins_count as f64;
        // but if item is large and leaves a big residual, new bin is attractive
        if item_size >= 50 && post_residual >= 50 {
            nb -= 70.0;
        }
        // late in the stream, prefer consolidating
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 30.0 * progress;
        score += nb;
    }

    // Slight preference to fill bins below mean residual (balance tightening)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
