    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate: make empty bins unattractive unless existing bins are
    // all poor fits (post_residual would be tiny).
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
    }

    score
}

