        score += 60.0 - 45.0 * crowdedness - 20.0 * waste_pressure;
        // Early in the stream, opening bins is cheap and flexible.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with large mean residual -> discourage leaving more
    // slack around; prefer bins below mean residual (consolidation).
    let below_mean = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score += 10.0 * below_mean;

    // Mild preference for using bins with less residual overall as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

