        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 58.0 + 36.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Waste fraction penalty (parent idea, softened)
    let waste_frac = norm_pr;
    score += waste_frac * waste_frac * 18.0;

    // Lookahead on next item: reward slack fits, penalize dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 250.0;
            } else if slack <= 40.0 {
