        if pr >= 8.0 && pr <= 20.0 {
            score += 10.0 + 6.0 * (1.0 - progress);
        }
        // Reward bins whose post-residual still exceeds mean residual (future capacity)
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= mean_residual.min(cap * 0.5) {
                score -= 34.0 * (after / cap);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.5 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Small items prefer emptier bins (parent idea)
    score += (item_size as f64) * (bin_residual as f64 / cap) * 0.05;

    score
}

