        score += (fitting_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Mean-residual aware consolidation: favor bins tighter than the mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin smoothly, more so early
