            }
            // harmonic bonus: post_residual is an exact multiple of next item
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residual: penalize leaving big residue
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish, but prefer it when residual is large
    // (this bin is nearly empty anyway) or item barely fits elsewhere.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // post_residual of a fresh bin
        if post_residual == bin_capacity {
            score += 15.0; // slight bias toward reusing open bins on ties
        }
    }

    // Fraction of capacity wasted: quadratic penalty on large residuals.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 30.0;

    // Slight preference for tighter (fuller) bins early vs late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - frac) * 5.0 * (0.5 + progress);

    // Mean residual coupling: if this bin is much emptier than average,
    // prefer filling it rather than a well-packed one.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit bonus.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: favor bins whose residual can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (more filled already).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit: post_residual == next_item_size -> strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits too: reward proportionally to closeness of match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would not fit in the leftover: penalize dead space.
            score += 15.0 + diff * 0.5;
        }

        // Bonus if the two-step chain leaves a tiny, still-usable remainder.
        let chain = next_item_size + item_size as u32;
        if bin_residual >= chain {
            let r2 = bin_residual - chain;
            if r2 <= 10 {
                score -= 10.0;
            }
        }
    } else {
        // Last item: minimize final leftover directly (baseline already does).
        score += 0.0;
    }

    // Relative to mean residual: prefer bins whose post_residual deviates
    // favorably (smaller) from the mean residual of open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Penalize creating very small unusable slivers (1..=5) unless exact chain match.
    if post_residual > 0 && post_residual <= 5 && next_item_size != post_residual {
        score += 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing fits are poor (large post_residual waste) or few bins fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Attractive early in the stream or when nothing fits well.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 35.0; // fresh bin perfectly chains with the next item
        } else if progress < 0.2 && open_bins_count > 4 {
            score -= 20.0; // early diversification
        }
    }

    // Mild penalty for leaving a residual that exactly equals a "hard" size
    // that rarely appears (heuristic dead-space avoidance around 50/50 splits).
    if post_residual == 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but heavily so.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill (min item 1, typical small).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // nearly unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        score -= 12.0 - 0.15 * leftover as f64;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for wasting large residual
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item is a better relative fit
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling bins with small residual already (consolidate waste).
    let res_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * res_gap;

    // Early in stream: be conservative, keep bins flexible (favor balanced residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 0.10 * post_residual as f64;
    } else if progress > 0.7 {
        // late: aggressively close out bins
        score -= 0.06 * item_size as f64;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let best_possible = if post_residual == 0 { 0.0 } else { post_residual as f64 };
        score += 20.0 - 0.1 * best_possible;
        if fitting_bins_count == 0 {
            score -= 25.0; // must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Smooth polynomial coupling: residual quality weighted by stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks near prn=0.5
    score -= 30.0 * poly * (0.5 + progress);

    // Penalize tiny dead space more as stream progresses (wasted space matters late)
    let dead = (1.0 - prn).powi(3);
    score += 20.0 * dead * progress;

    // Reward tight fits (small post_residual) early via quadratic term
    score -= (1.0 - progress) * (prn * (2.0 - prn)) * 10.0;

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - prn);
    } else if next_item_size > 0 {
        score += 4.0 * prn;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64) * 0.05 * prn;

    // New-bin candidate: penalize slightly so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "dead" classes (too small for the smallest plausible item) are penalized.
    let dead_threshold = 10u32; // smallest legacy item size
    if post_residual < dead_threshold {
        score += 40.0; // unusable sliver
    }

    // Classify post_residual by integer division into harmonic bands of capacity/5.
    let band = post_residual / (bin_capacity / 5).max(1);
    let band_bonus: f64 = match band {
        0 => 8.0,   // nearly full bin: excellent compaction
        1 => 2.0,   // small residual, still useful
        2 => 0.0,   // mid residual
        3 => -1.0,  // large residual: wasteful
        _ => -3.0,  // mostly empty bin being filled slightly
    };
    score -= band_bonus;

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // common item sizes, making future perfect fits more likely.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0); // better if tight
        } else {
            // next item won't fit here; residual becomes dead space for next step
            score += (next_item_size - post_residual).min(20) as f64 * 0.5;
        }
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin should only win when the
    // placement here is poor (large post_residual) or it's early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive for large items or many open bins.
        score = 60.0 + 40.0 * item_ratio - 30.0 * progress
            + 3.0 * open_bins_count as f64
            - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    let mut score = pr;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 160.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack <= 4.0 {
                score -= 380.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 200.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 20.0 * (1.0 - progress);
            }
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 34.0 * (after / cap);
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if fill > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        // New: with many open bins, opening a fresh bin is costlier.
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        // New: late stream, prefer filling existing bins over opening.
        new_score += 25.0 * progress * (1.0 - fill);
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        // New: near-exact two-item chain lookahead (item + next fits residual).
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for even the smallest plausible item.
    let dead_threshold = 10.0f64.min(item_size as f64);
    if (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual <= 20 {
        // Risky zone: likely to become dead space later.
        score += 12.0;
    }

    // Reward very tight fits (small but still-usable residual).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading across many open bins,
    // but a last-chance bin (fitting_bins_count == 1) should be favored strongly.
    score += open_bins_count as f64 * 0.6;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // residual usage or open-bin residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 15.0; // base cost of opening a new bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= fragmentation * 0.3;
        if item_size > 70 {
            score -= 10.0; // big items fit cleanly into fresh bins
        }
        if progress < 0.2 {
            score += 5.0; // early stream: prefer filling existing bins
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // placing here would strand the next item's better option
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize leftover space with non-linear shaping, harder late in stream.
    let mut score = pr as f64;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    // Tiered dead-space shaping (borrowed from best): strong rewards for tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 58.0 + 36.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    let fill = item_norm;
    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead: anticipate next item fit (combined fine-grained tiers).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 40.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 250.0;
            } else if slack <= 40.0 {
                score -= 102.0 * (1.0 - slack / cap);
            } else {
                score -= 45.0 * (1.0 - slack / cap);
            }
            // Reward leaving a second usable gap after the next item fits.
            if slack >= mean_residual.min(cap * 0.5) && slack > 0.0 {
                score -= 34.0 * (slack / cap);
            }
        }
        // Mid-range residual that cannot hold next item late: fragmentation risk.
        if pr > 20.0 && pr < 45.0 && nxt > pr {
            score += 6.5 * (1.0 - progress);
        }
        // Dead gap just below next item size: nearly unusable.
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score -= 40.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
