    // 2-step lookahead: reward when post_residual matches next item exactly or closely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 60.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportional to wasted space
            score += 10.0 + 0.3 * (nxt - post_residual as f64);
        }
    } else {
        // last item: prefer tightest fit
        score -= 15.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are more "committed";
    // placing there keeps many bins usable.
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fit is terrible or stream is early.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
