        // can still absorb the next item comfortably.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 + 4.0 && fill < 0.6 {
            new_score += 30.0 * (1.0 - progress);
        }
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        // Near-exact two-item chain lookahead.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 24.0 * (1.0 - after2 / 6.0) * (0.6 + 0.4 * progress);
            }
        }
        // Reward leaving a residual close to mean_residual (keeps future fits easy).
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if (after - mean_residual).abs() <= 3.0 {
                score -= 12.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted residual (dead space), amplified late in stream.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth cubic coupling: early stream tolerates loose fits, late stream punishes them.
    let progress_coupling = 0.6 * progress * progress * (3.0 - 2.0 * progress);
    score += progress_coupling * pr * (1.0 + pr / cap);

    // Perfect-fit reward: smoothly stronger as post_residual approaches zero.
    let fit_quality = 1.0 - pr / cap;
    score -= 14.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead: reward residual that can accommodate the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let miss = (nx - pr) / cap;
            score += 10.0 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 8.0 * progress;
    }

    // Deter new-bin proliferation smoothly with number of open bins.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 4.0 + 1.5 * open_bins_count as f64 + 25.0 * (1.0 - progress);
        // Allow new bin when existing residuals are all poor fits (smooth gate).
        let mean_gap = ((mean_residual - pr).abs()) / cap;
        score -= 12.0 * mean_gap * mean_gap;
    }

    // Mild preference for balancing residuals across open bins.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
