            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 250.0;
            } else if slack <= 40.0 {
                score -= 102.0 * (1.0 - slack / cap);
            } else {
                score -= 45.0 * (1.0 - slack / cap);
            }
            // Parent's second-gap reward retained
            if slack >= mean_residual.min(cap * 0.5) && slack > 0.0 {
                score -= 30.0 * (slack / cap);
