        if next_item_size > 60 {
            score -= 32.0;
        }
        if item_norm > 0.85 {
            score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 13.0 * item_norm;
        }
    } else {
        // Mid-range residual guard
        if pr >= 8.0 && pr <= 20.0 {
            score += 10.0 + 6.0 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (divisible by common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward post_residuals that are exact multiples of 10 or 25 (harmonic classes)
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 20 == 0 {
            score -= 3.0;
        }
    } else {
        // Perfect closure: bin exactly filled
        score -= 30.0;
    }

    // Penalize dead space: leftover too small for any plausible item
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.8 {
        score -= 8.0 * fill_ratio;
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
        // Extra reward if next item exactly matches a harmonic class of pr
        if pr % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; mild penalty for wasting the lookahead
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty so
    // we only open new bins when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 14.0;
        // But if current bin would leave a terrible residual, new bin is better
        if pr > 0 && pr < 15 {
            score -= 25.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress;

    // Prefer bins tighter than the mean residual (compactness pressure)
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Many open bins: discourage spreading, favor tightest fills
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64;
        score -= 0.05 * (bin_residual as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are only bad
    // if they are tiny-but-nonzero gaps that nothing realistic will fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: leaving a gap the lookahead item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap slightly larger than the next item (awkward fit).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score += 12.0;
    }
    // Penalize bins that cannot host the next item at all while gap is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // (penalize opening a new bin, recognizable by residual == capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count.min(20) as f64;
    }

    // Mean residual coupling: prefer bins whose post placement stays near the mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early in the stream, be more tolerant of new bins; later, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

