pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward post_residual that exactly matches
    // or closely matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 500.0; // chain: this bin will be perfectly filled next step
        } else if post_residual >= next_item_size {
            score -= 120.0 - gap * 0.8; // next item can still fit here
        } else {
            score += 40.0; // next item cannot follow; residual likely dead
        }
    }

    // Penalize post_residual that is unusably small relative to typical
    // item sizes (dead space), scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - progress * 0.5);
    }

    // Relative-to-mean coupling: prefer bins whose resulting residual
    // moves the open-bin pool toward homogeneity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Make the empty bin mildly unattractive
    // so good existing fits beat it, but attractive when fits are poor.
    if bin_residual == bin_capacity {
        score += 90.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open new bin
        } else {
            // If best alternative would leave big dead space, opening fresh
            // is fine; approximate via item fit quality in this call.
            let fit_ratio = item_size as f64 / bin_capacity as f64;
            if fit_ratio > 0.8 {
                score -= 100.0; // big item into fresh bin is natural
            }
        }
    }

    // Slight preference to fill bins with more content already (fewer bins overall).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to item
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 18.0 / (1.0 + fit_ratio);

    // Penalize large dead space relative to capacity
    let dead_frac = post_residual as f64 / cap;
    score += 12.0 * dead_frac * dead_frac;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 / (1.0 + slack / cap);
        } else {
            // next item won't fit here; mild penalty if post_residual becomes tiny waste
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits); later, pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - dead_frac);

    // Global state: many open bins with high mean residual -> encourage filling existing bins
    let mean_resid_frac = mean_residual / cap;
    if mean_resid_frac > 0.5 && open_bins_count > 2 {
        score -= 5.0 * mean_resid_frac * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 1.0 } else {
            // how bad are existing fits? approximate via mean residual vs item size
            ((item_size as f64) - mean_residual).max(0.0) / cap
        };
        score += 22.0 - 20.0 * urgency;
        // late in stream, avoid opening new bins
        score += progress * 8.0;
    }

    // Slight bonus for bins already partially filled (fragmentation avoidance)
    if bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - (bin_residual as f64) / cap);
    }

    score
}

