    // Last-chance bonus: smooth ramp via fitting_bins_count ratio
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 6.0 * scarcity * scarcity;
    }

    // Mild pressure from mean residual of open bins (encourages balancing loads)
    score -= 0.05 * (mean_residual - pr);

    // Small diversity term coupling open bins count with progress
    score += 0.3 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

