        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mid-range residual band: discourage leaving 8-20 slack when many bins
    // are open (fragmentation source).
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    // Late-stream: item larger than typical remaining slack nudges new-bin option.
    if bin_residual != bin_capacity && next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
        score += 7.0 * (1.0 - progress);
    }

    // New-bin candidate: sigmoid gate — open only when open bins are mostly full
    // or next item is large and needs fresh capacity.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0; // opening is necessary
        }
        if next_item_size > 60 {
            new_score -= 32.0; // reserve fresh capacity for large next item
        }
        if item_norm > 0.85 {
            new_score += 34.0; // very large item justifies a fresh bin
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0); // item larger than typical slack
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            new_score += 16.0; // existing slack can serve next item; don't open
