            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            new_score -= 13.0 * item_norm;
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = post_residual as f64 / bin_capacity as f64;

    // Strong reward for tight fits: small post_residual is good
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // Dead-space penalty: residual that no plausible item (1..100) can use well
    if post_residual > 0 {
        // Harmonic class: residuals in 1..10 are nearly dead space
        if post_residual < 10 {
            score += 60.0 - 6.0 * post_residual as f64;
        } else if post_residual < 20 {
            score += 25.0 - 1.0 * post_residual as f64;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.2 * next_item_size as f64;
            // extra reward for near-exact next-item fit
            let gap = post_residual - next_item_size;
            if gap < 5 {
                score -= 12.0;
            }
        } else {
            // post_residual too small for next item: penalize proportional waste
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit. Penalize new bin mildly so tight fits win.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if many bins are open and mean residual is high, opening new bin
        // can help consolidation later; soften penalty
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 15.0;
        }
        // early in stream, new bins are cheap
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Modulo/harmonic class shaping on post_residual: residuals that are
    // multiples of 10 align with common item sizes -> slightly favored
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // residuals that are prime-ish odd small numbers are awkward
    if post_residual % 2 == 1 && post_residual < 15 {
        score += 4.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is already below average (they're "nearly done")
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are "dead". Penalize them super-linearly.
    // Items in [1,100]; treat post_residual <= 12 as effectively dead space.
    let dead_zone = 12.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Perfect-fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; encourage closing bins out by filling them tightly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 1.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin that should be consumed rather than left dangling.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual,
    // strongly favor this placement (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves further fragmentation: mild reward.
        let next_left = post_residual - next_item_size;
        score -= 8.0;
        if next_left < dead_zone as u32 {
            score += (dead_zone - next_left as f64) * 2.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use post_residual: the leftover is likely dead.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin
    // is costly, so strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Only
    // prefer it when no open bin offers a decent fit, i.e. when the best
    // achievable post_residual among open bins would be highly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (amortized over long streams).
        let stream_progress = step_index as f64 / (total_items.max(1) as f64);
        let amortized = 18.0 * (1.0 - 0.3 * stream_progress);
        // Opening is attractive if the current item is large and would leave
        // a clean residual for the (known) next item, or if open bins are tight.
        let clean_fit = if next_item_size > 0 && post_residual >= next_item_size { 6.0 } else { 0.0 };
        let tight_open_bins = if mean_residual < item_size as f64 { 5.0 } else { 0.0 };
        score = amortized - clean_fit - tight_open_bins + (100 - item_size.min(100)) as f64 * 0.05;
    }

    score
}

