pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact chain matches.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).abs();
            score -= 40.0 / (1.0 + gap as f64 / 10.0); // graded reward for close chain fit
        }
        // Penalize residuals too small for typical future items (dead space)
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: strongly reward tight fills
        score -= (100.0 - post_residual as f64) * 0.5;
    }

    // Reward good absolute fill (low post residual)
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Relative to mean residual: prefer bins with above-average usage pressure
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless current fit is poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // If lookahead chains well into a fresh bin, allow it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid proliferation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    score
}

