    // Penalize dead space relative to mean residual (quadratic deviation).
    let dev = pr - mean_residual;
    score += 0.2 * dev * dev / cap;

    // Lookahead: reward if next item fits the post residual (smooth kernel).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
