        let gap = next_item_size as f64 - pr;
        score += 0.5 * gap * gap / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty scaled by number of open bins (prefer consolidation early).
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are tiny.
    if bin_residual == bin_capacity {
        score = score.max(0.0) + 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

