    // residual, this placement is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the known next item.
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins with slack -> prefer compacting
    // into existing bins; few open bins -> new bin is cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure of existing open bins.
        score += 30.0 + 15.0 * open_pressure;
        // If current bin is the only fit, strongly discourage a new bin.
        if fitting_bins_count == 1 {
            score += 120.0;
        }
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual.max(0.0);
    } else {
        // Existing bin: mild reward for using already-open capacity.
        score -= 5.0 * open_pressure;
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual >= 10 && post_residual < 20 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let match_quality = 1.0 - ((post_residual as f64 - next) / bin_capacity as f64);
            score -= 15.0 * match_quality; // next item fits perfectly-ish later
        } else {
            // next item cannot fit here: penalize dead space more strongly
            score += 5.0;
        }
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize waste
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "odd" —
    // filling them tightly is good; leaving them with big residual is wasteful.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs().powf(1.3) * if dev > 0.0 { 1.0 } else { 0.6 };

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 30.0 - 0.5 * crowding;
        // If next item is large and this item is small, new bin may be worth it
        if next_item_size > 50 && item_size < 30 {
            score -= 10.0;
        }
    }

    // Mild stream-phase adjustment: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let item = item_size as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fills: the fuller the bin becomes, the better.
    score -= 0.12 * (cap - post) * (item / cap);

    // Lookahead coupling: strongly favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Perfect two-item pairing bonus, scaled by how snug the pair is.
            score -= 6.0 + 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Leftover that cannot host the next item is likely dead space.
            score += 3.0 + 0.05 * (post - nxt).abs();
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when the item is large relative
    // to the average leftover space (existing bins would fragment badly).
    if bin_residual == bin_capacity {
        let advantage = item - mean_residual;
        if advantage > 0.0 {
            score -= 0.35 * advantage;
        } else {
            score += 6.0 - 0.2 * advantage.abs();
        }
        // Late in the stream, closing out bins is more valuable than spreading.
        score -= 12.0 * progress;
        // Fewer open bins -> slightly prefer reusing them over opening new.
        score += 0.25 * open_bins_count as f64;
    }

    // Penalize unusable slivers (< 10) that no future item can occupy.
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }

    // Mild global pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

