    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Tight-fit ladder (borrowed strength, tuned).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 170.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 30.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 12.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.5 * norm_pr * (1.0 + progress);
    }

    // --- 2-step lookahead: reward bins whose post_residual matches next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 550.0;
            } else if slack <= 4.0 {
                score -= 380.0 - 12.0 * slack;
            } else if slack <= 15.0 {
                score -= 210.0;
            } else if slack <= 40.0 {
                score -= 90.0 * (1.0 - slack / cap);
            } else {
                score -= 40.0 * (1.0 - slack / cap);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (55.0 + 45.0 * progress);
            if nxt <= 12.0 {
                score += 12.0 * (1.0 - progress);
            }
        }
    }

    // --- Mean-residual coupling: prefer bins tighter than the mean ---
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (9.0 + 0.4 * open_bins_count.min(25) as f64);

    // --- Last-chance logic: only fitting open bin must be used ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 25.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.0 * norm_pr;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let item_norm = item_size as f64 / cap;
