        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size > pr {
            score -= 38.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // Discourage leaving medium residuals when next item won't use them
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize leftover space with non-linear shaping, harder late in stream.
    let mut score = pr as f64;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    // Dead-space avoidance: small unusable gaps heavily penalized (tiered).
    if post_residual > 0 && post_residual <= 3 {
        score -= 120.0 + 28.0 * progress;
    } else if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Perfect fit is ideal (stronger reward, progress-scaled).
    if post_residual == 0 {
        score -= 100.0 + 60.0 * progress;
    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    score -= item_norm * item_norm * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead: exact fit for next item is a big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 80.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (40.0 + 30.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            // NEW: near-miss gap for next item wastes the residual band.
            if gap > 0.0 && gap < 0.10 {
                score += 22.0 * (0.10 - gap) * (1.0 + progress);
            }
        } else {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 80.0;
            } else if slack <= 4.0 {
                score -= 60.0 - 8.0 * slack;
            } else if slack <= 15.0 {
                score -= 45.0 * (1.0 - progress);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 15.0 * (1.0 - progress);
            }
            // Reward leaving a second usable gap after the next item fits.
            if slack >= mean_residual.min(cap * 0.5) && slack > 0.0 {
                score -= 32.0 * (slack / cap);
            }
            // NEW: reward filling a large fraction of the current residual.
            let fill_of_res = (bin_residual as f64 - pr) / bin_residual.max(1) as f64;
            score -= 18.0 * fill_of_res * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.0 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mid-range residual band: discourage leaving 8-20 slack when many bins
    // are open (fragmentation source).
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 9.0 + 6.0 * (1.0 - progress);
    }

    // New-bin candidate: sigmoid gate — open only when open bins are mostly full
    // or next item is large and needs fresh capacity.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 215.0; // opening is necessary
        }
        if next_item_size > 60 {
            new_score -= 25.0; // reserve fresh capacity for large next item
        }
        if item_norm > 0.85 {
            new_score += 32.0; // very large item justifies a fresh bin
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 22.0 * (ratio - 1.3).min(2.0); // item larger than typical slack
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            new_score += 15.0; // existing slack can serve next item; don't open
        }
        // If no open bin can even hold the next item, fresh capacity is valuable.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && mean_norm < 0.15 {
            new_score -= 20.0 * (1.0 - mean_norm / 0.15);
        }
        // NEW: tiny items should never trigger a new bin.
        if item_norm < 0.15 && mean_norm > 0.03 {
            new_score += 40.0;
        }
        // NEW: late in stream, strongly prefer existing bins.
        if progress > 0.7 {
            new_score += 20.0 * progress;
        }
        score = new_score;
    }

    score
}

