        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        new_score += 25.0 * progress * (1.0 - fill);
        // dead-space lookahead: if next item would leave a small unusable sliver in a fresh bin, penalize opening
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let dead = (pr - nxt_f) / cap;
            if dead > 0.0 && dead < 0.12 {
                new_score -= 20.0 * (0.12 - dead) * (1.0 + progress);
            }
        }
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
