pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills (low post_residual strongly rewarded).
    // Late: dead space matters less, so coupling decays.
    let decay = 1.0 - 0.6 * progress * progress;
    let prn = pr / cap;
    score -= decay * (1.0 - prn) * (1.0 - prn) * 12.0;

    // Smooth penalty for awkward residuals: mid-range post-residuals are least useful.
    let awkward = 4.0 * prn * (1.0 - prn);
    score += awkward * awkward * 10.0 * (0.5 + 0.5 * progress);

    // Reward using a nearly full bin (small post-residual relative to residual used).
    let fill = 1.0 - br / cap;
    score -= fill * fill * 6.0;

    // Last-chance bin bonus (smoothly weighted by how tight the fit is).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - prn);
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - prn) * (1.0 - progress);
    }

    // Prefer bins with residuals near the mean (balance preservation), smooth term.
    let dev = (br - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for opening new bins when many bins are already open and progress is high.
    if br == bin_residual && bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 measure "wasted" space
    // relative to the common item granularity (items 1..100, typical steps of 10).
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 2.5; // penalize off-grid leftovers

    // Dead-space cliffs: tiny post_residual is either perfect fit or useless gap
    if post_residual == 0 {
        score -= 40.0; // perfect closure — best possible
    } else if post_residual < 5 {
        score -= 15.0; // near-perfect, negligible waste
    } else if post_residual <= 10 {
        score += 5.0; // small but awkward gap
    } else if post_residual < 20 {
        score += 12.0; // dead space unlikely to be reused
    }

    // Integer-division thresholds on post_residual: how many "typical" items fit
    let slots = post_residual / 10;
    score -= slots as f64 * 6.0; // more reusable slots -> better bin

    // Lookahead coupling: harmonic class of next item vs post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0; // next item fits here: strong reward
            let nxt_class = (next_item_size % 10) as f64;
            let post_class = (post_residual % 10) as f64;
            if post_class >= nxt_class {
                score -= 8.0; // residue alignment: leftover stays on-grid
            }
        } else {
            score += 10.0; // next item won't fit here
        }
        // exact divisibility: post_residual is a multiple of next_item_size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 14.0;
        }
    } else {
        // last item: prefer closing bins
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when placement is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // baseline cost of opening a new bin, decaying slightly over stream
        score += 30.0 - 10.0 * progress;
        if post_residual > 50 {
            score += 15.0; // huge item in fresh bin wastes little, still costly
        }
    }

    // Spread pressure: prefer bins below mean residual when many bins open
    let residual_f = bin_residual as f64;
    if open_bins_count > 1 {
        let dev = residual_f - mean_residual;
        score += 0.08 * dev; // prefer tighter-than-average bins (best fit)
    }

    // Capacity fraction coupling: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac; // reward large fills

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual leaves a gap smaller than the lookahead item,
    // creating dead space the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward bins that can also host the next item (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins,
    // but a brand-new empty bin candidate gets a mild penalty unless needed.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight preference for tight bins (small residual) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    // Mean-residual coupling: if open bins are loose on average, prefer tightest fit.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New empty bin candidate: penalize unless current item is large relative to capacity
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
