    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: tiered residual shaping (fine-grained dead-space avoidance).
    let mut score = pr;
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 190.0 + 28.0 * progress;
    } else if post_residual <= 10 {
        score -= 55.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Extra non-linear shaping on top of tiers.
    let quad = norm_pr * norm_pr;
    score += quad * 20.0 * (0.5 + progress);

    // Tightness reward: filling most of the bin is desirable, more so early.
    score -= item_norm * item_norm * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead: anticipation of next item fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Reward leaving a second usable gap after next item fits.
            if slack >= mean_residual.min(cap * 0.5) && slack > 0.0 {
                score -= 32.0 * (slack / cap);
            }
            if slack <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
            // Fill-based reward when next item fits.
            let fill_used = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill_used * (1.0 - 0.5 * progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            if nxt - pr <= 4.0 {
                score += 7.0 * (1.0 - progress);
            }
            if pr > 20.0 && pr < 45.0 {
                score += 6.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 65.0 + 25.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.5 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mid-range residual band: fragmentation source.
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 9.0 + 6.0 * (1.0 - progress);
    }

    // Perfect fit for a small next item is extra valuable.
    if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: sigmoid gate with tuned adjustments.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 215.0;
        }
        if next_item_size > 60 {
            new_score -= 30.0;
        }
        if item_norm > 0.85 {
            new_score += 32.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            new_score -= 12.0 * item_norm;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            new_score += 15.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 && mean_norm < 0.15 {
            new_score -= 20.0 * (1.0 - mean_norm / 0.15);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            new_score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        // Dead-space risk: if next item would leave a tiny gap in this fresh bin, discourage.
        if next_item_size > 0 {
            let dead = (cap - next_item_size as f64) / cap;
            if dead > 0.0 && dead < 0.12 {
                new_score -= 20.0 * (0.12 - dead) * (1.0 + progress);
            }
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
    } else if next_item_size > post_residual {
        // Next item can't use leftover; penalize proportionally to wasted lookahead space.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Relative to mean residual: prefer bins with residual near the mean (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (below typical minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Early in stream, slightly favor opening bins to spread load; late, favor tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few typical items could use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 8.0; // tiny unusable gap
        } else if dead < 30.0 {
            score -= 2.0; // usable small gap
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here anyway; slight penalty for wasting space
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation_pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 6.0 * consolidation_pressure;
    } else {
        // New-bin candidate: penalize more when open bins are half-empty and early.
        score += 4.0 + 10.0 * consolidation_pressure * (1.0 - 0.5 * progress);
    }

    // Time horizon: late in stream, avoid opening bins; be more greedy on tight fits.
    score -= 15.0 * progress * fit_ratio;

    // Prefer bins whose residual is close to mean residual (balanced packing),
    // slightly less important late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - 0.5 * progress);

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
