    // Non-linear base: super-linear penalty on post residual (dead space)
    let mut score = 0.9 * post + 0.010 * post * post / cap;

    // Smooth coupling of dead-space penalty with stream progress:
    // later in the stream, waste matters more
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 0.35 * post * (0.5 + progress_coupling) / cap;

    // Reward tight fits: fill fraction of the bin, smoothly amplified
    let fill = item / cap;
    score -= 12.0 * fill * fill;

    // Reward near-exact closure of the bin (post residual close to 0)
    score -= 8.0 * (1.0 - post / cap).powi(6);

    // Lookahead: penalize leaving a residual that doesn't fit next item,
    // reward residuals that can absorb it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
