    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing ones
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual interaction: prefer bins deviating below mean residual
    // (closing small-residual bins first), smooth quadratic term
    score += 0.02 * (resid - mean_residual).powi(2) / cap;

    // New-bin candidate: make it unattractive unless existing placements
    // would be terrible (high post residual relative to capacity)
    if bin_residual == bin_capacity {
        let desperation = (post / cap).powi(2);
        // base cost of a new bin, discounted when all fits are wasteful
        score += 18.0 - 14.0 * desperation - 6.0 * progress;
    }

    score
}

