pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    }

    // Penalize very small post-residuals that create dead space unusable by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / post_residual as f64;
        if chain > 0.9 {
            score -= 25.0;
        } else {
            score -= 10.0 * chain;
        }
    }
    // Penalize leaving a gap that next item almost fits but misses (wasted potential).
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins give poor fits, but reduce penalty late in the stream or when
    // many bins are open with large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 8.0 * progress;
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 6.0;
        }
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Slight preference for filling larger residual bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.03 * bin_residual as f64;

    score
}

