pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / c;

    // Base: post residual with smooth polynomial shaping (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth coupling of residual with stream progress: late in stream, tolerate residual more
    score -= 18.0 * norm_pr * progress;

    // Tight fit reward (smooth, non-piecewise): gaussian-like bonus near zero residual
    let tightness = (-norm_pr * norm_pr / 0.02).exp();
    score -= 25.0 * tightness;

    // Last-chance bin: strongly reward if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    } else {
        score += 5.0 / fit.max(1.0);
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth margin term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / c;
        score -= 12.0 * (1.0 - (-gap * 8.0).exp());
        // penalize if next item nearly but not exactly fits (leaves awkward sliver)
        let sliver = (next_item_size as f64 - pr).max(0.0) / c;
        score += 10.0 * (-sliver * 20.0).exp() * sliver;
    }

    // Open bin pressure: many open bins -> favor consolidation into existing bins
    score += 3.0 * (open / (open + 5.0)) * (1.0 - progress);

    // Mean residual coupling: prefer bins whose residual is below mean (denser bins)
    score += 4.0 * ((pr as f64 - mean_residual) / c).max(-1.0).min(1.0);

    // New-bin candidate: penalize opening a fresh bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / c).max(0.0).min(1.0);
        score += 22.0 - 18.0 * avg_tightness - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (e.g. 0, 25, 50) are more reusable — reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill is always best
    } else {
        let class_bonus = match pr {
            0..=5 => 20.0,
            6..=15 => 10.0,
            16..=25 => 6.0,
            26..=50 => 0.0,
            _ => -6.0, // large dead space
        };
        score -= class_bonus;

        // Modulo-10 harmonic classes: residuals divisible by 10 pair well with
        // typical item sizes drawn on a 1..100 grid.
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this bin's leftover: penalize proportional dead space
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): must NOT win unless existing fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 1.5 + 20.0;
        // but if no open bin can fit the item, the new bin should win
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    // Tightness coupling: reward high fill ratio non-linearly.
    let fill = 1.0 - (bin_residual as f64 / cap);
    score -= 10.0 * fill * fill;

    // Stream progression: late in the stream, be greedier about filling bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Tiered near-perfect fit rewards (borrowed from best, tightened)
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 190.0 + 28.0 * progress;
    } else if post_residual <= 10 {
        score -= 55.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Lookahead on next item with graded slack rewards
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // fill-based reward: prefer bins that were fuller before placement
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            // tiny sliver residual is fine — likely usable later
            let sliver = pr / cap;
            if sliver > 0.0 && sliver < 0.05 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            // near-miss chain: next item barely doesn't fit — mild penalty
            if nxt - pr <= 4.0 {
                score += 7.0 * (1.0 - progress);
            }
        }
        // dead-space lookahead: penalize stranding a residual the next item nearly fills
        let dead = (pr - nxt) / cap;
        if dead > 0.0 && dead < 0.12 {
            score -= 20.0 * (0.12 - dead) * (1.0 + progress);
        } else if dead >= 0.12 && dead < 0.25 {
            score += 9.0 * (dead - 0.12) * (1.0 + progress);
        }
        if pr >= nxt && pr - nxt <= 2.0 && progress < 0.7 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0 + 25.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.5 * norm_pr;
    }

    // Residual dispersion penalty (keep residuals uniform for future fits)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // New-bin candidate logic with pressure-based sigmoid
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // large item relative to mean residual: opening a bin is reasonable
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size > pr {
            score -= 38.0 * (1.0 - progress);
        }
        // very low mean residual + small item late: squeeze into existing bins
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // existing-bin refinements
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after > 0.0 && after >= mean_residual.min(cap * 0.5) {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
    }

    score
}

