pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Tight-fit tiered rewards (borrowed & tuned from best-known)
    if post_residual == 0 {
        score -= 950.0;
    } else if post_residual <= 3 {
        score -= 180.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 36.0 * progress;
    } else if post_residual < 25 {
        score -= 5.0 + 12.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.5 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead with graded chain rewards
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 600.0;
            } else if slack <= 4.0 {
                score -= 420.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 230.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                score -= 40.0 * (1.0 - slack / cap);
            }
            // sliver avoidance: keep residuals either 0 or usable
            let sliver = pr / cap;
            if sliver > 0.0 && sliver < 0.05 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (55.0 + 45.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
    }

    // Mean-residual coupling (deviation penalty)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Last-chance: only fitting open bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 25.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.5 * norm_pr;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 210.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // Open-bin specific adjustments
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt > pr && nxt - pr <= 4.0 {
                score += 7.0 * (1.0 - progress);
            }
            if pr > 20.0 && pr < 45.0 && nxt > pr {
                score += 6.0 * (1.0 - progress);
            }
            let fill = (bin_residual as f64 - pr) / cap;
            if pr >= nxt {
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    score
}

