            new_score -= 38.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            new_score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            new_score -= 12.0 * item_norm;
        }
        if nxt_f > 0.0 {
            let dead = (pr - nxt_f) / cap;
            if dead > 0.0 && dead < 0.12 {
                new_score -= 20.0 * (0.12 - dead) * (1.0 + progress);
            }
            let chain = (pr - nxt_f) / cap;
            if chain >= 0.12 && chain < 0.25 {
                new_score += 9.0 * (chain - 0.12) * (1.0 + progress);
            }
            if pr >= nxt_f && pr - nxt_f <= 2.0 && progress < 0.7 {
                new_score -= 12.0 * (1.0 - progress);
            }
        }
        score = new_score;
    }

    score
}

