pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize leftover space with non-linear shaping, harder late in stream.
    let mut score = pr as f64;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    // Dead-space avoidance: tiered shaping for small residuals (borrowed from best).
