pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Tiered residual shaping (borrowed strength): exact fit >> tight >> mid >> loose.
    let mut score = pr;
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 190.0 + 28.0 * progress;
    } else if post_residual <= 10 {
        score -= 55.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    score -= item_norm * item_norm * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead: exact fit for next item is a big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Reward leaving a second usable gap after the next item fits.
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
            // Two-item lookahead: item + next nearly fills the bin.
            let two_slack = pr - nxt - item_size as f64;
