        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
        // Chain fill reward: bigger placements in bins that still chain well.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            if fitting_bins_count > 3 && pr / cap < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
        // Two-step chain: item + next item nearly fill bin.
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && pr >= nxt_f {
            let two_slack = pr - nxt_f - (item_size as f64);
            if two_slack >= 0.0 && two_slack <= 5.0 && (item_size as f64 / cap) < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            }
        }
    }

    // --- Late-stream consolidation: prefer filling existing bins near the end ---
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual that is too small for the *next* item too.
    if post_residual > 0 {
        let next_fits = next_item_size > 0 && post_residual >= next_item_size;
        if !next_fits {
            // Unusable gap for the lookahead item: quadratic dead-space penalty.
            let gap = post_residual as f64;
            score += gap * gap / (bin_capacity as f64);
        } else {
