    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Tightness ratio: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage scattering across many open bins.
    score += (open_bins_count as f64) * 0.8;

    // Penalize placing into bins whose residual deviates wildly from the mean
    // (prefer balanced residual pools unless it's a tight fit).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fallback, not a default.
    if bin_residual == bin_capacity {
        // Early in the stream, opening bins is fine; later, be conservative.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + progress * 25.0;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item (chaining).
        score -= 8.0;
        // Extra reward if item + next item nearly fill the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
