pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual already does this), but sharpen
    // with a quadratic penalty so leaving awkward gaps is heavily discouraged.
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can exactly fill this bin's post_residual,
    // this is a perfect pairing — reward it heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item would fit in the post_residual, mild reward for preserving usability.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If the next item CANNOT fit in the residual, the leftover is likely dead space;
    // penalize proportionally (unless residual is small enough to be near-full anyway).
    else if next_item_size > 0 && post_residual > 0 {
        score += 0.4 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Its post_residual == capacity - item_size is large, so it naturally scores high
    // (bad). Add extra penalty so a new bin is only chosen when all fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But late in the stream, opening fresh bins is less harmful (less future
        // to amortize), relax the penalty slightly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Global state coupling: when many bins are open with large mean residual,
    // there's slack in the system — be pickier about tight fits (amplify the
    // tightness reward). When bins are scarce/tight, accept decent fits readily.
    if open_bins_count > 0 {
        let slack = mean_residual / bin_capacity as f64;
        // High slack -> emphasize consolidation into existing bins.
        if slack > 0.5 && bin_residual < bin_capacity {
            score -= 8.0;
        }
        // Low slack -> avoid fragmenting: penalize medium-sized leftovers more.
        if slack < 0.25 && post_residual > 0 && post_residual < 30 {
            score += 6.0;
        }
    }

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very small residuals that limit future items); late in the stream, just
    // finish filling — reward any placement that closes bins down.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual < 10 {
        score -= 10.0; // near end: squeeze out every last drop
    }
    if progress < 0.2 && post_residual > 0 && post_residual < 15 {
        score += 8.0; // early: don't create tiny unusable slivers yet
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty for residual far from "useful" sizes, smoothed by progress
    let dead = (x - 0.5) * (x - 0.5);
