    // Reward tight fits more strongly as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = ((x - nx).abs() < 0.05) as f64;
        score -= 8.0 * fit_next * (1.0 - progress);
        // penalize residuals slightly larger than next item (wasted sliver)
        let sliver = ((pr as i64 - next_item_size as i64).unsigned_abs() as f64) / cap;
        score += 5.0 * sliver * (1.0 - sliver) * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for opening new bins late in the stream
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (5.0 + 20.0 * progress);

    // Mean residual alignment term
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: quantize capacity into eighths.
    // Residuals near a "usable slot" boundary (multiples of 25) are valuable.
    let eighth = post_residual / 12; // 0..8 harmonic class
    let class_bonus = match eighth {
        0 => 40.0,                 // dead space, heavily penalize
        1 => 18.0,
        2 => 0.0,
        3 => -6.0,
        4 => -10.0,                // ~half-full leftover: reusable
        5 => -8.0,
        6 => -4.0,
        _ => 6.0,                  // nearly full bin: good closure
    };
    score += class_bonus;

    // Exact modulo coupling: residual divisible by 25 or 50 is a clean slot.
    if post_residual % 50 == 0 && post_residual > 0 { score -= 12.0; }
    else if post_residual % 25 == 0 && post_residual > 0 { score -= 6.0; }

    // Lookahead: reward if next item fits into post_residual exactly or snugly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect pairing
