            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; penalize leaving medium gaps
            if post_residual >= 10 && post_residual <= 40 { score += 10.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap;
    if fill > 0.9 { score -= 20.0; }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (mean residual small) or few bins fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_tight = (cap - mean_residual) / cap; // high when bins are full
        let freshness = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        score = 55.0 - 35.0 * pressure - 25.0 * mean_tight - 10.0 * freshness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
