    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.0 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mid-range residual band: discourage leaving 8-20 slack when many bins
    // are open (fragmentation source).
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 9.0 + 6.0 * (1.0 - progress);
    }

    // New-bin candidate: sigmoid gate — open only when open bins are mostly full
    // or next item is large and needs fresh capacity.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 215.0; // opening is necessary
        }
        if next_item_size > 60 {
            new_score -= 30.0; // reserve fresh capacity for large next item
        }
        if fill > 0.85 {
            new_score += 32.0; // very large item justifies a fresh bin
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 22.0 * (ratio - 1.3).min(2.0); // item larger than typical slack
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 15.0; // existing slack can serve next item; don't open
        }
        // No open bin can hold the next item -> fresh capacity valuable.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && mean_norm < 0.15 {
            new_score -= 20.0 * (1.0 - mean_norm / 0.15);
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 38.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 12.0 * fill;
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer small post_residual (tight fit).
    // Lookahead: reward exact match of post_residual with next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-step chain
        }
        // Penalize post_residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are more valuable to fill.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Penalize leaving awkward residuals (too small to be useful: < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 8.0; // tiny unusable sliver
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            score += 0.15 * dead; // residual can't host the lookahead item
        }
    }

    // Lookahead chaining: reward residuals that exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let follow_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * follow_fit;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = fit_ratio < 0.7;
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        // Opening a new bin costs more late in the stream and when many bins are open.
        score += 35.0 + 20.0 * progress + pressure;
        if poor_fit && fitting_bins_count > 0 {
            // Allow escape hatch when the best existing fit is bad.
            score -= 30.0;
        }
    } else {
        // Mild bonus for consolidating into already-open bins.
        score -= 3.0;
        // Prefer bins below the mean residual (keeps residual distribution balanced).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global waste pressure: penalize leaving large residuals when few bins remain useful.
    let waste = (bin_capacity as f64 - item_size as f64) - post_residual as f64;
    let _ = waste; // waste equals bin_residual - item_size, implicit in post_residual

    // Slight preference for filling larger bins first when residuals are similar.
    score += 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth penalty for dead space that is too small to be useful later.
    let norm_pr = pr / cap;
    score += 12.0 * (1.0 - norm_pr) * norm_pr * norm_pr * cap * 0.05;

    // Reward tight fits (small post_residual relative to item) more strongly later in stream.
    let tightness = 1.0 - (item_size as f64) / (bin_residual.max(1) as f64);
    score -= (1.0 - tightness) * (3.0 + 4.0 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).abs() as f64) / cap;
        score += (1.0 - fits_next) * 4.0 * (1.0 + progress);
        score -= fits_next * (3.0 + 2.0 * (1.0 - gap));
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * (1.0 - progress);

    // New-bin candidate handling: make empty bin attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score += 2.0 + 1.5 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already the seed).

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small, hard-to-fill" classes get a bonus for being filled now.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, always best
    } else if pr <= 10 {
        score -= 8.0; // nearly dead space, close it out
    } else if pr % 10 == 0 {
        score -= 3.0; // round residual is reusable by common item sizes
    } else if pr < 20 {
        score += 4.0; // awkward small residual, penalize creating it
    }

    // Modulo-class coupling: if next item could exactly fill this residual,
    // reward strongly (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        } else if next_item_size > pr {
            score += 2.0; // next item won't fit here anyway; residual less valuable
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and there are many open bins with slack.
    if bin_residual == bin_capacity {
        let waste_here = post_residual as f64; // = capacity - item
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0
            - 10.0 * (waste_here / bin_capacity as f64)
            - 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If mean residual across open bins is large, opening new bins is worse.
        score += mean_residual * 0.15;
    }

    // Prefer bins with below-average residual (denser bins) mildly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight penalty for spreading across many bins late in the stream.
    if open_bins_count > 10 {
        score += 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 190.0 + 28.0 * progress;
    } else if post_residual <= 10 {
        score -= 55.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            score -= 38.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr > nxt {
                let after = pr - nxt;
                if after >= mean_residual.min(cap * 0.5) {
                    score -= 32.0 * (after / cap);
                }
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            } else if nxt - pr <= 4.0 {
                score += 7.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            let sliver = pr / cap;
            if sliver > 0.0 && sliver < 0.05 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 {
            let nxt = next_item_size as f64;
            if nxt >= pr * 0.5 && nxt < pr {
                score -= 8.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Penalize post_residual that cannot fit the lookahead item but could have fit it before.
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
        // Reward leaving room for the next item.
        if post_residual >= next_item_size {
            score -= 3.0;
        }
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Open bins pressure: discourage spreading across many bins when alternatives exist.
    if fitting_bins_count > 1 {
        score += open_bins_count as f64 * 0.5;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when it enables a clean pairing with the next item
    // or when current bin fits are all poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 40.0 + open_bins_count as f64 * 0.2;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 10.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            new_bin_score -= 5.0;
        }
        score += new_bin_score * (0.5 + 0.5 * progress);
    }

    // Mild preference for tighter existing bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize dead space more as residual shrinks.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 10.0 * (1.0 - dead / next_item_size as f64);
        }
    }

    // Reward tight fits relative to current item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Penalize bins far from mean residual (avoid fragmenting many bins unevenly).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But allow new bin if no existing bin gives a good 2-step chain.
        if next_item_size == 0 || post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize large post-residual dead space, especially if it's too small
    // to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 10.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 30.0 * next_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual can't hold the next item: penalize proportionally.
        score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Perfect match bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is above the mean
    // (larger residual bins absorb items, keeping tight bins intact).
    score -= 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Time horizon: later in the stream, be more conservative — prefer tight
    // packing and avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let large_item_relief = (item_size as f64 / 100.0) * 30.0;
        let no_alternative_relief = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let late_stream_penalty = progress * 20.0;
        score += base_penalty - large_item_relief - no_alternative_relief + late_stream_penalty;
    }

    // Small exploration coupling: favor bins whose residual is close to the
    // item size (residual-match term).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 3.0 * residual_gap / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 60.0 + 35.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead chain bonuses
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // two-item chain: next item and the one after could both fit
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            // near-miss: next item barely misses, small dead space penalty
            if nxt - pr <= 4.0 {
                score += 8.0 * (1.0 - progress);
            }
        }
    }

    // Deviation from mean residual: prefer tighter fills
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // New-bin candidate logic: pressure-aware opening
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;

        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let ratio = item_size as f64 / mean_residual.max(1.0);
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // Open-bin refinements
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr > nxt {
                let after = pr - nxt;
                if after >= mean_residual.min(cap * 0.5) {
                    score -= 32.0 * (after / cap);
                }
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            let sliver = pr / cap;
            if sliver > 0.0 && sliver < 0.05 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Mild consolidation pressure
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
