            }
        } else {
            // next item cannot use this residual: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
        // modulo resonance between post_residual and next_item_size
        if next_item_size != 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize tight bins (many fitting bins means flexibility; prefer least-flexible fit)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: prefer new bin only when current residuals are large
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac > 0.4 {
            score -= 10.0; // open bins are mostly empty-ish; fresh bin fine
        } else {
            score += 15.0; // prefer filling existing bins
