        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size as f64 > pr && next_item_size as f64 - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual).
    let mut score = post;

    // Penalize dead space that is too small to be useful for typical items,
    // scaled by how "orphaned" the leftover is.
    if post > 0.0 {
        let orphan = (1.0 - post / cap).exp() * (cap - post);
        score += 0.35 * orphan;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.9 * (nxt / cap) * (1.0 + post / cap);
        } else {
            // Wasted lookahead potential: leftover can't fit next item.
            score += 0.25 * (1.0 - post / cap);
        }
    } else {
        // Last item: pack as tightly as possible.
        score -= 0.5 * (item / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else or global space is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        let mut new_bin_score = cap - item; // waste of a fresh bin for this item
        // Early on, or when open bins are nearly full on average, new bin is fine.
        new_bin_score -= 0.8 * (1.0 - fragmentation);
        new_bin_score += 0.6 * progress * fragmentation;
        // If no bin can fit at all, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            new_bin_score -= 2.0;
        }
        // Lookahead synergy: a fresh bin can host many future items.
        if next_item_size > 0 {
            new_bin_score -= 0.4 * (next_item_size as f64 / cap);
        }
        score = score.min(new_bin_score);
    }

    // Mild penalty for spreading load across many bins when mean residual is high.
    if bin_residual != bin_capacity && open_bins_count > 1 {
        score += 0.15 * (mean_residual / cap) * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Normalize post_residual relative to item size (waste ratio)
    let waste_ratio = pr / (item_size as f64).max(1.0);

    // Non-linear penalty on waste ratio, growing with stream progress
    score += waste_ratio * waste_ratio * (0.5 + 2.0 * progress);

    // Smooth reward for tight fits (post_residual near zero)
    let tight = (-pr / (0.15 * cap)).exp();
    score -= 8.0 * tight * (0.5 + progress);

    // Coupling: post_residual vs mean residual — prefer bins below mean residual (compact bins)
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * 2.0 - dev * 3.0;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 4.0 * snug * snug;
        } else {
            // penalize residuals that can't host the next item, scaled by closeness to fitting
            let miss = (nx - pr) / cap;
            score += 3.0 * miss * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild penalty on spreading across many bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Slight preference for opening a new bin only when residual is very small
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = post_residual % (bin_capacity / 4).max(1); // quarter-capacity classes
    let post_class_f = post_class as f64;

    // Reward post_residuals in "harmonic" sweet spots (small classes pack well with small items)
    if post_residual > 0 {
        if post_class <= 5 {
            score -= 12.0 * (1.0 - post_class_f / 6.0); // near-zero class: good dead space
        } else if post_class >= (bin_capacity / 4) - 3 {
            score -= 6.0; // boundary class, often still usable
        } else {
            score += 8.0 * (post_class_f / (bin_capacity / 4) as f64); // penalize mid-class waste
        }
    } else {
        score -= 30.0; // perfect fill
    }

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish: reward tight coupling
            let gap = post_residual - next_item_size;
            if gap <= 4 {
                score -= 20.0;
            } else {
                score -= 10.0 * (next_item_size as f64 / post as f64);
            }
        } else {
            // next item won't fit: penalize leftover dead space proportionally
            score += 0.35 * post * (1.0 - post_residual as f64 / cap);
        }
    } else {
        // last item: prefer fullest bin
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        // allow new bin when many open bins and mean residual is high (fragmentation)
        if open_bins_count > 3 && mean_residual > 0.45 * cap {
            score -= 55.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.15 {
            score -= 20.0;
        }
    }

    // Penalize bins that are already very full (avoid wasting near-closed bins on small items)
    if post_residual > 0 && post_residual < item_size.max(1) {
        score += 5.0;
    }

    // Slight preference for tighter bins overall
    score -= 0.08 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
