pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A post_residual below the minimum item size (1..100 stream => treat ~10 as "likely dead")
    // is wasted space; apply a superlinear penalty for tiny residuals.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr) / 10.0; // fully dead gap
        } else if post_residual < 20 {
            score += 25.0 * (20.0 - pr) / 10.0; // likely dead for most items
        } else if post_residual < 40 {
            score += 8.0 * (40.0 - pr) / 20.0;  // risky gap
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // rather than spreading; penalize placements that leave large residuals when bin count is high.
    let obp = open_bins_count as f64;
    score += 0.05 * obp * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it moderately attractive only when the
    // current item is large or existing fits are poor. Penalize the empty bin by default
    // so we exhaust existing bins first, unless the item is big.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let big_item_bonus = if item_size > bin_capacity / 2 { -25.0 } else { 0.0 };
        // Lookahead: if next item is large and this item is small, opening a fresh bin
        // may pay off later.
        let lookahead_bonus = if next_item_size > 0 && next_item_size > bin_capacity / 2 && item_size < 30 {
            -15.0
        } else {
            0.0
        };
        // Fewer open bins => cheaper to open a new one.
        let openness = (open_bins_count as f64).ln().max(0.0) * 5.0;
        score += base_penalty + big_item_bonus + lookahead_bonus + openness;
    }

    // Lookahead synergy: reward placing item so post_residual can host the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 10.0; // residual just above next item wastes space
    }

    // Stream progression: early on, be more willing to open bins (spread); late, consolidate.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is ideal.
    if post_residual == 0 {
