    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight chain: post_residual close to next_item_size.
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Exact chain bonus.
            if post_residual == next_item_size {
                score -= 150.0;
            }
        } else {
            // Penalize dead space the next item cannot use, scaled by how close we came.
            let miss = (next_item_size - post_residual) as f64;
