        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Last item: pure waste minimization.
        score -= 300.0;
    }

    // Compare against mean residual: prefer bins that are already relatively full
    // (small residual) to consolidate occupancy.
    let resid_f = bin_residual as f64;
    score += 0.5 * (resid_f - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // If item leaves large unusable gap relative to next item, extra penalty.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // Few open bins -> new bin less costly.
        if open_bins_count <= 2 {
            score -= 60.0;
        }
    }

    // Mild preference for bins whose residual is a "nice" multiple region
    // (post_residual in 1..=9 is nearly dead space; penalize).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly hold a future item.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap the next item cannot use.
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is costly unless the item is
    // large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Base cost of a new bin.
        score += 45.0;
        // Reward opening when item is large and mean residual is small (poor fits elsewhere).
        score -= 40.0 * item_frac * (1.0 - mean_frac);
        // Early in the stream, opening bins is cheaper (more future to fill them);
        // late in the stream, prefer packing into existing bins.
        score -= 15.0 * (1.0 - progress) * item_frac;
        // Many open bins already -> discourage more.
        score += 2.0 * open_bins_count as f64;
        // If other bins fit, opening a new bin should be strictly discouraged
        // unless the fit elsewhere would be terrible.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild preference for bins with residual close to item_size (perfect fill).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    // Global balance: prefer bins whose residual deviates from the mean
    // in the direction that reduces fragmentation.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev;

    // Slight time-horizon scaling of the tightness reward: late items benefit
    // more from tight packing since fewer chances remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
