        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
    }

    // Deviation from mean residual: prefer tighter-than-average bins
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: adaptive gate based on mean residual pressure and progress
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let item_norm = item_size as f64 / cap;
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;

        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // large item relative to mean residual: opening a fresh bin is fine
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        // avoid opening bins whose post-fit dead space blocks the next item
        if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
        // early stream with small mean residual: reuse open bins instead
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        // large items late in the stream: prefer fresh bins
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // Open-bin specific refinements
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
        // sliver residuals that still chain with the next item
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            let sliver = pr / cap;
            if sliver > 0.0 && sliver < 0.05 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
