        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
    }

    // Mutation: two-step chain lookahead — reward bins where item + next item leave a near-perfect fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
