    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (multiples of common item-size blocks), penalize
    // awkward dead-space classes.
    let cap = bin_capacity as f64;

    // Class 1: post_residual divisible by 10 -> clean reusable space
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class 2: post_residual divisible by 25 (quarter/half classes)
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Class 3: dead-space penalty for tiny unusable remainders
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Integer-division threshold coupling: how many "average items"
    // (harmonic mean proxy ~ 20) still fit?
    let slots = post_residual / 20;
    score -= slots as f64 * 3.0;

    // Lookahead coupling via modulo classes of next_item_size
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by exactness of fit
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack % 10) as f64 * 0.5;
        } else {
            // next item does not fit: penalize proportionally to overflow class
            let over = next_item_size - post_residual;
            score += (over / 10) as f64 * 4.0 + 2.0;
        }
        // Harmonic alignment: next item size in same residue class as residual
        if next_item_size % 10 == bin_residual % 10 {
            score -= 2.5;
        }
    } else {
        // last item: prefer tightest fill
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // existing residuals are poor (high mean residual fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap).abs();
        // open new bin if mean residual is small (existing bins nearly full)
        score += 30.0 - fragmentation * 40.0 - progress * 5.0;
        // discourage hoarding many open bins
        score += open_bins_count as f64 * 1.5;
        // if the item perfectly fills a fresh bin's harmonic class, mild boost
        if item_size % 25 == 0 {
            score -= 5.0;
        }
    }

    // Mild preference for fuller bins overall (waste minimization)
    score += (bin_residual as f64 / cap) * 4.0;

    // Normalize pressure across stream progression
    score *= 1.0 + 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

