pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residual that cannot fit the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bins pressure: prefer reusing existing bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would not fit the post residual but could fit current residual.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins near the mean to keep balance.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: make empty bins moderately attractive only
    // when they would leave a large usable residual, else push toward reuse.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * open_bins_count as f64;
        if post_residual < 20 {
            score += 50.0; // opening a new bin for a near-full fill is wasteful
        }
    }

    // Late-stream tightness: as the stream progresses, be stricter about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: next item fills this bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item leaves only a tiny unusable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0 - slack as f64 * 2.0;
        } else {
            // Penalize leaving space just above the next item's size (dead zone).
            score += (slack as f64).min(60.0) * 0.15;
        }
    }

    // Next item cannot fit here at all: this residual is likely final.
    if next_item_size > 0 && post_residual < next_item_size {
        // Small residuals are fine (tight fit now), tiny ones ideal.
        if post_residual <= 5 {
            score -= 15.0;
        } else {
            score += post_residual as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Relative fill quality vs. mean residual: tighter-than-average is good.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize opening a new bin when other bins exist, unless stream is early
    // and few bins are open (spread load when cheap).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin required
        }
    }

    score
}

