pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Bonus proportional to how well next item also fits snugly.
            let chain_left = post_residual - next_item_size;
            score -= (chain_left as f64) * 0.3;
        } else {
            // Dead space risk if next item can't follow here.
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless all fits are bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing bins usually win.
        score += 55.0;
        // If item fits perfectly in a fresh bin (e.g. size 100 or near), allow it.
        let perfect = (item_size as f64 - bin_capacity as f64).abs() < 1e-9;
        if perfect {
            score -= 200.0;
        }
        // Late in the stream, opening fresh bins is cheaper than scattering.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
        // If current item is large, residual bins become dead space anyway.
        if item_size > 60 {
            score -= 20.0;
        }
        // Many open bins with high mean residual: prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 25.0;
        }
    } else {
        // Existing bin: mild reward for keeping bin count low.
        score -= 5.0;
        // Penalize bins far from mean residual (outliers) to keep balance.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Early stream: encourage diversity of open bins (fill many partially).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
