pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * (1.0 + 2.0 * p * (1.0 - p) * 4.0 * p * (1.0 - p));

    let mut score = 1.5 * coupling + 0.35 * norm_pr * norm_pr * (1.0 + p);

    // Penalize very small unusable remnants, more so early in the stream
    let dead = (norm_pr > 0.0 && norm_pr < 0.1) as f64;
    score += dead * (1.0 - p) * 4.0;

    // Reward tight fits (small post_residual) with smooth falloff
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 0.8 * tightness * tightness * (1.0 + p);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - 0.5 * p);
    }

    // New-bin candidate: penalize early, allow late or when open bins are full
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 4.0 * (1.0 - p) * (1.0 - pressure) + 1.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else mild penalty
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 1.2 * (1.0 - (nx / cap) - norm_pr).abs().min(1.0);
        } else {
            score += 0.6 * (nx - pr) / cap;
        }
    }

    // Mild preference for bins with residuals near mean (balance)
    score += 0.15 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fractions.
    // Dead space classes: leftover <= 10 is "perfect" (hard to use anyway),
    // leftover in (10, 20] is still usable by small items, larger leftovers waste capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else {
        score += (post_residual - 30) as f64 * 0.15; // penalize large dead space
    }

    // Modulo / integer-division harmonic class of the residual:
    // residuals divisible by 10 pair naturally with common item sizes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size as f64) as u32;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0 * (10.0 / (1.0 + slack as f64 / 10.0));
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover becomes dead until future items.
        score += post * 0.05;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless this item is huge
    // or the stream is early and we want fresh capacity for future small items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // Opening a new bin is attractive for large items (they'd wreck a small residual)
        // and early in the stream.
        score += 35.0 - 30.0 * item_frac - 15.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize leftover space with non-linear shaping, harder late in stream.
    let mut score = pr as f64;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    // Dead-space avoidance: small unusable gaps heavily penalized (tiered).
    if post_residual > 0 && post_residual <= 3 {
        score -= 120.0 + 28.0 * progress;
    } else if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Perfect fit is ideal (stronger reward, progress-scaled).
    if post_residual == 0 {
        score -= 100.0 + 60.0 * progress;
    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    let fill = item_norm;
    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead: exact fit for next item is a big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 80.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (40.0 + 30.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 80.0;
            } else if slack <= 4.0 {
                score -= 60.0 - 8.0 * slack;
            } else if slack <= 15.0 {
                score -= 45.0 * (1.0 - progress);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 15.0 * (1.0 - progress);
            }
            // Reward leaving a second usable gap after the next item fits.
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            // Two-step chain: after next item, could the item after that also fit?
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && fill < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && fill < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.0 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mid-range residual band: discourage leaving 8-20 slack when many bins
    // are open (fragmentation source).
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
