            new_score -= 38.0 * (1.0 - progress);
        }
        // Borrowed: low mean residual, small item, late stream — consolidate first.
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        // Borrowed: large item mid/late stream fits fine in a fresh bin.
        if fill > 0.6 && progress > 0.5 {
            new_score -= 12.0 * fill;
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit the smallest plausible item are wasted.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 60.0 * (1.0 - progress);
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance pressure: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 6.0; // new bin better reserved for smaller future items
        }
    }

    // Mild preference for using bins with small residuals relative to mean.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
