pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            // next item fits; better the smaller the leftover after it
            let second_leftover = post_residual - next_item_size;
            score -= 25.0 - second_leftover as f64 * 0.3;
        } else {
            // next item does not fit here; penalize bins that leave awkward gaps
            score += 8.0;
        }
        // Exact fit now also strongly rewarded (bin closes)
        if post_residual == 0 {
            score -= 50.0;
        }
    } else {
        // No lookahead available: prefer tight fits
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare residual against mean residual: bins with below-average residual are
    // "tighter" and should absorb the item to consolidate fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Prefer keeping the number of open bins low; slight penalty as bins accumulate.
    score += open_bins_count as f64 * 0.3;

    // Early in the stream, be slightly more willing to open fresh bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or fit elsewhere is poor.
        score -= item_size as f64 * 0.35;
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: tiered residual scoring (borrowed from best), heavily rewarding tight fits.
    let mut score = pr;
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 190.0 + 28.0 * progress;
    } else if post_residual <= 10 {
        score -= 55.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Tightness reward: filling most of the bin is desirable, more so early.
    score -= item_norm * item_norm * 25.0 * (1.0 - 0.5 * progress);

    // Lookahead: exact fit for next item is a big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Reward leaving a second usable gap after the next item fits.
            if slack >= mean_residual.min(cap * 0.5) && slack > 0.0 {
                score -= 32.0 * (slack / cap);
            }
            // Two-step chain: after next item, could another item also fit?
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // Small post-next sliver: dead-space avoidance.
            let sliver = pr / cap;
            if sliver < 0.05 && sliver > 0.0 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
            // Dead-band shaping: small dead fraction penalized, mid chain rewarded.
            let dead = slack / cap;
            if dead > 0.0 && dead < 0.12 {
                score -= 20.0 * (0.12 - dead) * (1.0 + progress);
            } else if dead >= 0.12 && dead < 0.25 {
                score += 9.0 * (dead - 0.12) * (1.0 + progress);
            }
            // Chain exactness: post-next slack equals current item.
            if slack as u32 == item_size && item_norm < 0.3 {
                score -= 8.0 * (1.0 - progress);
            }
            // Small item fits into post-next slack.
            if item_norm < 0.25 && slack <= item_size as f64 {
                score -= 10.0 * (1.0 - progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            if nxt - pr <= 4.0 {
                score += 7.0 * (1.0 - progress);
            }
        }
        // Mid-range residual band with next item nearly fitting: discourage.
        if pr > 20.0 && pr < 45.0 && nxt > pr {
            score += 6.0 * (1.0 - progress);
        }
        if pr > 0.0 && nxt >= pr * 0.5 && nxt < pr {
            score -= 8.0 * (1.0 - progress);
        }
        if pr == 0.0 && nxt < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: only fitting open bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.0 * norm_pr;
    }

    // Prefer bins below mean residual (balanced spread).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Open-bin pressure.
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mid-range residual band: fragmentation source.
    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 9.0 + 6.0 * (1.0 - progress);
    }

    // New-bin candidate: sigmoid gate with refinements.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 215.0; // opening is necessary
        }
        if next_item_size > 60 {
            new_score -= 30.0; // reserve fresh capacity for large next item
        }
        if item_norm > 0.85 {
            new_score += 32.0; // very large item justifies a fresh bin
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            new_score += 15.0; // existing slack can serve next item; don't open
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 && mean_norm < 0.15 {
            new_score -= 20.0 * (1.0 - mean_norm / 0.15);
        }
        if pr > 0.0 && pr < 8.0 && next_item_size > pr {
            new_score -= 38.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            new_score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            new_score -= 12.0 * item_norm;
        }
        // Consolidation: many open bins with usable slack -> avoid opening.
        if open_bins_count > 6 && mean_norm > 0.25 && item_norm < 0.4 {
            new_score += 14.0 * (1.0 - progress);
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight_fit * tight_fit;

    // Perfect fit is excellent
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Lookahead: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; slight penalty proportional to leftover
        score += 3.0;
    }

    // Last chance: this is the only bin that fits; strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling already-open bins vs opening new ones:
    // new bin candidate has bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // penalize new bins, more when many bins are open or mean residual is high
        score += 20.0 + 1.5 * open_bins_count as f64 + 0.05 * mean_residual;
        // but if no open bin would be a good fit (item much smaller than residual),
        // soften: opening a fresh bin for tiny items on fat bins can be fine
        let spread = bin_residual as f64 - item_size as f64;
        if spread > 60.0 {
            score -= 15.0;
        }
    } else {
        // reward using open bins, especially ones below mean residual (consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream be conservative with new bins (future items
    // can use big residuals); late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64 * 0.15);

    // Mild preference for placing into bins whose residual is close to item size
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

