            if item_norm > 0.7 && mean_norm < 0.10 {
                score -= 18.0 * item_norm * (1.0 - progress);
            }
            // NEW: penalize opening a fresh bin when the resulting dead space
            // (capacity - item) exceeds the mean residual surplus, i.e. when
            // existing open bins could absorb the item with less waste overall.
            let new_dead = cap - item_size as f64;
            if new_dead > mean_residual * 1.1 && fitting_bins_count > 0 && item_norm < 0.6 {
