                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                // NEW: reward near-perfect two-item chains in open bins —
                // placing item + next item leaves a tiny sliver.
                let chain_slack = pr - nxt - item_size as f64;
                if chain_slack >= 0.0 && chain_slack <= 3.0 {
                    score -= 13.0 * (1.0 - chain_slack / 3.0) * (1.0 - 0.5 * progress);
                }
            }
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr >= (next_item_size as f64) && (pr - next_item_size as f64) < 1.0 {
            score -= 4.0 * (1.0 - progress);
        }
