            let overshoot = (next_item_size as f64) - pr;
            if overshoot > 6.0 && overshoot < 18.0 {
                score += 5.0 * (1.0 - (overshoot - 6.0) / 12.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 25.0 * progress;
    } else if post_residual < 10 {
        score -= 50.0 + 30.0 * progress;
    } else if post_residual < 25 {
        score -= 8.0 + 12.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * (pr / cap) * (1.0 + progress);
    }

    // 2-step lookahead with graded slack rewards
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 650.0;
            } else if slack <= 4.0 {
                score -= 420.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 230.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                score -= 40.0 * (1.0 - slack / cap);
            }
            // two-item chain: item + next both fit leaving tiny residue
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_size < 45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (60.0 + 45.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            if nxt - pr <= 4.0 {
                score += 7.0 * (1.0 - progress);
            }
        }
