        if norm_pr > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * norm_pr * (1.0 - progress);
        }
        if norm_pr > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * norm_pr * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && norm_pr > 0.15 && norm_pr < 0.35 {
            score += 5.0 * (norm_pr - 0.15) / 0.20 * (1.0 - progress);
        }
        if norm_pr > 0.3 && item_norm > norm_pr - 0.05 && item_norm < norm_pr {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead: chain bonus scaled by leftover waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // two-item lookahead
            let two_slack = pr - nxt - (item_size as f64);
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            // triple-chain
            let tri_slack = pr - nxt - 2.0 * (item_size as f64);
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // quad-chain
            let quad_slack = pr - nxt - 3.0 * (item_size as f64);
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt > pr && nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
        }
    }

    // Penalize small dead space
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 12.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 260.0;
    }

    // Waste-aware urgency
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // Dead-space-ratio urgency
    if bin_residual != bin_capacity {
        let usable_floor = 0.5 * (mean_residual.max(8.0));
        if pr > 0.0 && pr < usable_floor {
            score += 5.0 * (1.0 - pr / usable_floor) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW-BIN CANDIDATE
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        // refuse new bin when mean residual nearly equals item (snug fit elsewhere)
        if fitting_bins_count >= 1 && mean_norm > 0.01 && (mean_residual - item_size as f64).abs() < 6.0 {
            score += 26.0 * (1.0 - progress);
        }
        // allow new bin late when residuals are scattered
        if nxt_f > 0.0 && progress > 0.7
            && (mean_residual - nxt_f).abs() > 15.0
            && (mean_residual - item_size as f64).abs() > 15.0 {
            score -= 14.0 * (progress - 0.7) / 0.3;
        }
        // NEW: block new bin when many bins fit and item is small (consolidation)
        if fitting_bins_count >= 2 && item_norm < 0.25 {
            score += 20.0 * (1.0 - progress);
        }
    } else {
        // Open-bin refinements
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
            }
        }
        // dead-space penalty when leftover cannot fit next item
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        if next_item_size > 0 && pr >= (next_item_size as f64) && (pr - next_item_size as f64) < 1.0 {
            score -= 4.0 * (1.0 - progress);
        }
        // stranded-residual trap penalty
        if post_residual > 0 {
            let trap_lo = 11.0;
            let trap_hi = 24.0;
            if post_residual >= trap_lo && post_residual <= trap_hi {
                let depth = 1.0 - ((post_residual as f64 - trap_lo) / (trap_hi - trap_lo)).abs();
                score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        // NEW: prefer bins whose post-residual can host a mean-sized future item
        if pr > 0.0 && pr >= mean_residual {
            score -= 3.0 * (pr / (mean_residual.max(1.0))).min(2.0) * (1.0 - progress);
        }
        // NEW: combine fine-grained fit with lookahead — reward bins where item + next
        // item fit with minimal combined slack, weighted by fitting scarcity
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let comb_slack = pr - next_item_size as f64;
            let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
            if comb_slack <= 8.0 {
                score -= 12.0 * (1.0 - comb_slack / 8.0) * (0.5 + scarcity);
            }
        }
    }

    // Consolidation pressure
    score += 2.0 * open_bins_count as f64;

    score
}

