    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead: chain bonus scaled by leftover waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - (item_size as f64);
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * (item_size as f64);
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * (item_size as f64);
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt > pr && nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
        }
    }

    // Penalize small dead space (softened to avoid thrash)
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 260.0;
    }

    // Waste-aware urgency
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // Dead-space-ratio urgency
    if bin_residual != bin_capacity {
        let usable_floor = 0.5 * (mean_residual.max(8.0));
        if pr > 0.0 && pr < usable_floor {
            score += 5.0 * (1.0 - pr / usable_floor) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && progress > 0.7
            && (mean_residual - nxt_f).abs() > 15.0
            && (mean_residual - item_size as f64).abs() > 15.0 {
            score -= 14.0 * (progress - 0.7) / 0.3;
        }
        // NEW: stronger block when mean residual closely matches item (snug fit exists elsewhere)
        if fitting_bins_count >= 1 && mean_norm > 0.01 && (mean_residual - item_size as f64).abs() < 6.0 {
            score += 30.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        if next_item_size > 0 && pr >= (next_item_size as f64) && (pr - next_item_size as f64) < 1.0 {
            score -= 4.0 * (1.0 - progress);
        }
        // stranded-residual trap zone
        if post_residual > 0 {
            let trap_lo = 11.0;
            let trap_hi = 24.0;
            if post_residual >= trap_lo && post_residual <= trap_hi {
                let depth = 1.0 - ((post_residual as f64 - trap_lo) / (trap_hi - trap_lo)).abs();
                score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        // NEW (from best): extra dead-space pressure when several bins fit
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        // NEW: reward bins whose post-residual still hosts mean-sized future item
        if pr > 0.0 && pr >= mean_residual {
            score -= 3.0 * (pr / (mean_residual.max(1.0))).min(2.0) * (1.0 - progress);
        }
    }

    // Consolidation pressure
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead: chain bonus scaled by leftover waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // two-item lookahead: next item + a small follow-up fits
            let two_slack = pr - nxt - (item_size as f64);
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            // triple-chain: residual can absorb next + item + small margin
            let tri_slack = pr - nxt - 2.0 * (item_size as f64);
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // quad-chain: four-way stack when items are tiny (borrowed from best)
            let quad_slack = pr - nxt - 3.0 * (item_size as f64);
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt > pr && nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
        }
    }

    // Penalize small dead space (softened to avoid thrash)
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 260.0;
    }

    // Waste-aware urgency
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // Dead-space-ratio urgency: penalize mid-range residual traps
    if bin_residual != bin_capacity {
        let usable_floor = 0.5 * (mean_residual.max(8.0));
        if pr > 0.0 && pr < usable_floor {
            score += 5.0 * (1.0 - pr / usable_floor) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // New-bin candidate: pressure-gated
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        // refuse new bin when mean residual nearly equals the item (snug fit elsewhere)
        if fitting_bins_count >= 1 && mean_norm > 0.01 && (mean_residual - item_size as f64).abs() < 6.0 {
            score += 26.0 * (1.0 - progress);
        }
        // huge item with next item also large: fresh bin helps chain
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        // late-stream fragmentation: allow new bins when residuals scattered
        if nxt_f > 0.0 && progress > 0.7
            && (mean_residual - nxt_f).abs() > 15.0
            && (mean_residual - item_size as f64).abs() > 15.0 {
            score -= 14.0 * (progress - 0.7) / 0.3;
        }
    } else {
        // Open-bin refinements: keep residual alive for next item
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
            }
        }
        // dead-space penalty when leftover cannot fit the next item
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        if next_item_size > 0 && pr >= (next_item_size as f64) && (pr - next_item_size as f64) < 1.0 {
            score -= 4.0 * (1.0 - progress);
        }
        // stranded-residual trap band
        if post_residual > 0 {
            let trap_lo = 11.0;
            let trap_hi = 24.0;
            if post_residual >= trap_lo && post_residual <= trap_hi {
                let depth = 1.0 - ((post_residual as f64 - trap_lo) / (trap_hi - trap_lo)).abs();
                score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        // heavy dead-space penalty when other bins can also host the item
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        // mid dead-space with next item blocked
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        // item exactly plugs the dead space: reward
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        // NEW: prefer bins whose post-residual still hosts mean-sized future items
        if pr > 0.0 && pr >= mean_residual {
            score -= 3.0 * (pr / (mean_residual.max(1.0))).min(2.0) * (1.0 - progress);
        }
    }

    // Consolidation pressure
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    let mut score = pr;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 160.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += miss * (3.0 + 2.0 * progress);
            }
        } else {
            let slack = pr - nxt;
            if slack <= 4.0 {
                score -= 380.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 200.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 20.0 * (1.0 - progress);
            }
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 34.0 * (after / cap);
            }
            // Multi-step chain lookahead: item + next + more copies fill residual exactly.
            let it = item_size as f64;
            let two_slack = pr - nxt - it;
            if two_slack >= 0.0 && two_slack <= 5.0 && fill < 0.45 {
                score -= 20.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && fill < 0.35 {
                score -= 7.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            let tri_slack = pr - nxt - 2.0 * it;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && fill < 0.20 {
                score -= 12.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * it;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && fill < 0.12 && progress < 0.7 {
                score -= 9.0 * (1.0 - quad_slack / 2.0);
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if fill > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        new_score += 25.0 * progress * (1.0 - fill);
        // Chain-fit bonus for new bin: item + next nearly fills capacity.
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let rem = cap - item_size as f64 - nxt_f;
            if rem >= 0.0 && rem <= 4.0 {
                new_score -= 30.0 * (1.0 - rem / 4.0) * (1.0 - progress);
            }
        }
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
            let sliver = pr / cap;
            if sliver < 0.05 && sliver > 0.0 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        // Dead-space trap: penalize residuals next item cannot touch.
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.3 && fill > dead_frac - 0.05 && fill < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Tight-fit tiers (borrowed structure, retuned constants).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 220.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 7.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 6.0 * progress;
    } else {
        score += 2.5 * (pr / cap) * (1.0 + progress);
    }

    // --- 2-step lookahead: chain with next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 600.0;
            } else if slack <= 4.0 {
                score -= 420.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 220.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                score -= 40.0 * (1.0 - slack / cap);
            }
            // Multi-item chain: item_size multiples after next item.
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 18.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 7.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (60.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
        }
    }

    // Small sliver penalty: residuals under 10 that next item cannot use are waste.
    if post_residual > 0 && post_residual < 10 && (next_item_size as u32 > post_residual) {
        score += 90.0 * (1.0 - progress);
    }

    // Mean-residual deviation: prefer bins near the mean (balanced filling).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Last-chance logic: if this is the only fitting open bin, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0;
    } else if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: new bin necessary
        }
        // Big items justify fresh bins; small items should not open bins.
        if item_norm > 0.85 {
            score += 32.0;
        }
        if item_norm > 0.55 && fitting_bins_count >= 1 {
            score += 14.0 * item_norm;
        }
        // If next item is large, a fresh bin can host it after this item.
        if next_item_size > 60 {
            score -= 30.0;
        }
        // If mean residual can still host the next item, avoid new bin.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Tight-fit ladder: strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // graded by the slack left after placing it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Multi-item lookahead: can the leftover host next + another copy?
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
        }
    } else {
        // Last item: pack as tightly as possible.
        score -= 0.5 * item_norm;
    }

    // Penalize tiny useless slivers early (they can't host future items).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins that stand out as tight.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Last-chance bonus: if this is the only fitting open bin, prefer it strongly.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: opening a bin should be rare — only when open bins
    // are nearly full on average or the item fits nowhere else.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
    } else {
        // Open-bin refinements: discourage leaving awkward mid-range leftovers.
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr > nxt {
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
            } else {
                let dead_frac = norm_pr;
                if dead_frac > 0.25 {
                    score += 11.0 * dead_frac * (1.0 - progress);
                }
            }
        }
        // Trap zone: leftovers in 11..24 are hard to fill later.
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((post_residual as f64 - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if dead_space_waste(post_residual, next_item_size) && norm_pr > 0.3 {
            score += 14.0 * norm_pr * (1.0 - 0.4 * progress);
        }
    }

    score
}

fn dead_space_waste(post_residual: u32, next_item_size: u32) -> bool {
    next_item_size > 0 && post_residual > 0 && (next_item_size as u64) > (post_residual as u64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
