        // sliver in an existing bin (dead-space avoidance at open decision).
        if nxt_f > 0.0 && (bin_residual as f64 - item_size as f64) >= nxt_f {
            let would_remain = bin_residual as f64 - item_size as f64 - nxt_f;
            if would_remain <= 3.0 {
                score += 60.0 * (1.0 - would_remain / 3.0) * (1.0 - 0.4 * progress);
            }
        }
        // NEW: opening a fresh bin for a tiny item early wastes capacity.
        if item_norm < 0.10 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.10) * (1.0 - 0.5 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
