            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // NEW: dead-space refinement — bins whose residual cannot hold the next item
        // but could hold a small follow-up (mean-residual sized) are less attractive
        // early, but become acceptable sinks late in the stream.
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any future item
    // (min plausible item ~1..=100, but assume small useful threshold) are dead weight.
    // Penalize unusable gaps super-linearly.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit is gold
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Open bins pressure: with many open bins, prefer consolidation into existing bins
    // (penalize opening new bins implicitly by making existing bins more attractive).
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only open
    // a new bin when existing placements look genuinely bad (high post_residual waste).
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.15;
        // Early in the stream, opening bins is cheaper (no consolidation possible anyway).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
    }

    // Mean residual coupling: if average residual is small, existing bins are precious;
    // avoid fragmenting them with mediocre fits.
    if mean_residual < 25.0 && post_residual > 0 {
        score += (25.0 - mean_residual) * 0.3;
    }

    score
}

