            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            // reward bins whose post-residual remains reusable by the mean-sized
            // upcoming demand, coupling lookahead with global residual statistics.
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            // penalize near-misses harder when other bins exist to absorb the item,
            // pushing the stream toward bins that actually close cleanly.
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // dead space lookahead: penalize residual space that cannot host the next item.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        let waste = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste * (0.4 + 0.6 * (1.0 - progress));
        if item_norm > 0.8 {
            score -= 12.0 * waste;
        }
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        // opening a fresh bin is justified when the item nearly equals the
        // capacity (perfect single-item bin) and few bins can host it.
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // prefer opening a fresh bin for large items early when mean
        // residual across open bins is too tight to ever host such items.
        if item_norm > 0.55 && mean_norm < item_norm * 0.6 && progress < 0.75 {
            score -= 18.0 * item_norm * (1.0 - progress);
        }
        // if next item is medium and mean residual is within a hair of it,
        // opening a new bin preserves the tight fits elsewhere.
        if nxt_f > 0.0 && nxt_f > mean_residual && nxt_f - mean_residual < 6.0 && item_norm < 0.3 {
            score += 10.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                // reward leaving a residual that matches the mean residual
                // of other bins, keeping a homogeneous pool of slivers.
                let pool = (pr - mean_residual).abs() / cap;
                if pool < 0.03 {
                    score -= 5.0 * (1.0 - pool / 0.03) * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // dead-space refinement — bins whose residual cannot hold the next item
        // but could hold a small follow-up (mean-residual sized) are less attractive
        // early, but become acceptable sinks late in the stream.
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // penalize bins whose post residual exceeds the next item by a
        // large margin when many bins compete — spread fills instead.
        if next_item_size > 0 && pr > (next_item_size as f64) * 2.5 && fitting_bins_count > 2 {
            score += 4.0 * (pr / cap) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            // REFINED: exact post-fit match against the mean upcoming demand is a
            // strong signal the bin closes after the next item — tighten the band.
            if mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 && pr >= nxt {
                score -= 9.0 * (1.0 - (pr - mean_residual).abs() / 3.0) * (1.0 - 0.3 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: fresh-bin cost should scale with how much residual mass is stranded
        // across open bins — with many near-empty bins, opening another is wasteful.
        let stranded = if open_bins_count > 0 {
            (mean_residual * open_bins_count as f64) / cap
        } else {
            0.0
        };
        if stranded > 1.5 && item_norm < 0.5 {
            score += 10.0 * (stranded - 1.5).min(3.0) * (1.0 - item_norm);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space refinement — a bin whose residual exactly equals the item
        // (perfect closure) is heavily favored even in the "else" branch region.
        if pr == item_size as f64 && pr > 0.0 {
            score -= 12.0 * (1.0 - 0.5 * progress);
        }
        // NEW: penalize bins that leave a residual slightly below the mean demand —
        // these strand space that a typical upcoming item could have used.
        if mean_residual > 0.0 && pr > 0.0 && pr < mean_residual && mean_residual - pr < 0.06 * cap {
            score += 5.0 * (1.0 - (mean_residual - pr) / (0.06 * cap)) * (1.0 - 0.4 * progress);
        }
    }

    score
}

