            && mean_residual > 0.0 && pr >= mean_residual {
            let excess = (pr - mean_residual) / cap;
            let late_bonus = if progress > 0.65 {
                6.0 + 8.0 * (1.0 - excess.min(1.0))
            } else {
                -4.0 - 6.0 * excess.min(1.0)
            };
            score += late_bonus * dead_frac;
        }
        // NEW: penalize bins whose residual is stranded above the next item but
        // just below a plausible two-item chain (item + mean residual), which
        // wastes compaction opportunities mid-stream.
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= item_size as f64 + mean_residual {
            score += 7.0 * (1.0 - progress) * dead_frac;
        }
    }

    score
}

