        score -= 40.0 + 30.0 * progress;
    } else if post_residual < 25 {
        score -= 5.0 + 12.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 600.0;
            } else if slack <= 4.0 {
                score -= 420.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 220.0;
            } else if slack <= 40.0 {
                score -= 90.0 * (1.0 - slack / cap);
            } else {
                score -= 40.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
