            }
            // REFINED: exact-chain lookahead — bins that can host the next item AND
            // then close to zero residual are prime targets; scale the reward with
            // stream progress so late bins chase perfect closures harder.
            let chain_slack = pr - nxt - item_size as f64;
            if chain_slack == 0.0 && item_norm < 0.55 {
                score -= 24.0 * (0.5 + 0.5 * progress);
