            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // REFINED: dead-space sink detection — a bin whose residual equals the
        // mean upcoming demand exactly (within 2 units) is a guaranteed future
        // closer; reward it, especially once the stream is halfway through.
        if mean_residual > 0.0 && pr > 0.0 && (pr - mean_residual).abs() < 2.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 9.0 * (0.5 + 0.5 * progress);
        }
