        // dead space can't host either the next item or a mean-sized item, steer
        // the stream away from spreading residuals across too many bins.
        if open_bins_count > 8 && dead_frac > 0.18 && next_item_size > 0
            && (next_item_size as f64) > pr
            && (mean_residual <= 0.0 || pr < mean_residual) {
            score += 5.0 * dead_frac * (1.0 - progress);
        }
    }

    score
}

