            let d = (pr - mean_residual).abs();
            if d <= 5.0 {
                score -= 8.0 * (1.0 - d / 5.0) * (1.0 - 0.4 * progress)
                    * (1.0 + 0.03 * (open_bins_count as f64).min(20.0));
            }
        }
    }

    score
}

