    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;
    let next = next_item_size as f64;

    let mut score = pr;

    // smooth non-linear coupling: residual waste penalized more as stream progresses
    let waste_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += 40.0 * waste_coupling * cap / 100.0;

    // reward tight fits via smooth exponential-like term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (1.0 + progress);

    // lookahead: reward leaving room for the next item (smooth interaction)
    if next > 0.0 {
        let next_norm = next / cap;
        let gap = (norm_pr - next_norm).abs();
        score -= 15.0 * (1.0 - gap.min(1.0)) * (1.0 + 2.0 * progress);
    }

    // last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // mild penalty for bins below mean residual (fragmented bins), smooth in progress
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - 0.5 * progress) - 4.0 * dev;

    // discourage opening new bins when many are open and fit exists
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_c * (0.5 + progress);
    }

    // tiny diversity term: polynomial in open bins and progress
    score += 0.5 * open_c * progress * progress;

    score
}

