        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // REFINED: fresh-bin threshold now scales with stream position — early on
        // opening a bin for a large item is cheaper (many items left to fill it),
        // late it must be near-perfect.
        let open_gate = 0.80 - 0.15 * progress;
        if item_norm > open_gate && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress) + 8.0 * (item_norm - open_gate);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // REFINED: quantify dead space against the *mean* upcoming demand rather
        // than only the next item — bins whose leftover can't even hold one
        // mean-sized item are penalized more sharply mid-stream.
        if dead_frac > 0.25 && mean_residual > 0.0 && pr > 0.0 && pr < mean_residual && progress < 0.85 {
            score += 9.0 * (mean_residual - pr) / cap * (1.0 - progress);
        }
        // REFINED: prefer bins whose residual is an exact multiple of the mean
        // demand — they will close cleanly over subsequent placements.
        if mean_residual > 1.0 && pr > 0.0 && pr >= mean_residual && dead_frac > 0.15 {
            let k = (pr / mean_residual).round();
            let off = (pr - k * mean_residual).abs();
            if off <= 2.0 && k >= 1.0 {
                score -= 8.0 * (1.0 - off / 2.0) * (1.0 - 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let nxt = next_item_size as f64;
    let mut score = pr;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead with graded slack rewards
    if next_item_size > 0 {
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Multi-step chain checks
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            // Reward residuals matching upcoming mean-sized demand
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // Dead-space penalty for tiny residuals
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins near the pack's typical slack
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Last-chance consolidation
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // NEW-BIN CANDIDATE logic: adaptive pressure gate
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if nxt > 60.0 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if nxt > 0.0 && mean_residual >= nxt && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        if nxt > 0.0 && mean_norm > 0.02 && (mean_residual - nxt).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt > 0.0 && (mean_residual - nxt).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt > 0.0 && item_norm > 0.9 && nxt <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt > 0.0 && nxt >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt > 0.0 && nxt > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        // Fresh bin justified for near-capacity items when next item can follow
        if item_norm > 0.95 && nxt > 0.0 && nxt >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
    } else {
        // Trap zone: residuals that tend to strand space
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && nxt > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo && post_residual <= trap_hi {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && nxt > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && nxt > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && nxt > pr {
            let wasted = dead_frac - (nxt / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // Dead-space refinement: mean-residual-sized follow-ups
        if dead_frac > 0.2 && next_item_size > 0 && nxt > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: mid-stream, prefer bins whose post-residual still admits the mean
        // item size — keeps residuals reusable rather than stranding them.
        if mean_residual > 0.0 && pr > 0.0 && pr >= mean_residual
            && pr - mean_residual <= 6.0 && progress > 0.3 && progress < 0.8 {
            score -= 5.0 * (1.0 - (pr - mean_residual) / 6.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // ---- base: post-placement residual (lower is better) ----
    let mut score = pr;

    // ---- harmonic class of post_residual (modulo arithmetic on capacity fractions) ----
    // Residuals that are "aligned" with the item-size granularity (multiples of 10)
    // are statistically reusable by future items; reward them.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 6.0,
        5 => 3.0,
        1 | 9 => 1.5,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: which "harmonic band" does the residual fall in?
    // band 0: pr <= 10 (nearly perfect), band 1: <= 25, band 2: <= 50, band 3: > 50
    let band = post_residual / 25; // 0..=4
    score -= match band {
        0 => 12.0,
        1 => 6.0,
        2 => 0.0,
        _ => 4.0, // large dead space mildly penalized extra
    };

    // ---- lookahead coupling (k=2) ----
    if nx > 0.0 {
        if nx <= pr && pr > 0.0 {
            // next item can also be chained into this bin: strong reward,
            // scaled by how much of the residual the next item consumes.
            let fill_ratio = nx / pr.max(1.0);
            score -= 8.0 + 6.0 * fill_ratio;
        } else if nx > pr {
            // residual too small for the next item: dead-space penalty grows
            // with residual size relative to capacity fraction.
            score += 0.25 * pr * (pr / cap);
        }
    }

    // ---- last-chance bin: if this is the ONLY bin that fits, strongly favor it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // ---- new-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin costs a fixed overhead plus the natural residual.
        // For small items this is high (loses to any decent fit);
        // for large items it can win over terrible fits in open bins.
        score = pr + 0.25 * cap - class_bonus;
        // If nothing else fits at all, new bin must be chosen.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, slightly prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    } else {
        // mild preference for bins already tighter than the mean residual
        let mr = mean_residual.max(0.0);
        if pr < mr {
            score -= 2.0 * (1.0 - pr / (mr + 1.0));
        }
        // crowded fleet: reward using existing bins rather than spreading
        score -= 0.05 * open_bins_count as f64;
    }

    // ---- item-size harmonic interplay: exact complement fits are golden ----
    if bin_capacity % item_size.max(1) == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit: always best
    }

    score
}

