            let used_frac = 1.0 - (bin_residual as f64 / cap);
            if miss <= 8.0 && used_frac > 0.6 {
                score += (8.0 - miss) * 3.5 * used_frac * (1.0 - 0.4 * progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: opening a fresh bin for a large item whose complement (cap - item)
        // matches the mean residual creates a perfectly reusable leftover —
        // strongly favor this pairing.
        let complement = cap - item_size as f64;
        if item_norm > 0.4 && mean_residual > 0.0 && (complement - mean_residual).abs() < 3.0 {
            score -= 16.0 * (1.0 - 0.5 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space refinement — if placing this item leaves a residual that
        // exactly matches the mean residual, the bin becomes a reusable template;
        // reward this strongly early, fade it out late.
        if pr > 0.0 && mean_residual > 0.0 && (pr - mean_residual).abs() < 2.0 && dead_frac > 0.1 {
            score -= 11.0 * (1.0 - progress) * (1.0 - dead_frac);
        }
        // NEW: penalize bins whose post-residual is stranded between typical item
        // sizes (too big to close, too small for the mean item) — classic waste.
        if pr > 0.0 && mean_residual > 0.0 && pr < mean_residual && dead_frac > 0.08 && fitting_bins_count > 1 {
            score += 8.0 * dead_frac * (1.0 - pr / mean_residual.max(1.0)) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..10) are pure waste -> heavy penalty.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 500.0 + (min_item - post_residual as f64) * 50.0;
    }

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize moderate "unusable gap" zone: post_residual in [1, 15)
    // is likely dead space even if >= min item size.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // rather than fragmenting; also penalize when this is the only fitting bin.
    score += open_bins_count as f64 * 3.0;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0; // last-chance bin: strongly prefer using it
    }

    // New-bin candidate handling: only attractive if current bin fit is bad
    // (large post_residual waste relative to mean residual).
    if bin_residual == bin_capacity {
        score += 120.0;
        score -= mean_residual * 0.3;
        if post_residual >= item_size as f64 + next_item_size as f64 && next_item_size > 0 {
            score -= 60.0; // new bin can host item + next item
        }
    }

    // Deviation from mean residual: prefer bins whose post_residual stays
    // close to the fleet mean (balanced residual profile).
    score += (post_residual as f64 - mean_residual).abs() * 0.4;

    // Slight stream-progression pressure: later in the stream, waste hurts more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
