                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                // NEW: prefer bins whose post-residual after placing the item matches
