        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space sink refinement — late in the stream, bins whose dead space
        // exactly absorbs the item (item fills it with <=2 left) are excellent sinks;
        // reward that precisely instead of only penalizing generic dead space.
        if progress > 0.5 && dead_frac > 0.15 && item_norm >= dead_frac - 0.02 && item_norm <= dead_frac {
            score -= 12.0 * (1.0 - progress) * (fitting_bins_count.min(4) as f64).max(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size, penalize mismatch gap.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits but leaves slack: penalize proportional to slack.
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here: penalize the shortfall.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
        // Small continuous nudge toward exact matching.
        score += 0.15 * gap;
    } else {
        // Last item: strongly prefer minimal residual.
        score -= 40.0;
    }

    // Relative-to-mean coupling: bins with residual far from mean are
    // penalized slightly, encouraging balanced residual profiles.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a
    // tight fit (post_residual small) — penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If lookahead suggests a very tight fit exists elsewhere, keep new bin unattractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
