        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space sink detection — a bin whose residual is a near-exact
        // multiple of the mean residual acts as a natural absorber for the
        // average upcoming demand; reward it, especially mid-stream.
        if mean_residual > 1.0 && dead_frac > 0.15 {
            let k = (pr / mean_residual).floor();
            if k >= 1.0 {
                let rem = pr - k * mean_residual;
                if rem < 3.0 {
                    score -= 6.0 * (1.0 - rem / 3.0) * (0.4 + 0.6 * (1.0 - progress));
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    } else if post_residual > 50 {
        // Large dead space: penalize, scaled by how much room is wasted.
        score += 0.15 * (post_residual as f64 - 50.0);
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it fills the leftover.
            score -= 5.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap that is nearly the next item's size.
            let gap_waste = post_residual as f64 - next_item_size as f64;
            if gap_waste < 10.0 && gap_waste >= 0.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let mut new_bin_penalty = 18.0 + 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bins is wasteful.
        new_bin_penalty += 0.1 * mean_residual;
        // If few bins fit the item, opening a new bin is less bad.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for bins with smaller residuals when many bins are open (consolidation).
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Time-horizon coupling: early in the stream, be more conservative (prefer filling existing bins).
    let horizon = step_index as f64 / (total_items as f64).max(1.0);
    score -= 6.0 * horizon * tightness;

    score
}

