        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // MUTATION: late-stream consolidation — when few bins fit and the residual
        // can host the item plus a small follow-up, tighten preference to avoid
        // opening new bins near the end of the stream.
        if progress > 0.6 && fitting_bins_count <= 2 && next_item_size > 0 && pr >= (next_item_size as f64) {
            score -= 12.0 * (1.0 - dead_frac) * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them more.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * norm_pr;

    // Tight-fit reward: quadratic bonus for near-perfect fills
    let tightness = 1.0 - norm_pr;
    score -= 0.8 * tightness * tightness * tightness;

    // Penalize residuals that cannot fit the next item (smooth via ratio)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 0.5 * gap * gap * cap;
        } else {
            let slack = (pr - nxt) / cap;
            score -= 0.2 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    // Mild pressure to consolidate when many bins are open
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 0.3 * open_norm * norm_pr;

    // Encourage matching the mean residual state (smooth coupling)
    let mean_norm = mean_residual / cap;
    score += 0.15 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // New-bin candidate: make it attractive only when item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score = 2.5 - 1.5 * fill_ratio * fill_ratio;
    }

    score
}

