        }
    }

    // Reward near-perfect fits (waste <= 5) strongly.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Encourage matching residual to the lookahead item: if the next item
    // fits exactly into post_residual, this placement sets up a chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // mild bonus: next item still fits
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here afterwards
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer
    // using it rather than opening a new bin (penalize alternatives less).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items into
    // fresh bins; favor consolidating into already-open bins.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but relax late in the stream when consolidation is less useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += open_pressure * (1.0 - 0.5 * progress);
        // Only attractive if current item is huge relative to mean residual
        // (i.e., no good fit exists anywhere).
        let fit_quality = (bin_residual as f64 - item_size as f64) - mean_residual;
        if fit_quality < 0.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward proportional to how much better than average
        // this bin's residual is (tighter bins get priority).
        score -= (bin_residual as f64 - mean_residual) * 0.3;
        score -= open_pressure * 0.1;
    }

    // Slight preference for filling bins with larger residual first when
    // the item is small, to keep tight bins for tight items.
    if item_size <= 20 && bin_residual < bin_capacity {
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            // Reward bins whose post-residual remains reusable by the mean-sized
            // upcoming demand, coupled with global residual statistics.
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            // REFINE: prefer bins where the leftover after placing BOTH the current
            // item and the next one stays small — tight two-step packing chains.
            if two_slack >= 0.0 && two_slack < 8.0 && nxt >= 0.25 * cap {
                score -= 5.0 * (1.0 - two_slack / 8.0) * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
