    // can accommodate the next item (chained fit), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly equals next item size.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * chain_slack;
            if chain_slack == 0.0 {
                score -= 20.0; // perfect two-item pairing
            }
        } else {
            // Next item cannot follow; penalize proportionally to wasted lookahead.
            let gap = (next_item_size - post_residual.min(next_item_size)) as f64;
            score += 0.4 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // the current item is huge (poor fit anywhere else).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * big_item - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0; // fresh bin can chain the next item too
