        // large margin when many bins compete — spread fills instead.
        if next_item_size > 0 && pr > (next_item_size as f64) * 2.5 && fitting_bins_count > 2 {
            score += 4.0 * (pr / cap) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: quadratic in normalized post-residual (dead-space penalty grows super-linearly)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth cubic coupling with stream progress: later in stream, tolerate less waste
    score += (0.5 + progress) * norm_pr * norm_pr * norm_pr * cap;

    // Interaction: small post-residual is good, but only if it's a "snug" fit (post_residual small relative to item)
    let snug = 1.0 - norm_pr;
    score -= snug * snug * item * 10.0;

    // Lookahead: reward leaving room for the next item (smooth bell around exact fit)
    if nxt > 0.0 {
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 8.0).exp() * 6.0 * (1.0 - progress * 0.5);
        // Penalize post-residual that is uselessly small for the next item
        score += 4.0 * (nxt - pr).max(0.0) / cap * nxt;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is average (encourage consolidation)
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * norm_pr * (mean_residual / cap);

    // New-bin candidate: make empty bin attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        // neutral-ish baseline; poor fits in open bins will score higher via dead-space terms
        score = cap * 0.35 + 2.0 * (1.0 - progress) + (nxt.max(item)) * cap * 0.2;
    }

    score
}

