pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes modulo common item sizes.
    // Residuals divisible by small harmonics (e.g. %10, %20) are more reusable.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.8;                       // penalize non-aligned residuals
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;                            // reward half-capacity-aligned space
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;                            // quarter-capacity alignment
    }
    if post_residual == 0 {
        score -= 25.0;                           // perfect fit: best outcome
    }

    // Integer-division threshold classes on post_residual
    let q = post_residual / 10;                  // decile class
    score -= (q as f64) * 0.3;                   // mildly prefer larger usable leftovers
    if q >= 5 && q <= 7 {
        score -= 3.0;                            // sweet-spot residual (50-79): fits most items
    }

    // Lookahead harmonic coupling: can next item land exactly in the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;                       // guaranteed perfect follow-up
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score += (slack % 10) as f64 * 0.5;  // penalize awkward follow-up gaps
            if slack <= 10 { score -= 4.0; }     // tight follow-up fit is good
        } else {
            score += 4.0;                        // next item won't fit here: block risk
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad class
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && (post_residual % 10 != 0 || post_residual < 20);
        score += 30.0;                           // default: prefer existing bins
        if bad_fit && fitting_bins_count <= 2 {
            score -= 45.0;                       // open fresh bin on poor fits
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score -= 8.0;                        // fresh bin can host the next item better
        }
    }

    // Stream progression: tighten packing as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Congestion coupling: with many open bins, prefer bins below mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    score
}

