            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW (gen 97): fresh-bin justification when the item leaves a residual that
        // matches the mean residual closely (the residual will likely be reused),
        // but only early/mid stream when there is still demand to fill it.
        if nxt_f > 0.0 && mean_norm > 0.01 && (pr - mean_norm * cap).abs() < 3.0
            && item_norm > 0.3 && progress < 0.8 {
            score -= 9.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW (gen 97): dead-space refinement against the residual variance signal —
        // when the residual after placement is a small, "tight" leftover that no
        // plausible upcoming item (next or mean-sized) can use, penalize it more
        // strongly mid-stream; but near the end, tight leftovers are exactly what
        // we want, so the penalty flips off.
        if next_item_size > 0 && pr > 0.0 {
            let nxt = next_item_size as f64;
            let mean_safe = if mean_residual > 0.0 { mean_residual } else { nxt };
            let unusable = pr < nxt && pr < mean_safe && pr < 0.10 * cap;
            if unusable && progress < 0.85 {
                let tight = 1.0 - pr / (0.10 * cap);
                score += 8.0 * tight * (1.0 - progress);
            } else if unusable && progress >= 0.85 {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are "unusable"
    // (min item size 1, but small gaps rarely pair well) -> heavy penalty.
    if post_residual >= 1 && post_residual <= 12 {
        score += 40.0;
    } else if post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual but still usable).
    if post_residual > 12 && post_residual <= 30 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 15 {
        score -= 20.0;
    }
    // Penalize if next item cannot fit here but post_residual is still sizeable
    // (wasted potential).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 13 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow moderate slack.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Make the brand-new empty bin less attractive unless the fit is
    // genuinely poor in all open bins: new bin has post_residual = capacity - item,
    // which is large; add a fixed opening cost that tight fits can overcome.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is huge, a fresh bin is fine (avoid stranding big items).
        if item_size >= 60 {
            score -= 35.0;
        }
    }

    // Late in the stream, be slightly greedier (less slack tolerated).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Mild alignment with mean residual: prefer bins below mean residual
    // (filling the emptiest bins first when slack is high).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
