            if pair_slack >= 0.0 && pair_slack <= 8.0 && item_norm < 0.5 && fitting_bins_count > 1 {
                score -= 5.0 * (1.0 - pair_slack / 8.0) * (1.0 - 0.6 * progress);
            }
