        // follow-up item is tiny enough to share the fresh bin's leftover —
        // avoids fragmenting a half-full open bin for a near-capacity item.
        if item_norm > 0.75 && nxt_f > 0.0 && nxt_f <= cap - item_size as f64 && fitting_bins_count > 2 {
