        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space refinement — a bin whose dead space exactly matches
        // the mean residual is a good sink for upcoming small items; reward it
        // mildly, scaled by how far the dead space exceeds the next item.
        if dead_frac > 0.15 && next_item_size > 0 && mean_residual > 0.0
            && (dead_frac * cap - mean_residual).abs() < 3.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nxt = next_item_size as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Non-linear quadratic coupling of post_residual with stream progress:
    // late in the stream, dead space becomes increasingly costly.
    let dead_penalty = (post / cap).powi(2) * (1.0 + 3.0 * progress * progress);
    score += dead_penalty * cap;

    // Smooth cubic term: heavily penalize large residuals as stream matures.
    score += (post / cap).powi(3) * 20.0 * progress;

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that are "just barely" unusable (wasted slivers).
    if nxt > 0.0 {
        let usable = (nxt / cap - post / cap).max(0.0);
        score -= 6.0 * (-usable * 4.0).exp(); // reward if next item fits after this placement
        let sliver = (post / cap) * (1.0 - nxt / cap);
        score += 10.0 * sliver * (1.0 - sliver) * 4.0; // penalize awkward in-between residuals
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor. Penalize opening proportional to open bins count
    // and stream progress, with smooth sigmoid gating on item size.
    if bin_residual == bin_capacity {
        let tight = 1.0 - (item_size as f64 / cap);
        let gate = 1.0 / (1.0 + (-8.0 * (tight - 0.35)).exp()); // small items -> open bin is cheap
        score += (12.0 + 18.0 * progress) * (1.0 - gate) + open_bins_count as f64 * 2.0 * progress;
        score -= 5.0 * gate;
    }

    // Mild coupling with mean residual: prefer bins deviating below mean
    // (consolidate space into fewer bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    score
}

