        let waste = (next_item_size as f64 - pr) / cap;
        score += 20.0 * waste * (0.4 + 0.6 * (1.0 - progress));
        if item_norm > 0.8 {
            score -= 12.0 * waste;
        }
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        // fresh-bin justified when item nearly equals capacity and the next
        // item can still fit alongside it in the new bin.
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // prefer opening a fresh bin for large items early when mean residual
        // is too tight to ever host such items.
        if item_norm > 0.55 && mean_norm < item_norm * 0.6 && progress < 0.75 {
            score -= 18.0 * item_norm * (1.0 - progress);
        }
        // preserve tight fits elsewhere when the next item is a near-miss on the pool
        if nxt_f > 0.0 && nxt_f > mean_residual && nxt_f - mean_residual < 6.0 && item_norm < 0.3 {
            score += 10.0 * (1.0 - progress);
        }
        // NEW: avoid opening bins for tiny items when the pool has plenty of room
        if item_norm < 0.15 && mean_norm > 0.25 && fitting_bins_count > 2 {
            score += 26.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                // reward leaving a residual that matches the pool mean,
                // keeping a homogeneous set of slivers.
                let pool = (pr - mean_residual).abs() / cap;
                if pool < 0.03 {
                    score -= 5.0 * (1.0 - pool / 0.03) * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // dead-space refinement: bins that can't host the next item but could
        // host a mean-sized follow-up are acceptable sinks late in the stream.
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: spread fills — penalize bins whose post-residual dwarfs the next
        // item when many bins compete.
        if next_item_size > 0 && pr > (next_item_size as f64) * 2.5 && fitting_bins_count > 2 {
            score += 4.0 * (pr / cap) * (1.0 - progress);
        }
        // NEW: closing a bin exactly (post_residual tiny relative to item) is
        // gold — extra reward when item nearly equals residual.
        if (bin_residual as f64 - item_size as f64) <= 2.0 && item_norm > 0.3 {
            score -= 12.0 * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is small relative to capacity.
    let tight = 1.0 - (pr as f64) / cap;
    score -= 18.0 * tight.powi(4);

    // Perfect fit class.
    if pr == 0 {
        score -= 45.0;
    }

    // Harmonic modulo-10 class: residuals divisible by 10 pair well with
    // integer item sizes, keeping future divisibility options open.
    if pr % 10 == 0 && pr >= 10 {
        score -= 6.0;
    }
    // Very small dead space (< 10) is nearly unusable anyway; mild extra penalty
    // only when it is nonzero (a zero residual is already rewarded above).
    if pr > 0 && pr < 10 {
        score -= 8.0;
    }

    // Integer-division harmonic classes on post_residual (buckets of 20):
    // mid-range residuals (20..40) are the most reusable; tiny and huge are less so.
    let class = pr / 20;
    score -= match class {
        0 => 4.0,
        1 => 6.0,
        2 => 2.0,
        3 => 0.0,
        _ => 1.0,
    };

    // Lookahead coupling (k=2): reward if the next item fits exactly into the
    // post_residual; penalize if it clearly cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0 + 8.0 * (nxt / cap);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor
    // using it over opening a new bin (unless it would create huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the current mean residual (leave roomier bins open).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += 0.15 * diff;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            // Must open a bin: make it always win.
            score -= 200.0;
        } else {
            // Opening a new bin is only attractive when existing bins are
            // already quite full (low mean residual) or fits are poor.
            score += 12.0 + 0.25 * mean_residual;
            // Large items into a fresh bin are fine (post_residual small
            // already gets the tight-fit reward); discourage for small items.
            if item_size < 30 {
                score += 10.0;
            }
        }
    }

    // Mild stream-position effect: later in the stream, consolidation matters
    // more, so slightly favor reusing existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
