        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        // Fresh bin justified when the item nearly equals capacity (perfect
        // single-item bin) and few bins can host it; slightly stronger early.
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: open a fresh bin for large items when the mean residual can
        // still absorb the *next* item — avoids fragmenting a good open bin
        // with an oversized item that would strand its space.
        if nxt_f > 0.0 && item_norm > 0.45 && mean_residual >= nxt_f + item_size as f64
            && fitting_bins_count > 1 && progress < 0.5 {
            score -= 10.0 * item_norm * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
