            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: fresh-bin opening is justified when the item leaves a residual that
        // tightly matches the mean upcoming demand (post-residual lookahead).
        let fresh_res = cap - item_size as f64;
        if fresh_res > 0.0 && nxt_f > 0.0 && (fresh_res - nxt_f).abs() <= 3.0 {
