        // item is a tight multiple of the mean residual are preferred sinks,
        // reducing future dead space across the stream.
        if mean_residual > 0.0 && pr > 0.0 && pr > mean_residual {
            let k = (pr / mean_residual).round();
            let off = (pr - k * mean_residual) / cap;
            if k >= 1.0 && off < 0.03 {
                score -= 8.0 * (1.0 - off / 0.03) * (1.0 - 0.6 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: reward closeness of match
            score -= 80.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space the next item cannot use
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow new bin if item is large and residuals are fragmented
        if item_size as f64 > mean_residual {
            score -= 250.0;
        }
    }

    // Late in stream: consolidate, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

