            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        // NEW: prefer filling bins whose residual is exactly consumed by this
        // item plus a mean-sized follow-up, tightening residual compaction.
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * t;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr <= post_residual as f64 {
            // next item fits exactly-ish into the leftover: big reward
            let slack = (post_residual as f64 - nr) / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack);
        } else {
            // leftover too small for next item: penalize dead space proportional to waste
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 6.0 * (10.0 - waste); // nearly-full bin is fine, mild bonus handled above
                score -= 6.0 * (10.0 - waste); // net neutral, keep base
            } else {
                score += 0.05 * waste;
            }
        }
    }

    // Penalize opening a brand-new bin unless the item is large and open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 20.0 + 15.0 * item_frac;
        // If open bins are heavily fragmented (high mean residual), new bin is more attractive.
        new_bin_penalty -= 10.0 * (mean_residual / bin_capacity as f64);
        if fitting_bins_count == 0 {
