pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial decay of residual cost with stream progress:
    // later in the stream, wasting space is increasingly expensive.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward perfect-ish fits with smooth cubic term.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness.powi(3);

    // Lookahead coupling: if next item exactly fills post_residual, strong reward;
    // smooth bell-shaped coupling around the match.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (nx - pr).abs();
        let match_bonus = (-diff * diff / 50.0).exp() * 10.0;
        let usable = if nx <= pr { 1.0 } else { 0.3 };
        score -= match_bonus * usable;
    }

    // Last-chance bin: heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Penalize bins whose residual deviates far from the mean (fragmentation).
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: make it mildly attractive only when no bin fits well.
    if bin_residual == bin_capacity {
        let best_possible = (pr / cap) * 12.0;
        score = cap * 0.9 + best_possible - 6.0 * (1.0 - progress);
    }

    score
}

