        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // Refined dead-space lookahead: scale the late acceptance by how well
        // the residual matches the mean-sized follow-up demand instead of a
        // flat bonus, and widen the late phase slightly.
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let match_q = 1.0 - ((pr - mean_residual) / cap).min(1.0);
            let late_bonus = if progress > 0.6 { 4.0 + 6.0 * match_q } else { -4.0 + 2.0 * match_q };
            score += late_bonus * dead_frac;
        }
        // NEW: penalize bins whose residual is a "poison sliver" — just below
        // the mean residual so nothing mean-sized will ever land there, but
        // too large to ignore; strongest early when many alternatives exist.
        if mean_residual > 0.0 && pr > 4.0 && pr < mean_residual - 1.0
            && (mean_residual - pr) < 0.06 * cap && fitting_bins_count >= 2 {
            score += 8.0 * (1.0 - (mean_residual - pr) / (0.06 * cap)) * (1.0 - 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A post_residual below the minimum item size (1) is impossible here,
    // but gaps smaller than a "typical" item are likely dead space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 + item_size / 2 {
        score += 40.0 + (10 + item_size / 2 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to prefer consolidation.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 4.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.05;
        // Early in the stream, opening bins is cheaper; later, penalize more.
        score += progress * 10.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item cannot use the leftover gap: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Penalize residual far from mean (fragmentation signal).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

