pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residual too small to ever be useful (min item size 1, but
    // penalize small unusable leftovers relative to typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits after this placement: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 30.0 * (overshoot / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit style), penalize bins with unusually large residuals.
    if mean_residual > 0.0 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.5 * diff;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large item, many bins already open).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // Cheaper to open new bin when item is large relative to capacity.
        score -= 1.2 * item_size as f64;
        // Discourage hoarding many open bins.
        score += 3.0 * open_bins_count as f64;
        // If this is the only fitting option anyway, neutralize the base cost.
        if fitting_bins_count == 1 {
