        }
    } else {
        // Prefer already-open bins slightly to consolidate.
        score -= 10.0;
    }

    // Early in the stream, allow more liberal bin opening to build diverse
    // residual pools; later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 40.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

