    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residual after placement that likely can't host future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual > 0 {
        // dead-space penalty grows toward stream end (less time to fill it)
        score += (post_residual as f64 / bin_capacity as f64) * 6.0 * (0.5 + progress);
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into bins with below-mean residual (balance load).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
        // spread penalty when bin count is high relative to progress
        score += 0.02 * open_bins_count as f64 * progress;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (bin is empty) or late in the stream with fragmented open bins.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { (mean_residual / bin_capacity as f64).min(1.0) } else { 0.0 };
        let new_bin_bonus = 3.0 + 15.0 * fragmentation * (0.3 + progress);
        // if the item would leave a small residual in existing bins, opening fresh is fine
        score = post_residual as f64 + new_bin_bonus;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative: new bin is good
        }
    }

    score
}

