    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tight fits matter more; late, keep bins flexible.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize new-bin opening when open bins fit, scaled by residual waste.
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
    }

    // Dead-space penalty: post_residual too small for typical future items.
    if pr > 0.0 && pr < 10.0 {
        score += 20.0 * (10.0 - pr);
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild penalty when this bin's residual deviates from mean residual.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

