        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            // NEW: soften the near-miss penalty when this bin's residual is small
            // anyway — sacrificing a tiny residual is cheap even on a miss.
            if miss <= 4.0 && norm_pr < 0.08 {
                score -= (4.0 - miss).min(2.0) * 7.0 * (1.0 - progress);
