            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space grading — bins whose residual is a multiple of the mean
        // residual (likely to be exactly consumed by upcoming demand) are preferred
        // over bins with awkward fractional dead space.
        if dead_frac > 0.15 && mean_residual > 1.0 {
            let k = (pr / mean_residual).round();
            if k >= 1.0 {
                let fit_err = (pr - k * mean_residual) / cap;
                score -= 8.0 * (1.0 - (fit_err.abs() / 0.03).min(1.0)) * (1.0 - 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual >= 60 {
            score -= 10.0; // big item opening a fresh bin is fine
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 4.0;
    }

    // Slight preference for bins with below-mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

