            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space coupling with the next item — if placing the item leaves a
        // residual that exactly absorbs the mean upcoming size, tighten the bin.
        if dead_frac > 0.18 && mean_residual > 1.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 12.0 * (1.0 - (pr - mean_residual).abs() / 3.0) * (1.0 - 0.5 * progress);
        }
        // NEW: penalize bins that would strand a residual just below the next item
        // size by more than a hair — a common dead-space generator.
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && (next_item_size as f64 - pr) < 8.0 && fitting_bins_count > 1 {
            score += (8.0 - (next_item_size as f64 - pr)) * 2.5 * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize leaving dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 50.0;
        } else if next <= post_residual as f64 {
            score -= 10.0 * (1.0 - (post_residual as f64 - next) / cap);
        } else {
            // next item won't fit here; penalize waste proportional to gap
            score += 8.0 * ((next - post_residual as f64) / cap);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = 1.0 - (post_residual as f64 / cap);
    score -= 15.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Time horizon: early on, be conservative about waste; later, pack tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;
    score -= 20.0 * progress * fill_ratio;

    // Mean residual coupling: if this bin is much emptier than average, deprioritize it
    let dev = mean_residual - post_residual as f64;
    score += 5.0 * dev.max(0.0) / cap;
    score -= 3.0 * (-dev).max(0.0) / cap;

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
