pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;
    // Tight fit reward, stronger later in stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);
    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 10.0 * (1.0 - pr / nxt) * (0.5 + progress);
        } else {
            score -= 5.0 * (1.0 - (nxt / pr) * (nxt / pr));
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }
    // New-bin candidate: mildly penalize early, allow later when residuals fragmented
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 4.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }
    // Fragmentation pressure: penalize when this bin is far from mean residual
    score += 2.0 * (pr - mean_residual).abs() / cap;
    score
}

