pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into usable classes
    // Class 0: perfect fit (post_residual == 0) -> big reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space smaller than the smallest possible item (1) is impossible;
        // small dead space (< 10) is near-unusable in classic streams but items can be 1..100 here.
        // Classify by residue mod 10 and magnitude bands.
        let pr = post_residual;
        let band = match pr {
            0..=5 => 0.0,
            6..=15 => 1.0,
            16..=30 => 2.0,
            31..=50 => 3.0,
            _ => 4.0,
        };
        score += band * 15.0;

        // Harmonic penalty: dead space not divisible by common item granularities
        let gran10 = (pr % 10 == 0) as f64;
        let gran5 = (pr % 5 == 0) as f64;
        score -= gran10 * 20.0;
        score -= gran5 * 8.0;

        // Residue class mod 7 (prime modulus gives diverse classes)
        let r7 = (pr % 7) as f64;
        score += r7 * 1.5;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving room for the next item, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 60.0 - tight * 0.5;
        } else {
            // Penalize blocking the next item
            score += 25.0;
        }
        // Integer-division threshold: next item is "large" if > half capacity
        if next_item_size > bin_capacity / 2 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // open bins have poor fits. Penalize opening new bins mildly, more early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 80.0 + 40.0 * (1.0 - progress);
        if open_bins_count == 0 {
            new_bin_penalty = -500.0; // must open first bin
        }
        score = 100.0 + new_bin_penalty;
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — use it
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    // Slight noise-free tiebreak via step parity class
    if (step_index + post_residual as usize) % 3 == 0 {
        score -= 1.0;
    }

    score
}

