            }
            // NEW: graded multi-item lookahead — if the post-residual could absorb
            // k copies of the mean-sized demand, reward proportionally, since bins
            // that keep serving the stream prevent opening fresh bins.
            if mean_residual > 0.0 {
                let k = (pr / mean_residual).floor().min(4.0);
                if k >= 2.0 {
                    let exact = pr - k * mean_residual;
                    let tight = (1.0 - (exact / cap).clamp(0.0, 1.0)).max(0.0);
                    score -= 3.5 * (k - 1.0) * (0.5 + 0.5 * tight) * (1.0 - 0.6 * progress);
                }
