            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // MUTATED: dead-space / mean-residual coupling now graded by how well the
        // residual matches the mean demand rather than a hard late/early switch —
        // near-exact mean matches are rewarded at all stages, mismatches penalized
        // early and forgiven late.
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let match_q = 1.0 - ((pr - mean_residual) / (0.15 * cap)).clamp(0.0, 1.0);
            let early_bias = 1.0 - progress;
            score += (10.0 * match_q - 5.0 * (1.0 - match_q) * early_bias) * dead_frac;
        }
        // NEW: residual-size harmonic fit — bins whose residual is an integer
        // multiple of the current item (leaving near-zero slack) are ideal sinks.
        if item_size > 0 && pr > 0.0 {
            let copies = (pr / item_size as f64).floor();
            if copies >= 2.0 {
                let leftover = pr - copies * item_size as f64;
                if leftover <= 2.0 {
                    score -= 8.0 * (1.0 - leftover / 3.0) * (1.0 - 0.4 * progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large dead space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 22.0 / (1.0 + gap);            // exact chain fit bonus
        if post_residual == next_item_size {
            score -= 30.0;                       // perfect 2-step chain
        }
        // Penalize leaving a residual that the next item cannot use at all.
        if next_item_size > post_residual && post_residual > 0 {
            score += 0.6 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += 0.9 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when the item is large and
    // current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if pressure > 0.0 && (large_item || next_item_size == 0) {
            score -= 12.0;
        } else {
            score += 15.0; // discourage opening new bins otherwise
        }
    }

    // Mild stream-progression tightening: pack greedier later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

