    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: open a fresh bin preferentially when the item pairs exactly with the
        // next item to fill the bin (item + next ~= capacity), avoiding a stranded
        // sliver that no open bin would accept later.
        if nxt_f > 0.0 {
            let pair = item_size as f64 + nxt_f;
            if (pair - cap).abs() <= 3.0 {
                score -= 24.0 * (1.0 - (pair - cap).abs() / 3.0) * (1.0 - 0.6 * progress);
            } else if pair > cap * 0.9 && pair < cap {
                score -= 8.0 * (1.0 - 0.5 * progress);
            }
        }
        // NEW: reserve fresh bins for large items when open-bin residuals are small
        // relative to the item — placing a big item into a nearly-full bin strands
        // nothing, but placing it in a fresh bin wastes less overall.
        if fitting_bins_count > 1 && item_norm > 0.7 {
            let small_res = mean_norm < 0.25;
            if small_res {
                score -= 6.0 * item_norm * (1.0 - progress);
            }
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space refinement — if the leftover after this placement is
        // smaller than the smallest plausible future demand (below mean residual),
        // treat it as near-waste and penalize proportionally, but relax late in the
        // stream when any residual is acceptable.
        if pr > 0.0 && mean_residual > 0.0 && pr < mean_residual * 0.6 {
            score += (8.0 - 10.0 * progress).max(-2.0) * (1.0 - pr / (mean_residual * 0.6));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            // REFINED: reward exact two-step closure with the mean-sized item —
            // if post-residual minus next item leaves room for ~mean_residual,
            // the bin closes with a third piece. Sharpen the window and weight.
            if mean_residual > 1.0 {
                let third_slack = pr - nxt - mean_residual;
                if third_slack >= 0.0 && third_slack <= 6.0 {
                    score -= 9.0 * (1.0 - third_slack / 6.0) * (1.0 - 0.5 * progress);
                }
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: fresh-bin appeal rises when the remaining stream is dense with
        // large items (next item big + few fitting bins) — open early to avoid
        // forcing a large item into a fragmented residual later.
        if nxt_f > 0.0 && nxt_f > 0.5 * cap && fitting_bins_count <= 2 && item_norm < 0.5 {
            score -= 16.0 * (1.0 - progress) * (nxt_f / cap);
        }
        // NEW: resist opening fresh bins when mean residual is tiny (stream is
        // closing bins well) unless the item is large enough to justify it.
        if mean_norm < 0.06 && item_norm < 0.3 && fitting_bins_count >= 2 {
            score += 10.0 * (1.0 - item_norm / 0.3) * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space sink test — a bin whose residual is dead for the next
        // item but exactly absorbs a mean-sized piece becomes an attractive
        // terminal sink mid-stream, reducing fragmentation elsewhere.
        if next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 1.0
            && (pr - mean_residual).abs() <= 3.0 {
            score -= 12.0 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.4 + 0.6 * progress);
        }
        // NEW: penalize bins whose residual sits just below the next item size
        // by a near-mean amount — these are the classic "almost fits" traps
        // that strand mean-sized follow-ups.
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            let overshoot = (next_item_size as f64) - pr;
            if mean_residual > 1.0 && overshoot < mean_residual && overshoot > mean_residual * 0.5 {
                score += 7.0 * (1.0 - overshoot / mean_residual) * (1.0 - 0.3 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if (post_residual as f64) >= ns {
            let slack = (post_residual as f64) - ns;
            score -= 18.0 / (1.0 + slack);
        } else {
            // next item cannot follow here; mild penalty scaled by overflow
            let over = ns - post_residual as f64;
            score += 6.0 * (over / cap).min(1.0);
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 40.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Time horizon: later in stream, consolidate more aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * t * tight;

    // Many open bins: prefer filling existing ones over opening new.
    let new_bin = (bin_residual == bin_capacity) as f64;
    let pressure = (open_bins_count as f64 / 8.0).min(2.0);
    score += new_bin * (10.0 + 8.0 * pressure + 10.0 * t);

    // Mean residual coupling: if this bin is much tighter than average, favor it.
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev.max(0.0) + 0.2 * dev.min(0.0);

    // Fragmentation guard: prefer bins whose post residual is either 0 or >= ~mean item.
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let fill = item_norm;

    let mut score = pr;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 160.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
        } else {
            let slack = pr - nxt;
            if slack <= 4.0 {
                score -= 380.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 200.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 20.0 * (1.0 - progress);
            }
            // Multi-item chain lookahead: reward bins where item + next leaves
            // a near-closed residual (two-, three-, four-item chains).
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            // Residual reusable by mean-sized upcoming demand.
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 34.0 * (after / cap);
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity {
        if pr >= 8.0 && pr <= 20.0 {
            score += 10.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
            let sliver_fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * sliver_fill * (1.0 - 0.5 * progress);
            let sliver = norm_pr;
            if sliver < 0.05 && sliver > 0.0 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
            if after2 <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        // Dead-space shaping: penalize bins whose residual cannot hold the next
        // item, with late-stream tolerance for sink bins.
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - (1.0 - dead_frac)) * (1.0 - 0.4 * progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
    } else {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if fill > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && fill < 0.6 {
            new_score += 18.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && fill > 0.5 {
            new_score -= 20.0 * fill;
        }
        if fill > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            new_score -= 20.0 * (1.0 - progress);
        }
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        new_score += 25.0 * progress * (1.0 - fill);
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Quadratic dead-space penalty grows with progress
    score += 20.0 * prn * prn * (0.5 + progress);

    // Cubic interaction: late in the stream, small residuals are heavily penalized
    score += 15.0 * prn * prog3;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 10.0 * (1.0 - prn) * (1.0 - prn) * (0.3 + 0.7 * progress);

    // Penalize bins with residual far below mean residual (fragmentation)
    score += 3.0 * (mean_residual - pr).max(0.0) / cap;

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading, favor filling existing bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * prn;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // NEW: fresh bins are also justified when the remaining stream is short
        // enough that a clean single-item bin cannot be amortized poorly — i.e.
        // near the tail, prefer opening bins for medium items rather than
        // fragmenting existing residuals.
        if progress > 0.8 && item_norm > 0.35 && item_norm < 0.75 && fitting_bins_count > 2 {
            score -= 9.0 * (progress - 0.8) * 5.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // NEW: dead-space refinement — a residual that exactly equals the mean
        // upcoming demand (within a tight window) is a predicted perfect fill;
        // reward it strongly, tapering with distance from the mean.
        if dead_frac > 0.05 && mean_residual > 0.0 && pr >= mean_residual {
            let d = pr - mean_residual;
            if d <= 6.0 {
                score -= 12.0 * (1.0 - d / 6.0) * (1.0 - 0.3 * progress);
            }
        }
        // NEW: penalize residuals that are just barely too small for the next
        // item when the item is large — those leave large unusable slabs.
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            let miss = next_item_size as f64 - pr;
            if miss <= 10.0 && item_norm > 0.5 {
                score += 4.0 * (1.0 - miss / 10.0) * item_norm * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    let post_f = post as f64;

    // Reward tight fits: post_residual in low harmonic classes gets subtracted.
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post < quarter / 2 {
        score -= 40.0;
    } else if post < quarter {
        score -= 25.0;
    } else if post < half {
        score -= 8.0;
    } else {
        // Large residual left: penalize, but less if a known next item fits it.
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post {
            score -= 18.0;
        }
    }

    // Integer-division threshold coupling: post_residual divisible classes.
    if post > 0 && bin_capacity % post == 0 {
        score -= 6.0; // residual divides capacity: reusable harmonic class
    }

    // Next-item harmonic match: does next item exactly fill post_residual class?
    if next_item_size > 0 {
        let diff = post as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 30.0;
        } else if diff > 0 && (diff as u32) < quarter / 2 {
            score -= 12.0;
        } else if diff < 0 {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins whose residual deviates favorably from mean residual (balance).
    score -= 0.15 * (mean_residual - post_f);

    // New-bin candidate: only open a new bin when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let bad_fit = post_f > (cap * 0.45);
        let many_open = open_bins_count as f64 > 2.0;
        if bad_fit && many_open {
            score -= 15.0; // opening fresh is better than wasting space
        } else {
            score += 35.0; // prefer existing bins otherwise
        }
    }

    // Mild late-stream consolidation: fewer open bins is better near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

