        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        // NEW: penalize placements that strand a residual just below the mean
        // upcoming demand (dead wedge), pushing items toward bins that either
        // close exactly or leave a broadly reusable residual.
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr
            && mean_residual > 2.0 && pr < mean_residual - 2.0 && pr > mean_residual * 0.5 {
            score += 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * (1.0 - norm_pr));

    // Polynomial coupling of post_residual with stream progress:
    // early on prefer tight fills (low post_residual strongly), later allow spread
    let progress_weight = 0.6 * (1.0 - t) * (1.0 - t) + 0.15;
    score += progress_weight * pr * norm_pr * 2.0;

    // Reward near-perfect fits via smooth penalty on squared deviation from zero residual
    score -= 30.0 * (1.0 - norm_pr).powi(6);

    // Penalize residual that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0);
        score += 0.5 * gap + 0.01 * gap * gap;
        // Bonus if post_residual still accommodates next item snugly
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap)).powi(3);
        }
    } else {
        // last item: strongly prefer minimal waste
        score += 2.0 * pr;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t);
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly unless open bins are scarce or fit is poor
    if bin_residual == bin_capacity {
        let scarcity = (open_bins_count as f64).recip();
        score += 12.0 - 10.0 * scarcity * (1.0 - fit);
    }

    // Small penalty for many open bins relative to progress
    score += 0.02 * open_bins_count as f64 * (0.5 + t);

    score
}

