pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste, but gaps below a "useful threshold" are far worse.
    let useful_threshold = 20.0;
    if (post_residual as f64) < useful_threshold {
        // Quadratic penalty for creating unusable slivers.
        score += (useful_threshold - post_residual as f64).powi(2) * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Fit tightness relative to the bin: prefer bins where the item fills a
    // large fraction of the remaining space.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is cheap early (many items
    // remain to fill it), expensive late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by stream progress.
        score = 60.0 + progress * 40.0;
        // If the current item leaves a good gap for the lookahead item,
        // a fresh bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Many open bins with slack -> don't open another.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Open-bin pressure: penalize placements that spread load when few bins
    // can fit the item, to preserve flexibility.
    if fitting_bins_count > 1 && post_residual >= 1 {
        // Slight preference to keep large residuals in bins that remain
        // useful for future items.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0; // dead space w.r.t. lookahead item
        }
    }

    // Global pressure: with many open bins, discourage leaving mid-range
    // residuals that fragment capacity.
    let openness = open_bins_count as f64;
    score += (post_residual as f64 / bin_capacity as f64) * openness * 2.0;

    // Mean-residual coupling: if this bin's post-residual deviates upward
    // from the mean, it contributes to fragmentation.
    score += ((post_residual as f64 - mean_residual) / 100.0).abs() * 3.0;

    score
}

