    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more the tighter the miss
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 * (miss / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average (low waste).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny dead space (< 10) that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when residuals are large and item is big.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_res = mean_residual;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let penalty = 30.0 + 25.0 * (1.0 - item_frac) + 20.0 * progress;
        if avg_res > 1.6 * item_size as f64 {
            score += penalty * 0.3; // existing bins very roomy: discourage new bin mildly
        } else {
            score += penalty;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Tight-fit ladder with progress-coupled bonuses (borrowed from best, retuned).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 210.0 + 35.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 30.0 * progress;
    } else if post_residual < 25 {
        score -= 8.0 + 12.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.5 * norm_pr * (1.0 + progress);
    }

    // --- 2-step lookahead with graded slack rewards ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 450.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                score -= 40.0 * (1.0 - slack / cap);
            }
            // Multi-item chain forecasts.
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 18.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 7.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // Mean-residual reuse coupling.
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 8.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (60.0 + 46.0 * progress);
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            // Near-miss penalty when alternatives exist.
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 10.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // Small slivers are hard to fill: penalize early, allow late as sinks.
    if post_residual > 0 && post_residual < 10 {
        score += 90.0 * (1.0 - progress);
    }

    // Deviation from mean residual: avoid outliers.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    // Last-chance: keep the only fitting bin alive.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 24.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    // --- New-bin candidate gating ---
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 85.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 220.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // Fresh bin justified for near-capacity items.
        if item_norm > 0.95 && next_item_size > 0 && next_item_size as f64 >= item_size as f64 {
            score -= 22.0 * (1.0 - progress);
        }
        // Large item vs mean: prefer a fresh bin.
        if mean_residual > 0.0 {
            let ratio = item_size as f64 / mean_residual;
            if ratio > 1.3 {
                score -= 22.0 * (ratio - 1.3).min(2.0);
            }
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        if next_item_size > 0 && (mean_residual - next_item_size as f64).abs() < 3.0 && item_norm < 0.6 {
            score += 16.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
    } else {
        // Mid-residual trap zone: avoid leaving awkward gaps.
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 8.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
    }

    score
}

