pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let g = 1.0 - progress; // remaining stream fraction
    // smooth interaction: small residual is good early, dead space penalized late
    let coupling = prn * prn * (1.0 + 2.0 * progress) - prn * (1.0 - progress) * 0.5;
    score += 30.0 * coupling;

    // Reward tight fits (near-zero post residual) smoothly
    score -= 20.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Last-chance bin bonus (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: favor bins whose post residual could fit the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - pr / (next_item_size as f64 + 1.0)).max(0.0);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln() * (pr - mean_residual).abs();

    score
}

