            }
        }
        // MUTATION: late-stream dead-space sink tightening — after 60% of the stream,
        // residual alignment with mean residual matters more (fewer chances to fix
        // fragmentation later), so deepen the alignment reward and widen its reach.
        if mean_residual > 0.0 && dead_frac > 0.05 && progress > 0.6 {
            let align2 = 1.0 - ((pr - mean_residual) / cap).abs() * 6.0;
            if align2 > 0.0 {
