pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" residue class (small multiples of common item sizes)
    // are rewarded; awkward leftovers are penalized.
    let pr = post_residual;
    let class = pr % 10;
    let class_penalty = match class {
        0 => -8.0,               // perfectly reusable
        1 | 2 | 3 => 3.0,        // awkward slivers
        4 | 5 => 0.0,
        6 | 7 => 1.5,
        8 | 9 => 2.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division tiers: leftover in [0,10) is nearly dead space.
    if pr < 10 {
        score += 12.0;
    } else if pr < 20 {
        score += 4.0;
    } else if pr >= 50 {
        score -= 5.0; // roomy bin still useful
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot fit, mild penalty only when
    // alternatives exist.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * (item_size as f64);
    }

    // New-bin candidate handling: opening a new bin is attractive early or
    // when mean residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        score = 20.0 + 30.0 * fragmentation - 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0; // fresh bin also fits next item: fine
        }
    }

    // Slight tie-break preferring tighter fits among equals.
    score += (bin_residual - item_size) as f64 * 0.01;
    score - mean_residual * 0.02
}

