            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // NEW: dead-space compaction — if the item exactly fills the residual
        // down to a mean-sized follow-up, close the bin tightly.
        if mean_residual >= 1.0 && pr >= 1.0
            && (pr - mean_residual).abs() < 1.5 && item_size as f64 >= 0.5 * (bin_residual as f64 - pr) {
            score -= 10.0 * (1.0 - 0.5 * progress);
        }
    }

    score
}

