    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm > 0.45 && mean_norm < 0.18 && progress > 0.25 {
            score -= 10.0 * (item_norm - 0.45) * (1.0 - mean_norm / 0.18) * (1.0 - 0.5 * progress);
        }
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
                if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                    score -= 32.0 * (after / cap);
                }
            } else {
                let miss = nxt - pr;
                if miss <= 4.0 {
                    score += (4.0 - miss) * 7.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - (1.0 - dead_frac)) * (1.0 - 0.4 * progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_frac > 0.4 && next_item_size > 0 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
        if next_item_size > 0 && mean_residual > 0.0 && pr >= next_item_size as f64 + mean_residual {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // Penalize "dead space": small unusable gaps that no item can realistically fill.
    // Items are 1..100; a residual below ~10 is almost certainly dead space.
    let dead_threshold: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0; // heavy penalty for near-dead gaps
    }
    if pr == 0.0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Medium gaps that can't fit the lookahead item but could fit future small items:
    // mild penalty if gap is large but next item won't use it.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 8.0; // leaves room for the lookahead item: good
    } else if next_item_size > 0 && pr > 0.0 {
        // gap too small for next item: mild penalty scaled by gap size
        score += pr * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, new-bin option is cheaper.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or mean residual is high.
        score += 20.0 + pressure + mean_residual * 0.5;
        // Slightly cheaper to open new bins early in the stream.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    } else {
        // Reward using existing bins more strongly as open_bins_count grows.
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is close to mean (balanced packing) slightly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.5 * slack;
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use (dead space).
        score += 0.8 * (next_item_size as f64 - post_residual as f64).min(80.0);
    }

    // Prefer bins with residuals below the mean (tight bins) — keep loose bins for large items.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize wasting a nearly-empty (new) bin on a small item unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 150.0 - 1.5 * item_size as f64;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.6 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mildly penalize leaving a large gap.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax when existing bins fit poorly
    // (item doesn't leave a good residual) or many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        if fitting_bins_count > 0 {
            // If item would leave a large unusable residual in any existing bin, allow new bin.
            let worst_gap = (bin_capacity - item_size) as f64;
            if worst_gap > 35.0 && post_residual < next_item_size as f64 {
                new_bin_penalty -= 10.0;
            }
            // Spread load when open bins are mostly full.
            new_bin_penalty -= (open_bins_count as f64).sqrt() * 1.5;
        }
        // Early stream: slightly cheaper to open bins (future packing flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty -= 5.0 * (1.0 - progress);
        score += new_bin_penalty.max(5.0);
    }

    // Global pressure: when mean residual is low, conserve space more aggressively.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

