pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = item_size as f64 / cap;

    let mut score = pr;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 160.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
            // near-miss penalty scaled by alternatives
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack <= 4.0 {
                score -= 380.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 200.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 20.0 * (1.0 - progress);
            }
            // two-item chain lookahead: item + next + another copy of item
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && fill < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && fill < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // chain with mean residual
            let chain_slack = slack - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && fill < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 34.0 * (after / cap);
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if fill > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        new_score += 25.0 * progress * (1.0 - fill);
        // discourage opening new bins for tiny items when open bins are roomy
        if fill < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            new_score += 20.0 * (1.0 - fill / 0.08) * (1.0 - progress);
        }
        // pair fit in fresh bin: item + next fits exactly
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) <= cap * 0.98 && fill > 0.30 && mean_norm < 0.30 {
            new_score -= 6.0 * (1.0 - (item_size as f64 + next_item_size as f64) / cap) * (1.0 - progress);
        }
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
            // sliver residual bonus
            let sliver = pr / cap;
            if sliver < 0.05 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        // dead-space guard: leftover that next item cannot use
        if norm_pr > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * norm_pr * (1.0 - progress);
        }
        // residual-fragmentation guard
        if norm_pr > 0.3 && mean_residual > 0.0 && pr > 0.0 {
            let m = mean_residual.max(1.0);
            let rem = pr % m;
            if rem > 1.0 && rem < m - 1.0 {
                score += 4.0 * norm_pr * (1.0 - progress);
            }
        }
    }

    score
}

