pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let lookahead = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - lookahead).abs();

        if post >= lookahead {
            // Next item can follow in this bin: reward tight chains.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // perfect chain: item + next item exactly fills bin
            }
        } else {
            // Post residual too small for next item: dead space penalty,
            // scaled by how close the residual was to being useful.
            let waste_ratio = post / bin_capacity as f64;
            score += 20.0 * waste_ratio;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Penalize leaving residuals that are hard to fill later (small but nonzero).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish score based on capacity; discourage opening
    // new bins early unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream: prefer tighter packing, less experimentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

