pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Penalize dead space relative to capacity, non-linearly.
    let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 50.0 * waste;

    // Last-resort bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let mut penalty = 250.0 + 5.0 * open_bins_count as f64;
        // If the best alternative fit is bad (large post_residual elsewhere),
        // opening a new bin becomes attractive; approximate via mean residual.
        if mean_residual < item_size as f64 + 5.0 {
            penalty -= 150.0;
        }
        // Early in stream, be more willing to open bins (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= 1.0 - 0.3 * progress;
        score += penalty;
    }

    // Lookahead coupling: keep room for the next item if it fits snugly after this one.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 80.0; // enables perfect follow-up placement
            } else {
                score -= 30.0 * (gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here; mild penalty for leaving awkward space.
            let leftover = post_residual as f64;
            if leftover > 0.0 && leftover < next_item_size as f64 {
                score += 15.0 * (1.0 - leftover / next_item_size as f64);
            }
        }
    }

    // Global state: when many bins are open with slack, prefer consolidating
    // into bins whose residual is close to the mean (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Late in the stream, tighten up: prefer smallest post residual more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 40.0;

    score
}

