            let chain = (pr - nxt_f) / cap;
            if chain >= 0.12 && chain < 0.25 {
                score += 9.0 * (chain - 0.12) * (1.0 + progress);
            }
            if pr >= nxt_f && pr - nxt_f <= 2.0 && progress < 0.7 {
                score -= 12.0 * (1.0 - progress);
            }
            let two_slack = pr - nxt_f - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            }
            if item_norm > 0.55 && progress > 0.4 && mean_norm > 0.15 {
                score -= 14.0 * item_norm * (1.0 - progress);
            }
            if item_norm < 0.25 && (pr - nxt_f) <= item_size as f64 {
                score -= 10.0 * (1.0 - progress);
            }
            if item_norm > 0.7 && mean_norm < 0.10 {
                score -= 18.0 * item_norm * (1.0 - progress);
            }
        }
        // avoid opening a new bin when current item matches mean residual well
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() < 3.0 && fitting_bins_count >= 1 {
            score -= 12.0 * (1.0 - progress);
        }
        // strong avoidance when many open bins can fit and mean residual is healthy
        if fitting_bins_count >= 2 && mean_norm > 0.12 && item_norm < 0.6 {
            score += 10.0 * (fitting_bins_count.min(6) as f64) * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
            }
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
        // dead-space trap guard: residual cannot fit next item but fits current one
        let dead_frac = norm_pr;
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
        // penalize leaving residuals that no plausible future item fits
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - (1.0 - dead_frac)) * (1.0 - 0.4 * progress);
        }
    }

    score
}

