pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small harmonics) are more valuable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: huge reward
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr % 25 == 0 {
        -14.0
    } else if pr <= 10 {
        12.0 // tiny dead space, unusable for min item size 10
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual vs next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can still fit here: strong reward, scaled by snugness.
            let snug = (pr - next_item_size) as f64;
            score -= 25.0 - 0.15 * snug;
            if pr == next_item_size {
                score -= 35.0; // chain of perfect fits
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            let gap = (next_item_size - pr) as f64;
            score += 0.5 * gap.min(40.0);
        }
    }

    // Capacity fraction coupling: prefer filling bins past harmonic fractions.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill >= 0.5 && fill < 0.75 {
        score -= 8.0;
    } else if fill >= 0.75 {
        score -= 15.0;
    } else if fill < 0.25 && pr != bin_capacity {
        score += 6.0; // barely-touched bin getting a small item
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless current bins would leave bad residue.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming: fresh capacity is useful
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Tie-break by tightness of fit.
    score += 0.05 * (bin_residual - item_size) as f64;

    // Mean residual context: when open bins are spacious, prefer them.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 435.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // pair lookahead: current item + next item nearly fills the bin
            if item_norm > 0.0 {
                let pair_fill = item_size as f64 + nxt;
                if pair_fill <= pr && pr - pair_fill <= 6.0 {
                    score -= 8.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
                }
                let two_slack = pr - nxt - item_size as f64;
                if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                    score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
                } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                    score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
                }
                let tri_slack = pr - nxt - 2.0 * item_size as f64;
                if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                    score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
                }
                let chain_slack = pr - nxt - mean_residual;
                if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                    score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
                }
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
