        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * dead_frac * (1.0 - 0.4 * progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        // dead-space trap guard: residual can't fit next item but fits current; prefer tighter leftover
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
        if next_item_size > 0 && mean_residual > 0.0 && pr >= next_item_size as f64 + mean_residual {
            score -= 4.0 * (1.0 - progress);
        }
        if pr > 0.0 && mean_residual > 0.0 && pr >= next_item_size as f64 && (pr - next_item_size as f64) < mean_residual * 0.5 && dead_frac > 0.08 {
            score += 5.0 * (1.0 - (pr - next_item_size as f64) / (mean_residual * 0.5)) * (1.0 - progress);
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are pure waste;
    // residuals below a "usable threshold" are heavily penalized, scaled by how unusable they are.
    let dead_threshold = 12.0; // gaps below this rarely fit future items from unknown distribution
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let depth = dead_threshold - post_residual as f64;
        score += depth * depth * 0.6; // quadratic penalty on unusability depth
    }
    // Perfect fit is golden: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = (post_residual as f64) / (item_size as f64);
        score += tightness * 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    let pressure = open_bins_count as f64;
    score += pressure * pressure * 0.02;

    // Last-chance bin: if this is the only bin that can fit the item, favor it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item would fit the post-residual exactly or well,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64) * 6.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use this residual: penalize proportionally
        score += 3.0;
    }

    // Mean-residual coupling: placing into a bin with residual far below the mean
    // (converging bins) is good; avoid dumping into already-small residuals poorly.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.15;
    }

    // Early in the stream, be slightly more willing to open new bins (build a good pool);
    // late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early opening.
        score += 10.0 + 30.0 * progress;
        if post_residual >= 50.0 {
            score -= 8.0; // a fresh bin keeps a large residual for future big items
        }
    }

    score
}

