            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
        // penalize residuals in 25-45 range that cannot hold the item
        if pr > 25.0 && pr < 45.0 && item_norm > 0.15 && item_size as f64 > pr {
            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        // dead space that cannot even hold the mean residual chain
        if dead_frac > 0.22 && mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.95 {
            score += 3.5 * dead_frac * (1.0 - 0.5 * progress);
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
