            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // penalize residuals in the 25-45 range (too big to waste, too small for medium items)
        if pr > 25.0 && pr < 45.0 && item_norm > 0.15 && item_size as f64 > pr {
            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        // penalize dead space that cannot even hold the mean residual chain
        if dead_frac > 0.22 && mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.95 {
            score += 3.5 * dead_frac * (1.0 - 0.5 * progress);
        }
        // near-miss trap: residual just below next item, harder when other bins fit
        if pr > 0.0 && pr < next_item_size as f64 && next_item_size as f64 - pr <= 5.0 && fitting_bins_count > 1 {
            score += (5.0 - (next_item_size as f64 - pr)) * 7.0 * (1.0 - 0.4 * progress);
        }
    }

    score
}

