        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        // trap zone: residuals too big to waste, too small for medium items
        if post_residual >= 25 && post_residual <= 45 && item_norm > 0.15 && item_size as f64 > pr {
            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            let dead_frac = pr / cap;
            if dead_frac > 0.15 && dead_frac < 0.35 {
                score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
            }
            if dead_frac > 0.22 && mean_residual > 0.0 && pr < mean_residual * 0.95 {
                score += 3.5 * dead_frac * (1.0 - 0.5 * progress);
            }
        }
    }

    // Mild preference for consolidating into fewer bins
    score += 2.0 * open_bins_count as f64;

    score
}

