    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 160.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            // MUT138: when the next item misses but the mean residual could host it, penalize less (elsewhere capacity exists)
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - miss / (nxt - pr + miss)) * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 380.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 220.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 20.0 * (1.0 - progress);
            }
            // MUT138: continuous quadratic mid-slack gradient (borrowed from best) to smooth the 15-40 band
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 34.0 * (after / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            if slack >= 0.0 && slack < 8.0 && item_norm < 0.10 {
                score -= 4.0 * (1.0 - slack / 8.0) * (1.0 - progress);
            }
            // MUT138: penalize leaving a residual the next item almost (but not) fits when few bins can host it
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
            // MUT138: exact multiplicative alignment of slack with next item (future perfect fills)
            if slack > 0.0 && nxt > 1.0 {
                let m = (slack / nxt).floor();
                if m >= 2.0 && slack - m * nxt < 1.0 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
            if slack > 0.0 && item_size > 1 {
                let m2 = (slack / item_size as f64).floor();
                if m2 >= 1.0 && slack - m2 * item_size as f64 <= 1.0 {
                    score -= 4.0 * (1.0 - progress);
                }
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
