        // graded dead-space penalty pushing residual toward next-item-friendly sizes
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - (1.0 - dead_frac)) * (1.0 - 0.4 * progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
        if pr > 25.0 && pr < 45.0 && item_norm > 0.15 && item_size as f64 > pr {
            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 100.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly equals next_item_size -> strong reward
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + lookahead_gap);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residual that cannot fit the next item (dead space risk)
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: reward tightest fit
        score -= 10.0;
    }

    // Reward bins tighter than average (good fill), penalize looser ones
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating very small unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Early in stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - 1.0) * 0.5;

    // New-bin candidate: only attractive when current item is huge relative to mean residual
    if bin_residual == bin_capacity {
        let crowded = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.6 && open_bins_count > 2);
        if crowded {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
