pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        - 12.0 * norm_pr * (1.0 - norm_pr) * cap * 0.5 // reward mid-range residuals slightly
        + 8.0 * norm_pr * norm_pr * cap; // penalize large wasted residuals

    // Smooth interaction of post residual with stream progress
    score += 20.0 * norm_pr * progress * (1.0 - progress) * 4.0;

    // Tight fits favored: reward small post_residual non-linearly
    if pr == 0 {
        score -= 30.0;
    } else {
        score -= 25.0 * (1.0 - norm_pr).exp();
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Mean residual coupling: penalize deviating far from mean
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference to fill existing bins as stream progresses
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate penalty (empty bin) unless residuals are all large
    if bin_residual == bin_capacity {
        let threshold = mean_residual.max(1.0);
        score += 10.0 + 20.0 / threshold.sqrt();
        if progress > 0.7 {
            score -= 8.0; // late stream: opening fresh bins can help
        }
    }

    score
}

