            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // MUT141: quad-item chain for tiny items
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            if slack >= 0.0 && slack < 8.0 && item_norm < 0.10 {
                score -= 4.0 * (1.0 - slack / 8.0) * (1.0 - progress);
            }
            // MUT141: divisibility alignment — slack leaves near-exact multiples of next item
            if slack > 0.0 && nxt > 1.0 {
                let m = (slack / nxt).floor();
                if m >= 2.0 && slack - m * nxt < 1.0 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
            // MUT141: near-exact multiples of the current item in the leftover
            if slack > 0.0 && item_size > 1 {
                let m2 = (slack / item_size as f64).floor();
                if m2 >= 1.0 && slack - m2 * item_size as f64 <= 1.0 {
                    score -= 4.0 * (1.0 - progress).min(1.0);
                }
            }
            // MUT141: mean-residual alignment of the post-pair residual
            if mean_residual > 0.0 && slack > 20.0 && slack < 0.30 * cap && item_norm < 0.20 {
                let align = 1.0 - ((slack - mean_residual) / cap).abs() * 6.0;
                if align > 0.0 {
                    score -= 5.0 * align * (1.0 - progress);
                }
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if fill > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() < 3.0 && fitting_bins_count >= 1 {
            new_score -= 12.0 * (1.0 - progress);
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && fill < 0.6 {
            new_score += 18.0 * (1.0 - progress);
        }
        // MUT141: fresh-bin candidate discouraged when fleet mean residual already hosts the next item
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            new_score += 14.0 * (1.0 - 0.3 * progress);
        }
        // MUT141: fresh bin for a small item when open bins are nearly full — allow it
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            new_score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        new_score += 25.0 * progress * (1.0 - fill);
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        // MUT141: graded dead-space excess over the next item pushes residual toward next-friendly sizes
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        // MUT141: mean-residual alignment of the leftover residual
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            if mean_residual > 1.0 {
                let reuse = pr / mean_residual.max(1.0);
                if reuse < 3.0 && pr >= nxt {
                    score -= 5.0 * (1.0 - reuse / 3.0) * (1.0 - 0.5 * progress);
                }
            }
            // COMBINED: smooth quadratic dead-space gradient over mid slack
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // COMBINED: chain slack — residual after item + next + mean-sized follow-up
            let chain_slack = pr - nxt - item_size as f64 - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 5.0 && item_norm < 0.40 {
                score -= 8.0 * (1.0 - chain_slack / 5.0) * (1.0 - 0.4 * progress);
            }
            // COMBINED: mean-residual alignment of leftover slack
            if mean_residual > 0.0 && slack > 4.0 && slack < 0.35 * cap && item_norm < 0.25 {
                let align = 1.0 - ((slack - mean_residual) / cap).abs() * 7.0;
                if align > 0.0 {
                    score -= 5.0 * align * (1.0 - progress);
                }
            }
            // near-exact multiple of next item in slack
            if slack > 0.0 && nxt > 1.0 {
                let m = (slack / nxt).floor();
                if m >= 2.0 && slack - m * nxt < 1.0 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
            if slack >= 1.0 && slack <= 6.0 && fitting_bins_count >= 2 {
                score -= 10.0 * (1.0 - (slack - 1.0) / 5.0) * (1.0 - 0.3 * progress);
            }
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        let items_left = total_items.saturating_sub(step_index);
        if items_left <= 3 && item_norm > 0.5 {
            score -= 18.0 * item_norm;
        }
        if fitting_bins_count >= 4 && item_norm < 0.35 && progress < 0.4 {
            score += 10.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && item_norm < 0.4 && (cap - item_size as f64) > 1.5 * mean_residual.max(1.0) && fitting_bins_count >= 2 {
            score += 8.0 * (1.0 - progress);
        }
        // COMBINED: discourage fresh bins whose residual would strand a mean-sized follow-up
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        // COMBINED: fresh bin is justified when item + next pair nearly fills it
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // COMBINED: graded dead-space penalty pushing residuals toward next-item-friendly sizes
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        // COMBINED: mean-residual alignment of a dead residual is a small-item sink
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (residuals that pair well with typical small items: >= 10 or exactly 0).
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual >= 10 {
        score -= 8.0;
    } else {
        // dead space class 1..9: penalize proportionally
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Modulo classes on capacity: residuals congruent to 0 mod 25 are
    // "harmonic" (50, 25, 75 pair with common sizes).
    let r_mod = post_residual % 25;
    if r_mod == 0 && post_residual > 0 {
        score -= 12.0;
    } else if r_mod <= 5 && post_residual >= 10 {
        score -= 4.0;
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.6;
        // extra bonus for near-exact pairing
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        score += 5.0; // next item can't use this bin anyway
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive when open bins are crowded
    // or the fit here is bad.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0;
        score += 30.0 - pressure.min(30.0);
        // opening a new bin is bad if current fit is already good
        if post_residual <= 20 && post_residual >= 0 {
            score += 40.0;
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Late in stream: prefer closing bins (reduce open-bin sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    // Penalize leaving residual far from mean (fragmentation spread).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // combined: smooth mid-slack gradient (quadratic dead-space term)
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            if mean_residual > 1.0 {
                let reuse = pr / mean_residual.max(1.0);
                if reuse < 3.0 && pr >= nxt {
                    score -= 5.0 * (1.0 - reuse / 3.0) * (1.0 - 0.5 * progress);
                }
            }
            // combined lookahead: chain slack through item + mean-sized follow-up
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            // near-exact multi-fill: residual consumed by k copies of the item
            if item_size > 1 {
                let m = (slack / item_size as f64).floor();
                if m >= 1.0 && slack - m * item_size as f64 <= 1.0 {
                    score -= 4.0 * (1.0 - progress);
                }
            }
            // pair fill: item + next item closes the bin nearly exactly
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            // tight residual band when alternatives exist
            if slack >= 1.0 && slack <= 6.0 && fitting_bins_count >= 2 {
                score -= 12.0 * (1.0 - (slack - 1.0) / 5.0) * (1.0 - 0.3 * progress);
            }
            // penalize slack the next item almost (but not quite) fits when few alternatives
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
