pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: strongly reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste that can't fit the next item is more costly.
        score += 0.03 * post_residual as f64;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // Base penalty for opening a new bin.
        score += 30.0;
        // If open bins have large mean residual (lots of slack), discourage new bin more.
        score += crowdedness * 20.0;
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 10.0;
        // If no other bin fits at all, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Mild preference for filling bins with lower residual among equals.
    score += 0.01 * (bin_residual as f64 - mean_residual);

    // Slight consolidation pressure as open bin count grows.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
