pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic + cubic) shaping.
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr + 0.5 * norm_pr * norm_pr * norm_pr;

    // Smooth progress coupling: residual waste matters more later in the stream.
    let prog_term = 0.6 * progress + 1.4 * progress * progress;
    score *= 1.0 + prog_term * (1.0 - 0.5 * norm_pr);

    // Lookahead: reward bins whose post-residual can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        let usable = 1.0 / (1.0 + (4.0 * diff).powi(2)); // peaks when pr ≈ next size
        score -= 1.2 * usable * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0 + 1.5 * progress;
    }

    // New-bin candidate penalty: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 3.0 + 0.8 * crowding + 2.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (spread waste evenly).
    score += 0.25 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
