pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class of the post-residual: perfect fits (class 0) are golden.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        // Penalize dead space quadratically, scaled by capacity fraction.
        score += 0.02 * pr * pr / cap;
        // Class-based modulation: residuals that are multiples of 5 or 10
        // are more likely to be reused by future items.
        if class == 0 { score -= 12.0; }
        else if class == 5 { score -= 6.0; }
        else { score += 3.0 + 0.5 * (class as f64); }
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain continues; reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.1 * slack;
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 8.0; // harmonic divisibility: residual is a multiple of next item
            }
        } else {
            // Next item cannot use the leftover; dead space likely.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: minimize residual directly.
        score += 0.5 * pr;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream progress and
        // how fragmented the open bins are (mean residual).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        let mut new_score = 45.0 + 25.0 * progress - 30.0 * fragmentation;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 { new_score -= 10.0; }
        // Many open bins with high mean residual: don't open more.
        new_score += 2.0 * (open_bins_count as f64).sqrt();
        score = new_score.max(score);
    } else {
        // Slight preference for bins whose residual is below the mean
        // (consolidate waste into few bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    score
}

