            if mean_residual > 1.0 {
                let reuse = pr / mean_residual.max(1.0);
                if reuse < 3.0 && pr >= nxt {
                    score -= 5.0 * (1.0 - reuse / 3.0) * (1.0 - 0.5 * progress);
                }
            }
            // MUT144: continuous quadratic dead-space term in the mid-slack band
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // MUT144: small-item multi-fit reward — residual divisible by item size
            if slack > 0.0 && item_size > 1 {
                let m2 = (slack / item_size as f64).floor();
                if m2 >= 1.0 && slack - m2 * item_size as f64 <= 1.0 {
                    score -= 4.0 * (1.0 - progress).min(1.0);
                }
            }
            // MUT144: pair-fill lookahead — item + next item exactly closes the bin
            if slack >= 0.0 {
                let pair_fill = item_size as f64 + nxt;
                if pair_fill <= pr && pr - pair_fill <= 6.0 {
                    score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
                }
            }
            // MUT144: near-miss slack penalized when few bins can host the item
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        let items_left = total_items.saturating_sub(step_index);
        if items_left <= 3 && item_norm > 0.5 {
            score -= 18.0 * item_norm;
        }
        if fitting_bins_count >= 4 && item_norm < 0.35 && progress < 0.4 {
            score += 10.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && item_norm < 0.4 && (cap - item_size as f64) > 1.5 * mean_residual.max(1.0) && fitting_bins_count >= 2 {
            score += 8.0 * (1.0 - progress);
        }
        // MUT144: discourage fresh bins for small items when the fleet mean
        // residual could still absorb the item (avoid bin proliferation)
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        // MUT144: fresh bin justified when item + next item pair fits well
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        // MUT144: item close to mean residual size is a good fresh-bin opener
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // MUT144: graded dead-space penalty for residuals dead to the next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        // MUT144: reward near-exact item+mean chain closures
        if mean_residual > 0.0 && next_item_size > 0 && pr >= next_item_size as f64 + mean_residual {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * (pr / cap) * (1.0 + progress);
    }

    // Lookahead on next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Two-step chain: item + next both fit with tight leftover
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // Triple chain for small items
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // Smooth mid-slack gradient (MUT145)
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // Mean-residual alignment of leftover
            if mean_residual > 0.0 && pr > 0.0 && pr < 0.45 * cap {
                let align = 1.0 - ((pr - mean_residual) / cap).abs() * 8.0;
                if align > 0.0 {
                    score -= 6.0 * align * (1.0 - 0.5 * progress);
                }
            }
            // Multiples of next item fit cleanly
            if slack > 0.0 && nxt > 1.0 {
                let m = (slack / nxt).floor();
                if m >= 2.0 && slack - m * nxt < 1.0 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
        } else {
            let miss = nxt - pr;
            score += (miss / cap) * (58.0 + 46.0 * progress);
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // Small dead-space penalty
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Trap band: residuals that rarely fit future items
    if post_residual >= 11 && post_residual <= 24 {
        let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
        score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // Discourage fresh bin when existing fleet can host the next item anyway
        if next_item_size > 0 && mean_norm > 0.03 && mean_residual >= next_item_size as f64 {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        // Encourage fresh bin for very large items that would wreck a partial bin
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        // Small items late: prefer squeezing into existing space
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
    } else {
        // Mid-range residual that next item just misses
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            let dead_frac = pr / cap;
            if dead_frac > 0.25 {
                score += 11.0 * dead_frac * (1.0 - progress);
            }
        }
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
    }

    // Consolidation preference
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), non-linearly
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth coupling of dead space with stream progress: late in the stream,
    // small leftovers matter more (less time to fill them).
    score += 40.0 * norm_post * norm_post * progress;

    // Reward using an existing bin when it is the only fitting one (avoid new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating a small awkward residual
        score += 8.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Prefer bins with residual below the mean (consolidate small spaces)
    score += 0.5 * (post - mean_residual);

    // Mild penalty for opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (fitting_bins_count as f64);
    }

    // Very small residuals are nearly dead space; penalize smoothly
    score += 12.0 * (-norm_post * 10.0).exp() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets create tiered dead-space penalties.
    let pr = post_residual;
    let class = pr % 10;
    let dead = match pr {
        0 => -40.0,                    // perfect fit: strong reward
        1..=5 => 6.0 + class as f64,   // tiny slivers: heavily penalized
        6..=10 => 2.0 + class as f64,  // small residue
        11..=19 => 8.0,                // awkward mid sliver
        _ => 0.0,
    };
    score += dead;

    // Fraction-of-capacity harmonic tiers on residual space.
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.05 { score -= 10.0; }
    else if frac < 0.15 { score += 12.0; }
    else if frac < 0.30 { score += 4.0; }
    else if frac < 0.50 { score -= 3.0; }
    else { score -= 8.0; }

    // Integer-division threshold: post_residual divisible by next item => lookahead synergy.
    if next_item_size > 0 {
        if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 14.0;
        } else if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size > pr {
            score += 5.0; // next item cannot use this residue anyway
        }
        // Harmonic pairing: residue and next item share a common divisor class
        let g = gcd(pr, next_item_size);
        if g > 4 { score -= g as f64 * 0.3; }
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item leaves huge residue
    // and no open bin is a good host.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64) * 0.5 + (open_bins_count as f64) * 1.5;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0; // open bins are too full, prefer fresh bin
        } else {
            score += pressure;
        }
    }

    // Late-stream tightening: prefer compact fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.6;

    // Small bonus for tight fills relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 6.0;
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 430.0 - 14.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // MUT145: continuous quadratic dead-space gradient in the mid-slack band
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 24.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // MUT145: two-item lookahead — reward bins where item + next item nearly fill the residual
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 15.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // MUT145: triple lookahead for tiny items
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 9.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // MUT145: penalize residuals the next item almost (but doesn't) fit, worse when few alternatives exist
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.0 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            // MUT145: near-miss penalty — the next item just barely misses this residual
            let miss = nxt - pr;
            if miss <= 5.0 {
                score += (5.0 - miss) * (4.0 + 3.0 * progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            score -= 38.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && item_norm < 0.35 && progress > 0.25 {
            score -= 26.0 * (1.0 - mean_norm / 0.06);
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let dead = (pr - nxt_f) / cap;
            if dead > 0.0 && dead < 0.12 {
                score -= 20.0 * (0.12 - dead) * (1.0 + progress);
            }
            let chain = (pr - nxt_f) / cap;
            if chain >= 0.12 && chain < 0.25 {
                score += 9.0 * (chain - 0.12) * (1.0 + progress);
            }
            if pr >= nxt_f && pr - nxt_f <= 2.0 && progress < 0.7 {
                score -= 12.0 * (1.0 - progress);
            }
            let two_slack = pr - nxt_f - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            }
            if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            if item_norm > 0.55 && progress > 0.4 && mean_norm > 0.15 {
                score -= 14.0 * item_norm * (1.0 - progress);
            }
            if item_norm < 0.25 && (pr - nxt_f) <= item_size as f64 {
                score -= 10.0 * (1.0 - progress);
            }
            if item_norm > 0.7 && mean_norm < 0.10 {
                score -= 18.0 * item_norm * (1.0 - progress);
            }
            // MUT145: discourage opening a fresh bin when the fleet's mean residual could host the next item
            if fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
                score += 14.0 * (1.0 - 0.3 * progress);
            }
            // MUT145: fresh-bin bonus when the mean residual aligns with the next item size
            if mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
                score += 12.0 * (1.0 - progress);
            }
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 20.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 10.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 32.0 * (after / cap);
            }
            if after <= 2.0 {
                score -= 18.0 * (1.0 - progress);
            }
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            let sliver = pr / cap;
            if sliver < 0.05 && sliver > 0.0 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
            if fitting_bins_count > 3 && sliver < 0.02 {
                score -= 10.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 25.0 * (1.0 - progress);
        }
        // MUT145: graded dead-space excess penalty pushing residual toward next-item-friendly sizes
        if dead_check(norm_pr) && next_item_size > 0 && pr > 0.0 {
            let excess = norm_pr - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr <= 4.0 {
            score += 7.0 * (1.0 - progress);
        }
        if pr > 25.0 && pr < 40.0 && mean_residual > 0.0 && (pr / mean_residual) > 2.5 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) >= pr * 0.5 && (next_item_size as f64) < pr {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

#[inline]
fn dead_check(dead_frac: f64) -> bool {
    dead_frac > 0.05
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }
    // Tight fit bonus: residual dominated by item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // If many bins fit the item, prefer the tightest anyway; mild spread penalty
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Open-bins pressure: with many open bins, avoid spreading; encourage consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Mean residual coupling: if this bin's residual is far above mean, it's a poor target
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Lookahead: if next item fits into post_residual, reward leaving useful space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item cannot use the leftover gap: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 40.0 + pressure * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // pairing opportunity in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            if mean_residual > 1.0 {
                let reuse = pr / mean_residual.max(1.0);
                if reuse < 3.0 && pr >= nxt {
                    score -= 5.0 * (1.0 - reuse / 3.0) * (1.0 - 0.5 * progress);
                }
            }
            // MUT145: continuous quadratic gradient in the mid-slack band to
            // smooth residual waste instead of discrete band jumps.
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // MUT145: sharpen mid-band interpolation between the 15 and 40 slack tiers
            if slack > 15.0 && slack <= 40.0 {
                let band = (slack - 15.0) / 25.0;
                score -= (235.0 - 98.0) * band * (1.0 - 0.15 * band);
            }
            // MUT145: near-exact multi-copy alignment of slack with next item
            if slack > 0.0 && nxt > 1.0 {
                let m = (slack / nxt).floor();
                if m >= 2.0 && slack - m * nxt < 1.0 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
            // MUT145: chain lookahead — residual covers item + next + mean follow-up
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            // MUT145: penalize slack that the next item almost fits, when few alternatives
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            // MUT145: scale the near-miss penalty with fleet size so crowded
            // streams prefer bins whose residual is salvageable elsewhere.
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        let items_left = total_items.saturating_sub(step_index);
        if items_left <= 3 && item_norm > 0.5 {
            score -= 18.0 * item_norm;
        }
        if fitting_bins_count >= 4 && item_norm < 0.35 && progress < 0.4 {
            score += 10.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && item_norm < 0.4 && (cap - item_size as f64) > 1.5 * mean_residual.max(1.0) && fitting_bins_count >= 2 {
            score += 8.0 * (1.0 - progress);
        }
        // MUT145: small items into fresh bins are wasteful when other bins fit;
        // scale the deterrent with how many alternatives exist.
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        // MUT145: medium-large items early into fresh bins when mean residual
        // could absorb them — push toward existing bins.
        if item_norm > 0.45 && mean_norm < 0.18 && progress > 0.25 {
            score -= 10.0 * (item_norm - 0.45) * (1.0 - mean_norm / 0.18) * (1.0 - 0.5 * progress);
        }
        // MUT145: if a fresh bin is the only candidate but mean residual
        // elsewhere could host the next item, discourage the fresh open.
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // MUT145: graded excess dead-space penalty — residual dead for the next
        // item is penalized smoothly in proportion to the excess over the next
        // item's footprint, tightening residual toward usable sizes.
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        // MUT145: residual alignment with mean demand — bins whose residual
        // matches the fleet's typical leftover are easier to close later.
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer placements where the next item also fits (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item.
        score += 15.0 + 0.25 * (next_item_size as f64);
    }

    // Reward tight fits relative to mean residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space below typical small-item size (unusable gap).
    if post_residual < 10 {
        score -= 25.0; // nearly perfect fit, great
    } else if post_residual < next_item_size.max(10) {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good 2-step fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream or many open bins: opening fresh bins is cheaper later.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin guarantees a 2-step fit
        }
    }

    // Mild preference for bins with below-average residual (consolidate large gaps).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 55.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // MUT146: continuous quadratic dead-space term smoothing the mid-slack gradient
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // MUT146: discourage residuals the next item almost fits when few bins can host it
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            if mean_residual > 0.0 && pr > 0.0 && pr < 0.45 * cap {
                let align = 1.0 - ((pr - mean_residual) / cap).abs() * 8.0;
                if align > 0.0 {
                    score -= 6.0 * align * (1.0 - 0.5 * progress);
                }
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm > 0.45 && mean_norm < 0.18 && progress > 0.25 {
            score -= 10.0 * (item_norm - 0.45) * (1.0 - mean_norm / 0.18) * (1.0 - 0.5 * progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT146: fresh-bin penalty when the fleet already holds a residual matching the next item
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
