                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 100.0 * (1.0 - progress);
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
        // MUT146: graded dead-space penalty pushing residual toward next-item-friendly sizes
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if pr > 25.0 && pr < 45.0 && item_norm > 0.15 && item_size as f64 > pr {
            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Penalize small dead space that nothing (min size 1) can use later —
    // but small post-residuals relative to item range are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            let overflow = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * overflow.min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate,
    // favor filling existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * 8.0 * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item is large relative to capacity and current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Slight handicap so open bins win by default; overcome it for big items late in stream.
        score += 12.0 - 20.0 * big_item * (0.5 + progress);
    }

    // Time horizon: late in the stream, prioritize closing bins out (low post-residual matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

