pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size blocks (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    let mut reusability = 0.0;
    if r % 50 == 0 { reusability += 18.0; }
    else if r % 25 == 0 { reusability += 12.0; }
    else if r % 20 == 0 { reusability += 10.0; }
    else if r % 10 == 0 { reusability += 6.0; }
    score -= reusability;

    // Penalize dead space in the awkward zone (1..10): nearly unusable.
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size <= r {
        if next_item_size == r {
            score -= 40.0;
        } else {
            let nxt_class = if next_item_size % 10 == 0 { 1.0 } else { 0.5 };
            score -= 8.0 * nxt_class * (1.0 - (r - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual.saturating_sub(item_size)) as f64;
    }

    // New-bin candidate: give it a moderate baseline so it wins only when
    // all open bins would create bad fits; also attractive early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Tie-break with mean residual: prefer bins tighter than average
    // (pack full bins first, keep loose bins for future items).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Mild penalty for fragmenting many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

