    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 interface, but sizes >=10 typical) are dead space.
    // Penalize gaps below a usable threshold super-linearly.
    let usable_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < usable_threshold {
        score += (usable_threshold - pr) * (usable_threshold - pr) * 8.0;
    }

    // Medium gaps (10..30) are semi-dead: mild quadratic penalty.
    if pr >= usable_threshold && pr < 30.0 {
        score += (30.0 - pr) * 0.8;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward heavily; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > post_residual {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins by scaling the base dead-space signal.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * pr * 0.05;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its post_residual is large (100 - item), which already scores high.
    // Add extra fixed cost so a new bin is only chosen when all fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0 + (item_size as f64) * 0.3;
        // If no open bin fits, opening a new bin is necessary: soften cost.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Progress: early in the stream, slightly prefer consolidating into
    // existing bins; late in the stream, prioritize tight fits (already done).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - pr / bin_capacity as f64);

    // Mean residual coupling: bins with residual far below mean are tight;
    // filling them is good, so reward when post_residual approaches 0 relative
    // to mean residual.
    if mean_residual > 0.0 {
        score -= (mean_residual - pr).max(0.0) * 0.1;
    }

