pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving exactly zero space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 500.0; // exact chain: next item fills this bin perfectly
        } else {
            score += 0.6 * diff; // penalize mismatch
        }
        // If next item cannot fit here anyway, mild penalty for wasting large residual.
        if nxt > post {
            score += 0.25 * (post / bin_capacity as f64);
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
