        score -= 120.0;
    }

    // Penalize opening a new bin when open bins could still accommodate the item.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
        // Later in the stream, prefer consolidation into existing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Small penalty for large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny slivers are near-dead space
    }

    score
}

