            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        // MUT150: graded dead-space penalty proportional to excess over the
        // next item size, pushing residuals toward next-item-friendly sizes
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Normalized post-residual and fit quality
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Smooth non-linear coupling: squared/cubic post-residual terms
    // Penalize large leftover space quadratically (wasted capacity)
    score += 2.0 * post_norm * post_norm * cap;

    // Interaction of post_residual with stream progress:
    // late in the stream, dead space matters more
    score += (1.0 + progress) * post_norm * post_norm * post_norm * cap;

    // Reward tight fits: item nearly filling residual
    let tightness = item_norm / (bin_residual as f64 / cap).max(1e-6);
    score -= 1.5 * tightness * tightness * (1.0 - post_norm);

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = better consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev.abs() * cap;

    // Last-chance bonus: smooth sigmoid-like weighting on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 4.0 * last_chance * (1.0 - progress);

    // Lookahead coupling: reward leaving space that next item can use
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = post_norm - next_norm;
        // smooth penalty if post-residual is slightly too small for next item
        score += 1.2 * gap * gap * cap * (1.0 - progress);
        // reward if next item fits snugly into post residual
        score -= 1.0 * (1.0 - (gap * gap).min(1.0)) * post_norm * cap * progress;
    }

    // New-bin candidate: penalize opening a new bin smoothly unless
    // current bins are heavily fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 6.0 - 5.0 * fragmentation * fragmentation;
    }

    // Mild penalty for too many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
