            score += 16.0 * (1.0 - 0.5 * progress);
        }
        if mean_norm > 0.0 && item_norm <= mean_norm * 1.05 && fitting_bins_count >= 2 && nxt_f > 0.0 && nxt_f <= mean_res_safe {
            score += 10.0 * (1.0 - 0.4 * progress);
        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && item_norm > 0.55 && progress > 0.4 && mean_norm > 0.15 {
            score -= 14.0 * item_norm * (1.0 - progress);
        }
        if nxt_f > 0.0 {
            let two_slack = pr - nxt_f - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
