            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Quadratic waste penalty on unusable dead space fraction
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste_frac * waste_frac;

        // Lookahead (k=2): does the next item fit into the leftover?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 10.0; // chainable bin: reward
            } else {
                score += 12.0; // dead space for the known next item: penalize
            }
        }
    }

    // Harmonic class of leftover: coarser classes (bigger leftovers) are worse
    score += (post_residual / 10) as f64 * 3.0;
    // Extra penalty for leftovers in awkward small classes (1..9, 11..19 style gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (residual == capacity): penalize mildly, but allow when
    // no open bin fits or the item is large and current bins are tight
    if bin_residual == bin_capacity {
        score += 6.0 + item_size as f64 * 0.15;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin
        } else if item_size >= 60 {
            score -= 10.0; // large items may deserve fresh bins
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // Slight preference for bins below mean residual (balance/consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (say 10)
    // or smaller than the lookahead item when nothing else could use it.
    let min_item = 10.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_item {
        score += 60.0 * (min_item - pr) / min_item;
    }

    // Penalize residuals that are large enough to tempt but awkward:
    // quadratic term punishes mid-range waste less than tiny waste but adds shaping.
    score += 0.35 * (pr * pr) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that exactly accommodates the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap that can't fit the next item but could have if
    // we had chosen differently (soft pressure).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 0.8 * bin_pressure;
        // But if the current bin would leave a bad tiny gap, opening new is fine.
        if post_residual > 0 && post_residual < min_item {
            score -= 40.0;
        }
    } else {
        // Existing bins get a mild preference baseline.
        score -= 5.0;
        // Slight preference for tighter bins (smaller residual before placement).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Mean-residual coupling: if mean residual is large, packing into existing
    // bins is generally easy; nudge toward consolidation.
    score += 0.05 * (mean_residual - pr);

    score
}

