pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * tightness * tightness * bin_capacity as f64;

    // Penalize waste when the leftover cannot plausibly fit future items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus: bin can still host the lookahead item.
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Dead space relative to the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * dead * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to keep options open.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Prefer bins whose residual is below the mean (consolidating small leftovers),
    // unless the item is large and needs the space.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Time-horizon modulation: early in the stream, be pickier about waste;
    // late in the stream, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well (large item or very fragmented residuals).
    if bin_residual == bin_capacity {
        let avg_frag = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Attractive if item is large or open bins are very fragmented.
        let attractiveness = item_frac * 60.0 + avg_frag * 40.0 - 30.0;
        // Late in stream, avoid opening bins needlessly.
        score = attractiveness * (1.0 + 0.5 * (1.0 - progress));
        if fitting_bins_count == 0 {
            score = -1000.0; // no alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 1.5 * progress * norm_pr - 0.8 * (1.0 - progress) * norm_pr * norm_pr);

    // Reward tight fits: quadratic bonus shrinking with post_residual
    let tight_bonus = -(1.0 - norm_pr) * (1.0 - norm_pr) * (2.0 + 2.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    let mut dead_penalty = 0.0;
    if next_item_size > 0 && pr < next_item_size as f64 {
        dead_penalty = (1.0 - pr / next_item_size.max(1) as f64) * (1.0 + progress);
    }

    // Last-chance bin reward (smooth in fitting_bins_count)
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    let last_chance = -3.0 * scarcity * fit;

    // Mild penalty for spreading across many open bins
    let spread = 0.05 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt();

    // Alignment with mean residual state
    let mean_term = 0.3 * (norm_pr - mean_residual / cap).abs() * (1.0 - progress);

    // Lookahead synergy: prefer bins whose leftover still pairs with next item
