    if next_item_size > 0 && pr >= next_item_size as f64 {
        synergy = -1.0 * nxt * (1.0 - (pr - next_item_size as f64) / cap);
    }

    let score = poly * cap * 0.1 + tight_bonus * cap * 0.1
        + dead_penalty * cap * 0.1 + last_chance + spread + mean_term + synergy;

    score
}

