                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // MUT152: penalize slack just below the next item size when few
            // bins can host it — near-miss residual is the classic waste.
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
            // MUT152: reward slack that divides cleanly by the next item size
            // (chain of follow-ups closes the bin exactly).
