        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // fresh-bin relief late in the stream for large items
        let items_left = total_items.saturating_sub(step_index);
        if items_left <= 3 && item_norm > 0.5 {
            score -= 18.0 * item_norm;
        }
        // discourage new bins early when many open bins already fit the item
        if fitting_bins_count >= 4 && item_norm < 0.35 && progress < 0.4 {
            score += 10.0 * (1.0 - progress);
        }
        // avoid opening fresh bins when the item would strand a dead
        // residual in a fresh bin while an existing bin closes cleanly.
        if nxt_f > 0.0 && item_norm < 0.4 && (cap - item_size as f64) > 1.5 * mean_residual.max(1.0) && fitting_bins_count >= 2 {
            score += 8.0 * (1.0 - progress);
        }
        // MUT152: discourage small items into fresh bins when other bins fit them
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        // MUT152: fresh-bin only candidate — prefer it when item matches mean demand
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score -= 16.0 * (1.0 - 0.5 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        // dead-space refinement: residual dead for next item but matching mean
        // demand is a small-item sink rather than a near-miss loser.
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        // prefer bins whose residual is consumed by item + mean-sized follow-up
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        // penalize placements that leave a residual just below the next
        // item size — the classic "one unit short" waste — harder when other
        // bins can host this item.
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // MUT152: graded dead-space penalty proportional to excess over next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 9.0 * excess * (1.0 - 0.35 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += poly * 10.0;
    // Penalize dead space more strongly as stream progresses
    score += (norm_post * norm_post * norm_post) * (progress * 20.0);
    // Reward tight fits
    let tightness = norm_item / (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 5.0;
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 3.0 * (1.0 - progress);
        } else {
            score += 2.0 * progress;
        }
    }
    // New-bin candidate: mildly discouraged early, allowed late
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 2.0 * progress;
    }
    // Deter fragmenting bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 2.0;
    // Mean residual alignment
    score += (norm_post - mean_residual / bin_capacity as f64).abs() * 3.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it falls into
    // "small unusable" residue classes (1..=9) that nothing (min size 1..100, but
    // typical small items) can still use; reward residuals that are exact divisors
    // or multiples of common item sizes.
    let pr = post_residual;
    if pr > 0 {
        let dead = (pr < 10) as f64;
        score += dead * 40.0;

        // Reward residuals that are multiples of 10 (harmonic with capacity grid)
        if pr % 10 == 0 {
            score -= 12.0;
        }
        // Penalize prime-ish / odd residuals (low divisibility)
        if pr % 2 == 1 {
            score += 6.0;
        }
        if pr % 5 != 0 && pr % 2 == 1 {
            score += 4.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score += slack as f64 * 0.5;
            if slack < 10 {
                score += 10.0; // would create fresh dead space next step
            }
        } else {
            // next item cannot follow into this bin; mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Tightness reward: bins that will be nearly full are good.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Progress-scaled conservatism: early in stream, be pickier about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (pr as f64) * 0.1;

    // Spread penalty: avoid fragmenting when mean residual is already low.
    if (pr as f64) < mean_residual * 0.5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 34.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 238.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // continuous mid-slack dead-space smoothing
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // two-item lookahead: item + next fits almost perfectly
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // chain with mean residual
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            // next item barely fits after this one
            if slack >= 1.0 && slack <= 6.0 && fitting_bins_count >= 2 {
                score -= 12.0 * (1.0 - (slack - 1.0) / 5.0) * (1.0 - 0.3 * progress);
            }
            // pair_fill near-perfect
            if slack >= 0.0 {
                let pair_fill = item_size as f64 + nxt;
                if pair_fill <= pr && pr - pair_fill <= 6.0 {
                    score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
                }
            }
            // discourage leaving a residual the next item almost (not quite) fits when few alternatives
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm > 0.45 && mean_norm < 0.18 && progress > 0.25 {
            score -= 10.0 * (item_norm - 0.45) * (1.0 - mean_norm / 0.18) * (1.0 - 0.5 * progress);
        }
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // fresh bin: discourage when fleet mean residual already matches next item
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        // fresh bin: extra discouragement when item is small and many bins fit it
        if fitting_bins_count >= 3 && item_norm < 0.20 {
            score += 10.0 * (1.0 - item_norm / 0.20) * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
