pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * pr_norm);

    // Penalize tiny dead space (wasted slivers) via smooth quadratic term
    let sliver = (pr as f64 / 10.0).powi(2);
    score += 0.05 * sliver * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 10.0 * tightness * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            score += 0.1 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Mild penalty when many bins are open (discourage fragmentation)
    score += 0.3 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: make it moderately attractive only when residual is large
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) - 5.0 * tightness;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin if an existing one is last chance
        }
    }

    score
}

