pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: near-zero score so this bin always wins.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual modulo 10 (items are multiples of 10 in
    // the classic regime; residual classes that align with future item sizes
    // are more reusable).
    let class = post_residual % 10;
    if class == 0 {
        // Residual stays on a "harmonic" grid: still usable by any item size.
        score -= 8.0;
    } else {
        // Dead space: the smaller the unusable remainder, the worse the waste
        // density. Penalize proportionally to how much of the residual is dead.
        score += (10 - class) as f64 * 2.5;
        // Very tiny residuals (< 10) are almost certainly dead space.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Lookahead coupling (k=2): reward residuals that can chain the next item,
    // reward more when the chain lands back on a harmonic class.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_post = post_residual - next_item_size;
        let chain_bonus = (post_residual - next_item_size) as f64 * 0.8;
        let harmonic_bonus = if chain_post % 10 == 0 { 12.0 } else { 0.0 };
        score -= chain_bonus + harmonic_bonus;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's remainder: residual likely becomes
        // dead space. Penalize harder for small non-harmonic leftovers.
        let deadness = (10 - class) as f64;
        score += 5.0 + deadness * 1.5;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Stream-phase modulation: early in the stream, be slightly more willing
    // to consolidate (favor tight fits); late, keep flexibility.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - phase) * 3.0;

    // New-bin candidate (bin_residual == bin_capacity): give it a baseline
    // near capacity so it only wins when all open bins have heavily
    // penalized (wasteful) fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0 - phase * 5.0;
        // If mean residual across open bins is large, opening new bins is
        // wasteful; make the new-bin candidate even less attractive.
        score += mean_residual * 0.3;
    }

    score
