        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // graded dead-space excess penalty relative to next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: strong reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavy penalty.
        score += 80.0;
    } else if post_residual < 20 {
        score += 30.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when the current bin
    // would leave a large awkward gap or nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Slightly cheaper to open bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is useful.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - lookahead_fit / bin_capacity as f64);
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (binning residual space: fill the fullest-fitting bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual).
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.01 * 10.0 * 0.1; // mild tightness pressure

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        // Reward for enabling the next placement; bigger reward when the
        // chain fit is also tight (small slack after next item).
        score -= 25.0 + 20.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize creating dead space that the next item cannot use,
        // scaled by how much of the residual becomes waste.
        let waste = post_residual as f64;
        let waste_ratio = waste / bin_capacity as f64;
        score += 15.0 * waste_ratio;
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious;
    // wasting them is costly, using them well is rewarded.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 8.0 * (mean_residual - res_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.5 {
            score -= 30.0 * fill_ratio;
        } else {
            score += 10.0 * (1.0 - fill_ratio); // poor fit in last bin: mild penalty
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits (fitting_bins_count == 0) or the stream is early.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else {
            // Deter new bins when alternatives exist, more so late in stream
            // and when open bins are loosely packed.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 20.0 + 25.0 * progress + 10.0 * (mean_residual / bin_capacity as f64);
            // Exception: a huge item (>= half capacity) may deserve a fresh bin
            // to avoid fragmenting existing bins.
            if item_size >= bin_capacity / 2 && post_residual >= next_item_size && next_item_size > 0 {
                score -= 35.0;
            }
        }
    }

    // Slight preference to keep the number of open bins from exploding.
    score += 0.3 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
