            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 9.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 8.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            if slack >= 1.0 && slack <= 6.0 && fitting_bins_count >= 2 {
                score -= 11.0 * (1.0 - (slack - 1.0) / 5.0) * (1.0 - 0.3 * progress);
            }
            // MUT156: penalize residual that next item almost fits but not quite, when few bins can host it
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.0 * (1.0 - 0.5 * progress);
            }
            if slack > 0.0 && nxt > 1.0 {
                let m = (slack / nxt).floor();
                if m >= 2.0 && slack - m * nxt < 1.0 {
                    score -= 5.0 * (1.0 - progress);
                }
            }
            if slack >= 0.0 && item_norm > 0.0 {
                let pair_fill = item_size as f64 + nxt;
                if pair_fill <= pr && pr - pair_fill <= 6.0 {
                    score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
                }
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 8.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.4 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if post_residual > 0 && post_residual < 10 {
        score += 90.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 24.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm > 0.45 && mean_norm < 0.18 && progress > 0.25 {
            score -= 10.0 * (item_norm - 0.45) * (1.0 - mean_norm / 0.18) * (1.0 - 0.5 * progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        if mean_norm > 0.0 && item_norm <= mean_norm * 1.05 && fitting_bins_count >= 2 && nxt_f > 0.0 && nxt_f <= mean_res_safe {
            score += 10.0 * (1.0 - 0.4 * progress);
        }
        // MUT156: discourage opening a fresh bin when the fleet mean residual can host the next item
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        // MUT156: graded dead-space penalty when next item cannot use the residual
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * dead_frac * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
        if pr > 25.0 && pr < 45.0 && item_norm > 0.15 && item_size as f64 > pr {
            score += (45.0 - pr) * 0.18 * (1.0 - 0.3 * progress);
        }
        if dead_frac > 0.22 && mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.95 {
            score += 3.5 * dead_frac * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: fill fraction of the residual consumed by this item.
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Reward leaving residuals that pair well with the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Post-residual can host the next item: reward closeness of match.
            let gap = (post - nxt) / cap;
            score -= 12.0 * (1.0 - gap);
        } else {
            // Post-residual too small for next item: dead-space penalty scaled by waste.
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a fresh bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mildly prefer bins with small residuals (best-fit style).
        score += 2.0 * (post / cap);
    }

    // Penalize creating very small unusable slivers (dead space).
    if post > 0 && post < 10.0 {
        score += 15.0;
    }

    // New-bin candidate handling: opening a bin is costly unless the item fits poorly
    // everywhere or the fleet is congested.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_elsewhere = if fitting_bins_count == 0 {
            0.0
        } else {
            fit_ratio
        };
        // Cost of a new bin, discounted when open bins are nearly full or few fit.
        let mut new_bin_cost = 20.0;
        new_bin_cost -= 15.0 * congestion;      // congested fleet -> new bin cheaper
        new_bin_cost -= 10.0 * poor_fit_elsewhere; // item doesn't fit well anyway
        new_bin_cost -= 8.0 * progress;          // late in stream, keep bins tidy
        if fitting_bins_count == 0 {
            new_bin_cost = -100.0; // no alternative: must open
        }
        score += new_bin_cost;
    }

    // Slight global regularization: prefer bins with residuals below the mean
    // (keeps large residuals available for large items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Reward tight fits: smooth non-linear discount peaking at small post_residual
    score -= (1.0 - pr) * (1.0 - pr) * 12.0;

    // Penalize dead space that is too small for typical future items:
    // smooth valley via polynomial of pr
    score += 6.0 * pr * pr * (1.0 - pr);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward;
    // if next item cannot fit, mild penalty scaled by progress
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        score -= (1.0 - gap / cap).max(0.0) * 8.0;
        if nx > post {
            score += 3.0 * pr * (0.5 + progress);
        }
    }

    // Stream progress: later in stream, prefer consolidating into existing bins
    score += progress * 4.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));

    // Deviation from mean residual: bins far above mean are attractive targets
    score -= 2.0 * (bin_residual as f64 - mean_residual) / cap;

    // Slight penalty for opening new bins when many are open and fit exists
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

