pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "useful" classes.
    // Class by capacity fraction: residual in [0,10) is dead space -> penalize hard.
    if post_residual < 10 {
        score -= 60.0; // perfect-ish fill
    } else {
        // Dead-space penalty grows super-linearly for small unusable remainders.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.15 {
            score += 25.0 * (0.15 - frac) * 10.0;
        }
        // Harmonic class reward: residuals divisible into common item-size blocks
        // (10..80 classes) are more likely to be filled by future items.
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 40, 50, 80].iter() {
            if post_residual % d == 0 && post_residual > 0 {
                harmonic_bonus += 12.0;
            }
        }
        score -= harmonic_bonus;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 40.0; // near-exact chain fit
            } else {
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += 5.0 * over as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, prefer tighter fits: relative fill fraction.
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be tiny
    // or current bin fit is poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // but if item is huge and would leave small residue, new bin is fine
        let pr = post_residual;
        if pr < 10 {
            score -= 90.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins: discourage adding more
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin is far below mean residual (already tight),
    // prefer it (it is nearly full).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 8.0 * dev / bin_capacity as f64 * 10.0;
    } else {
        score += 4.0 * (-dev) / bin_capacity as f64 * 10.0;
    }

    score
}

