pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host plausible items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // risky small gap
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would have fit only if we skip this bin; slight penalty
        score += 5.0;
    }

    // Last-chance bin: strong preference to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but only mildly so tight fits still win.
    score += 0.8 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to the item need.
    let dev = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * dev.abs();

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect or near-perfect fits (low post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fits exactly
        } else if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit: dead space penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare residual against mean residual: prefer filling bins that are
    // already emptier than average? No — prefer bins tighter than average
    // (concentrate waste in few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New empty bin candidate: penalize unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if lookahead suggests a fresh bin enables a good pair, ease up.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 120.0;
        }
    }

    // Late in the stream, consolidate: fewer open bins is better.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    score
}

