            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // graded dead-space penalty proportional to excess over next item size
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" harmonic bands (multiples of common item sizes).
    let cls = post_residual / 10;
    match cls {
        0 => score -= 60.0,            // near-perfect fit (0..=9 dead space)
        1 => score -= 45.0,            // 10..19: fits smallest class
        2 => score -= 30.0,            // 20..29
        3 => score -= 18.0,
        4 => score -= 10.0,
        5 => score -= 5.0,             // 50..59: half-bin harmonic
        6..=8 => score -= 2.0,
        _ => {}                        // large residual: no bonus
    }

    // Modulo harmonic: residuals divisible by small classes are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 5 == 0 { score -= 6.0; }
        else if post_residual % 20 == 0 { score -= 15.0; }
        if post_residual % 3 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin (perfect 2-item chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 25.0; }
            else if gap <= 20 { score -= 12.0; }
        } else {
            // next item cannot fit here; penalize wasted perfect-fit potential
            if post_residual >= 10 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are harmonically poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0
            - 40.0 * progress
            + 8.0 * open_bins_count as f64;
        if mean_residual < 25.0 { score -= 30.0; }  // open bins are nearly full anyway
        if next_item_size > 0 && post_residual >= next_item_size { score -= 20.0; }
    }

    // Tightness reward: the fuller the bin becomes, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.25;

    // Slight preference for bins below mean residual (fill the emptier ones).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic item (<= 9) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Small-but-reusable gaps are still risky if they can't hold the
    // lookahead item; add a mild penalty proportional to tightness.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize it mildly so we only open a new bin when no open bin gives
    // a decent fit, but less than the dead-space penalty so a hopeless
    // (tiny leftover) placement still loses to a fresh bin.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        // If the item would leave a large usable residual, a new bin is fine.
        if post_residual >= 50 {
            score -= 15.0;
        }
    }

    // Slight preference for bins with residuals close to the mean
    // (keeps bin states balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Early in the stream, be a bit more conservative about dead space
    // since many items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.80;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (small post_residual).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Exact-fit reward: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // ---- 2-step lookahead coupling (archetype core) ----
    if next_item_size > 0 {
        // Perfect chaining: next item exactly fills what remains.
        if next_item_size == post_residual {
            score -= 35.0;
        }
        // Next item still fits in the residual: mild bonus scaled to how well it fits.
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize leaving a residual that is
            // "almost but not quite" usable (wasted dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(50.0);
        }
        // Small residuals below the minimum item size are dead space.
        if post_residual > 0 && post_residual < 10.min(bin_capacity) {
            score += 15.0;
        }
    } else {
        // Last item: any placement works, prefer tightest.
        score -= 10.0;
    }

    // ---- Relative-to-mean-residual term ----
    // Prefer placing into bins whose residual is already below average
    // (consolidate fullness), penalize draining the roomiest bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // ---- Last-chance pressure ----
    if fitting_bins_count == 1 {
        // This is the only bin that fits; avoid opening a new bin unless
        // the fit is terrible.
        if post_residual <= bin_capacity / 4 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if fitting_bins_count == 0 {
        // New-bin candidate call: score is post_residual == capacity, add a
        // moderate opening penalty so we only open when fits are bad.
        score += 20.0;
    }

    // ---- Stream progression: late in stream, be more conservative about
    // spreading across bins (fewer chances to consolidate). ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-waste obsession.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize leaving a residual the next item cannot use.
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: pure tight-fit greed.
        score -= 30.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        };
        score += 60.0 - 45.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Dead-space penalty: residuals below typical small item size are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 8.0 * progress * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
            if mean_residual > 1.0 {
                let reuse = pr / mean_residual.max(1.0);
                if reuse < 3.0 && pr >= nxt {
                    score -= 5.0 * (1.0 - reuse / 3.0) * (1.0 - 0.5 * progress);
                }
            }
            // MUT: sharpen mid-slack gradient with a continuous quadratic dead-space term
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            // MUT: extend the quadratic gradient into the large-slack tail
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0).max(1.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            // MUT: exact-multiple chain bonus — residual that fits the next item an exact number of times is a perfect future fill
            if slack > 0.0 && nxt > 0.0 && slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT: penalize leaving a residual that the next item almost (but not quite) fits
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 22.0 * mean_norm * (1.0 - 0.5 * progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && mean_norm < 0.05 && item_norm < mean_norm * 4.0 {
            score += 12.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && (mean_residual - nxt_f).abs() < 2.0 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        if nxt_f > 0.0 && nxt_f > 0.9 * cap && item_norm < 0.15 {
            score -= 14.0 * (1.0 - progress);
        }
        if item_norm > 0.95 && nxt_f > 0.0 && nxt_f >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        let items_left = total_items.saturating_sub(step_index);
        if items_left <= 3 && item_norm > 0.5 {
            score -= 18.0 * item_norm;
        }
        if fitting_bins_count >= 4 && item_norm < 0.35 && progress < 0.4 {
            score += 10.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && item_norm < 0.4 && (cap - item_size as f64) > 1.5 * mean_residual.max(1.0) && fitting_bins_count >= 2 {
            score += 8.0 * (1.0 - progress);
        }
        // MUT: fresh-bin opening for tiny items wastes a whole bin — extra penalty when small and bins plentiful
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        // MUT: when a fresh bin is the only candidate, discourage it if the item would leave a residual close to the next item size elsewhere in the fleet
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
