        // tiny items should not open fresh bins when open bins exist
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 250.0 * (1.0 - progress) * 0.4;
        }
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        if dead_frac > 0.2 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && pr >= mean_residual {
            let late_bonus = if progress > 0.65 { 6.0 } else { -4.0 };
            score += late_bonus * dead_frac;
        }
        if dead_frac > 0.15 && next_item_size > 0 && (next_item_size as f64) > pr
            && mean_residual > 0.0 && (pr - mean_residual).abs() < 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= 1.0 && item_size as f64 + mean_residual <= bin_residual as f64
            && (bin_residual as f64 - item_size as f64 - mean_residual) < 2.0 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64
            && next_item_size as f64 - pr <= 2.0 && fitting_bins_count > 1 {
            score += 12.0 * (1.0 - progress);
        }
        // graded excess dead-space penalty
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item_norm = item_size as f64 / cap;
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let mut score = pr;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * (pr / cap) * (1.0 + progress);
    }

    // Lookahead on next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // two-step chain: current item + next item nearly fills residual
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // exact multiple of next item in slack = perfect future fill
            if slack > 0.0 && slack >= nxt {
                let m = (slack / nxt).floor();
                if slack - m * nxt == 0.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // mid-slack quadratic dead-space gradient
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            // pair fill: item + next exactly fills residual
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            // mean-residual alignment of post-residual
            if mean_residual > 0.0 && pr > 0.0 && pr < 0.45 * cap {
                let align = 1.0 - ((pr - mean_residual) / cap).abs() * 8.0;
                if align > 0.0 {
                    score -= 6.0 * align * (1.0 - 0.5 * progress);
                }
            }
        } else {
            let miss = nxt - pr;
            let gap = miss / cap;
            score += gap * (58.0 + 46.0 * progress);
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // Small unusable residual penalty
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // tiny items on a fresh bin waste a whole bin
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        // fresh-bin residual the next item almost fits
        if next_item_size > 0 {
            let fresh_res = cap - item_size as f64;
            let nxt = next_item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt && (nxt - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
        }
    } else {
        // residual in the awkward 11-24 band
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - dead_frac) * (1.0 - 0.4 * progress);
        }
    }

    // Mild consolidation preference
    score += 2.0 * open_bins_count as f64;

    score
}

