    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Exact-multiple chain: residual fits next item an exact number of times
            if slack >= nxt {
                let m = (slack / nxt).floor();
                if m >= 1.0 && slack - m * nxt == 0.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // Continuous dead-space gradient across mid and large slack
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
