            }
        }
        // Large item late in stream: better in a fresh bin than fragmenting a partial
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // Mid-band residual trap
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            } else if pr > 0.0 && norm_pr > 0.25 {
                score += 11.0 * norm_pr * (1.0 - progress);
            }
        }
        if dead_space_helper(norm_pr) > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * norm_pr * (1.0 - 0.4 * progress);
        }
    }

    // Mild consolidation pressure
    score += 2.0 * open_bins_count as f64;
    score
}

