                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let fill = item_norm;

    let mut score = pr;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= 42.0 * tight * (1.0 - progress);
            }
            // MUT: sharpen mid-slack gradient with continuous quadratic dead-space term
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            // MUT: exact-multiple chain bonus — residual fits next item an exact number of times
            if slack > 0.0 && nxt > 1.0 && slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt < 1.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT: penalize leaving residual that next item almost (but not quite) fits
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
            // MUT: residual aligned to fleet mean — future items likely fit
            if mean_residual > 0.0 && pr > 0.0 && pr < 0.45 * cap {
                let align = 1.0 - ((pr - mean_residual) / cap).abs() * 8.0;
                if align > 0.0 {
                    score -= 6.0 * align * (1.0 - 0.5 * progress);
