        score -= 5.0;
    } else {
        score += 0.15 * (post_residual as f64 - 20.0);
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if this bin becomes too fragmented
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or all existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin; cheaper late in the stream if bins are fragmented.
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        // If mean residual is small (open bins are cramped), new bin is less wasteful.
        new_bin_cost -= 0.25 * mean_residual;
