    // for future large items) unless the current item is large.
    let mean_r = mean_residual;
    if (bin_residual as f64) > mean_r + 15.0 && item_size < 40 {
        score += 3.0;
    } else if (bin_residual as f64) < mean_r - 15.0 {
        score -= 3.0;
