    // Non-linear polynomial coupling of residual with progress
    score += 8.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 4.0 * pr_norm * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly later in stream
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

