pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that is too small to hold even the smallest plausible item is pure waste.
    let dead_threshold = 10u32; // items >= 10 in classic regime; be conservative
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0; // heavy penalty: this bin becomes dead space
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 300.0;
    } else {
        // Non-linear penalty growing as post_residual shrinks toward unusable range.
        let pr = post_residual as f64;
        score += (dead_threshold as f64 / pr.max(1.0)) * 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        // Extra reward if next item nearly fills the bin after placement.
        if post_residual - next_item_size < dead_threshold {
            score -= 40.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to leftover.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage filling existing bins tightly.
    let pressure = (open_bins_count as f64).ln().max(1.0) * 15.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when the mean residual across open bins still has room.
        score += 120.0 + pressure + mean_residual * 0.5;
        // If no existing bin fits at all, opening a new bin is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Reward placing into existing bins, scaled by how tight the fit is.
        score -= pressure * 0.3;
    }

    // Stream progression: later in the stream, be slightly more aggressive about
    // closing bins tightly (dead space matters more as stream ends approach).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

