pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize dead space relative to the smallest useful item (1..100 range).
    let dead = post_residual as f64;
    score += (dead * dead) / (bin_capacity as f64 * 1.5);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more fragmentation: mild penalty scaled by leftover.
            let leftover = post_residual - next_item_size;
            score += leftover as f64 * 0.4;
        } else {
            // Next item won't fit here: mild reward for using this bin now.
            score -= 5.0;
        }
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 3.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future benefits from flexibility); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins more as stream progresses
        // and when mean residual across open bins is already large.
        score += 18.0 + progress * 30.0 + mean_residual * 0.25;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Opening a fresh bin early can be good if current item is small relative to capacity
        if item_size <= bin_capacity / 4 && progress < 0.5 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward reuse more late in the stream.
        score -= progress * 12.0;
        // If item leaves a residual close to mean residual, complementary future fits likely.
        if (post_residual as f64 - mean_residual).abs() < 5.0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize large post-residual more as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth cubic term
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Interact post-residual with mean residual: avoid leaving space when other bins are full
    score += 10.0 * norm_pr * (mean_residual / cap);

    // Last-chance bonus: strongly favor the only fitting bin, smoothly scaled by progress
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress + 0.2);
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 15.0 * (waste / cap) * (1.0 + progress);
    }

    // Mild penalty for too many open bins relative to stream progress
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect-fit and small-dead-space classes
    // are rewarded via modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: perfect fit (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: post_residual divides capacity harmonically (quarter/half/third classes)
    // i.e. residual is a clean fraction of capacity -> usable by typical items.
    let harmonic_units = [1u32, 2, 4, 5, 10, 20, 25, 50];
    for u in harmonic_units {
        if post_residual > 0 && post_residual % (bin_capacity / u) == 0 {
            score -= 40.0 + u as f64;
        }
    }

    // Class 3: integer-division dead-space threshold. Residual below smallest
    // plausible item (<=10) is dead space -> penalize strongly.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 10.0; // mildly awkward class
    }

    // Modulo classes on post_residual: multiples of 10 are "harmonic" targets.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else {
        score += (post_residual % 10) as f64 * 0.8; // penalize off-harmonic remainders
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            score -= 25.0 - (next_post % 10) as f64; // reward smooth chaining
        } else {
            score += 8.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item is large and
    // existing residuals are poor; otherwise bias toward filling open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual; // default penalty for opening new bin
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 55.0; // large item, no good home -> open new bin
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.05 * (1.0 - progress);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (post - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small "unusable" band
    // (too small for the smallest plausible item) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }

    // Reward very tight fits (waste <= 5) strongly.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already small (good consolidation).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward; if post residual can hold next item, mild reward; otherwise
    // slight penalty for fragmenting space the lookahead might need.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: keep it neutral-to-slightly-unattractive so it is
    // chosen only when all open bins have poor fits (their dead-space
    // penalties dominate).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

