        }
    }

    // Late in stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let max_item = 100u32;
        if post_residual >= max_item {
            score -= 6.0; // still fully usable
        } else {
            let dead = (max_item - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item then fits very snugly.
            let nr = post_residual - next_item_size;
            score -= 4.0 * (1.0 - (nr as f64) / (bin_capacity as f64));
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual > 40 {
            score += 8.0; // but bad fits still get pushed toward new bins
        }
    }

    // New-bin candidate handling: opening a bin is attractive only when the item
    // is large or the stream is early / few bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by state.
        let mut new_bin_cost = 25.0;
        new_bin_cost += 15.0 * progress;          // late in stream, prefer existing bins
        new_bin_cost -= 2.0 * open_bins_count as f64; // more open bins => consolidate
        new_bin_cost -= 0.1 * mean_residual;      // high mean residual => reuse
        if item_size >= 60 { new_bin_cost -= 10.0; } // big items pack cleanly in fresh bins
        score += new_bin_cost;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, residual waste is more costly -> amplify post_residual.
    let amp = 0.5 + 1.5 * progress * progress;
    score = score * amp;

    // Strong reward for tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= (cap * tightness * tightness * tightness) * (0.25 + 0.5 * progress);

    // Penalize bins that are nearly full already being "wasted" on this item
    // (i.e., very high fill before placement is fine, but avoid leaving tiny slivers).
    let sliver = (pr as f64).min(12.0);
    score -= sliver * sliver * 0.05; // reward leaving tiny slivers? No: reward means subtract -> we want to penalize slivers
    // Correct: slivers are bad; penalize small-but-nonzero post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64 * (0.5 + progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling: an empty bin should not be chosen unless
    // the fit into existing bins is poor. Give it a mild baseline penalty that
    // shrinks as mean residual across open bins shrinks (open bins nearly full).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 15.0 * openness * (1.0 - progress * 0.5);
        // If the next item is large and this item leaves a bad residual for it,
        // opening a fresh bin is more attractive.
        let ni = next_item_size as f64;
        if ni > 0.0 {
            let leftover_fit = if pr >= ni { 1.0 } else { 0.0 };
            if leftover_fit < 1.0 {
                score -= 10.0 * (1.0 - progress); // fresh bin can host next item
            }
        }
    } else {
        // Lookahead: penalize placements that leave a residual unusable by the
        // next item when that residual is small enough that nothing fits.
        let ni = next_item_size as f64;
        if ni > 0.0 && pr < ni && pr > 0.0 {
            score += 6.0 * (1.0 - pr / ni.max(1.0)) * (0.5 + progress);
        }
        // Reward placements whose residual still accommodates the next item well.
        if ni > 0.0 && pr >= ni {
            score -= 4.0 * (1.0 - ((pr - ni) / cap).abs()) * (0.3 + 0.4 * progress);
        }
    }

    // Mild preference to keep the number of open bins in check when they are
    // collectively full (mean residual low) -> reuse existing bins.
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-classes of capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals in "awkward" classes (small, unusable slivers)
    // Classes: post_residual mod 10 -> classify into harmonic buckets
    let class = post_residual % 10;
    match class {
        0 => { score -= 4.0; }            // perfectly aligned residual, very reusable
        1..=3 => { score += 6.0; }        // tiny slivers, near-dead space
        4..=6 => { score += 1.5; }        // moderately awkward
        _ => { score -= 1.0; }            // larger residuals still useful
    }

    // Integer-division threshold: post_residual / item_size ratio
    if item_size > 0 {
        let ratio = post as f64 / item_size as f64;
        if ratio >= 1.0 {
            score -= 3.0; // bin could host another item of same size later
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 2.0;
        } else {
            // next item won't fit here; penalize small leftover proportionally
            score += (next_item_size as f64 - post) * 0.3;
        }
        // Harmonic pairing: post_residual + next_item_size sums to capacity-fraction classes
        let pair_sum = post_residual + next_item_size;
        if pair_sum == bin_capacity {
            score -= 15.0;
        } else if pair_sum % 50 == 0 {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // early in stream, opening bins is cheaper (build diversity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if many bins already open, discourage opening more
        score += open_bins_count as f64 * 1.5;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // mild reward for keeping bins consolidated
        score -= mean_residual * 0.05;
    }

    // Encourage filling bins tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (low post_residual relative to bin capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: dead space likely.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheap so allow it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += 0.6 * pressure;

    // Prefer bins with residuals close to the item (minimize fragmentation).
    score += 0.3 * ((bin_residual as f64 - item_size as f64).abs());

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // Opening a new bin wastes existing capacity — make it costly
            // unless current bin leaves terrible dead space.
            if post_residual < 10 && bin_residual != bin_capacity {
                score -= 5.0;
            } else {
                score += 18.0;
            }
        }
    }

    // Mean-residual coupling: if open bins are already slack, penalize
    // adding more slack.
    if mean_residual > item_size as f64 * 2.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
