            score -= 100.0;
        }
        // Late in stream, prefer reusing open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins with larger residual (more flexible) when lookahead unknown.
    if next_item_size == 0 {
