pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual (already the base), amplify near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0 - post_residual as f64;
    }

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.2;
        }
    }

    // Time horizon: early in stream, prefer keeping bins flexible (mild penalty on very low post_residual
    // unless it's zero); late in stream, prefer aggressive packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 20 {
        score += 8.0 * (0.3 - progress);
    } else if progress > 0.7 {
        score -= 5.0 * (progress - 0.7);
    }

    // Global state: many open bins with high mean residual -> discourage opening new bins
    // (penalize new-bin candidate), encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate score: base on residual (100) plus pressure terms.
        score += 30.0;
        if open_bins_count > 0 {
            score += 20.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
        // Late in the stream, opening new bins is less costly.
        score -= 15.0 * progress;
        // If no existing bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Existing bin: reward when many bins are open (consolidation pressure).
        if open_bins_count > 3 {
            score -= (open_bins_count as f64).ln() * 2.0;
        }
        // Favor bins with residual close to mean residual (balanced packing).
        score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post residual (tight fit), with quadratic smoothing.
    let mut score = post + (post * post) / cap;

    // Reward near-perfect fits more aggressively as the stream progresses.
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Dead-space penalty: residuals too small for any plausible item (items >= 1,
    // but small fragments are wasteful) penalized smoothly.
    let frag = (post / cap).clamp(0.0, 1.0);
    score += 15.0 * frag * (1.0 - frag) * (1.0 - progress);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this bin; penalize if next item barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = if nxt <= post { 1.0 } else { 0.0 };
        score -= fit_next * (1.0 - gap / cap) * 12.0;
        score += (1.0 - fit_next) * (nxt / cap) * 4.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate: make it moderately attractive only when open bins are
    // crowded (mean residual low relative to item) or late in the stream.
    if is_new_bin {
        let crowd = mean_residual / cap;
        score -= 6.0 * crowd * (1.0 - progress) + 10.0 * progress;
        score += 5.0 * (1.0 - crowd);
    } else {
        // Slight preference for bins below mean residual (consolidate fullness).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev;
    }

    // Mild pressure to consolidate into fewer bins as open-bin count grows.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Harmonic class of post_residual: bins whose residual lies in "usable"
    // classes (multiples of common small sizes) are more valuable to keep.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect closure — strongly favored
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr >= 10 && pr <= 20 {
        -2.0 // residual in the typical item-size band stays usable
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize tiny dead space (1..9) that no item (min size 10) can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly
    // or well; penalize if next item cannot fit anywhere else and this is the
    // only fitting bin.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nxt_fit = (pr - next_item_size) as f64;
            score += nxt_fit * 0.15;
            if pr == next_item_size {
                score -= 30.0; // chains two perfect fills
            }
        } else {
            // next item won't fit here; if this bin is the item's last chance,
            // strongly favor using it now.
            if fitting_bins_count == 1 {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin bonus: only open bin that fits the current item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make empty bins mildly unattractive by
    // default (post_residual == capacity already gives a high raw score),
    // but reduce the penalty late in the stream or when mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 - 8.0 * progress;
        if mean_residual < 15.0 {
            score -= 12.0; // open bins are nearly full; fresh bin is fine
        }
    }

    // Mild pressure against spreading across many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
