            if next_item_size >= 50 {
                score += 10.0;
            }
        }
    }

    // Compare against mean residual: bins with below-average residual are scarcer;
    // using them for a loose fit wastes scarce space, so penalize loose fits there.
    if (bin_residual as f64) < mean_residual {
        score += 8.0 * (1.0 - fit_ratio);
    } else {
        score -= 4.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && fit_ratio > 0.3 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the current item
    // is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        if item_size <= 60 && fitting_bins_count >= 1 {
            score += 50.0;
        } else if fit_ratio < 0.5 {
            score += 20.0;
        } else {
            score -= 10.0; // big item with poor alternatives: fresh bin is fine
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Penalize leaving large residuals relative to the smallest plausible item (1),
    // scaled by how many bins are open (fragmentation cost grows with spread).
    score += 0.05 * (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post residual waste.
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits in post residual, reward this bin.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual in all open bins.
    if bin_residual == bin_capacity {
        // Default: opening new bins is expensive.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (this bin would leave big waste elsewhere),
        // opening a fresh bin becomes attractive when mean residual is large.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        if mean_residual > 0.5 * cap {
            score -= 0.05 * (mean_residual - 0.5 * cap);
        }
    }

    // Mild preference to consolidate into fuller bins (low residual relative to mean).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: late in the stream, avoid opening new bins even harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
