            score += 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin is a good host.
    if bin_residual == bin_capacity {
        let base = 30.0;
        // Early stream: opening bins is cheaper (more items to come to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 80.0 * progress + 0.5 * open_bins_count as f64;
        // If mean residual is large, prefer using existing bins.
        score += 2.0 * mean_residual;
        // If next item fits perfectly in a fresh bin, slightly favor it.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 200.0;
        }
    }

    // Mild pressure against spreading across too many open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

