            }
            // Near-miss of next item: bin will be nearly unusable after.
            if pr < nxt && nxt - pr <= 5.0 && fitting_bins_count > 1 {
                score += (5.0 - (nxt - pr)) * 7.0 * (1.0 - 0.4 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // Tiny dead-space residuals are traps early in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        // No alternatives: new bin is fine.
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        // Large next item: a fresh bin preserves room for it.
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // Item much bigger than mean residual: existing bins can't hold such items well.
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        // Large items late in stream: prefer consolidating into fresh full bins.
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        // Tiny items with fragmented fleet: keep them out of fresh bins.
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        // Fresh-bin residual divisibility: leftover that is an exact multiple
        // of the next item is a strong chain bet.
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
    } else {
        // Dead-zone analysis for existing bins.
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 10 {
            score += 100.0 * (1.0 - progress);
        }
        // Trap zone: residuals 11..24 that few items can use.
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        let usable_frac = 1.0 - dead_frac;
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
        // Item exactly fills the dead zone: good, not bad.
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && item_norm > 0.7 && dead_frac > 0.2 {
            score += 8.0 * item_norm * (1.0 - progress);
        }
        if next_item_size > 0 && pr > 0.0 && dead_frac > 0.4 && (next_item_size as f64) > pr {
            let wasted = dead_frac - (next_item_size as f64 / cap);
            if wasted > 0.0 {
                score += 6.0 * wasted * (1.0 - 0.5 * progress);
            }
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // Residual alignment with fleet mean keeps future fits available.
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
        if next_item_size > 0 && mean_residual > 0.0 && pr >= next_item_size as f64 + mean_residual {
            score -= 4.0 * (1.0 - progress);
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.22 && mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.95 {
            score += 3.5 * dead_frac * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.12 && next_item_size > 0 && pr > 0.0 && pr < (item_size as f64 + next_item_size as f64) && item_norm < 0.35 {
            score += 4.0 * dead_frac * (1.0 - 0.4 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        // Filling a roomy bin when fleet is crowded avoids sprawl.
        if open_bins_count > 4 && bin_residual > 50 {
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 5.0 * fill * (1.0 - 0.5 * progress);
        }
    }

    // Small tie-breaker: prefer bins whose residual is closest to item size.
    let frac = (bin_residual as f64 / cap - item_size as f64 / cap).abs();
    score += 3.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 9.0; // gaps below smallest item (1..100 unknown, use small threshold)
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 25.0;
    }

    // Non-linear penalty for wasted capacity relative to bin size.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 20.0;

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // If next item could use the post-residual, reward leaving a usable gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // gap too small for next item: penalize
        }
    }

    // Prefer bins with residual close to mean (balanced packing) mildly.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // Late in stream: tighten packing, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well.
        score += 15.0 * (1.0 - progress) + 5.0;
        if fitting_bins_count >= 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose leftover can exactly/nearly host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual >= next_item_size {
            // Next item fits: reward tight chains, strongest on exact match.
            score -= 20.0 + 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space scaled by shortfall.
            score += 5.0 + 0.5 * (nxt - post_residual as f64);
        }
        // Exact wrap-around match is ideal.
        if diff < 0.5 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 10.0;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only fitting bin; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of open bins could take the item.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * fitting_bins_count as f64;
        // Early in the stream, slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer tighter fits overall (relative waste ratio).
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Tiered tight-fit rewards (borrowed from best-known, scaled to parent style)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // --- 2-step lookahead on slack = post_residual - next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Exact multiple of next item => guaranteed chain
            if slack >= 2.0 * nxt && slack % nxt == 0.0 {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // Off-by-few dead space above a multiple
            if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // Residual tracks fleet mean => future items keep fitting
            if mean_residual > 0.0 {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
        } else {
            let miss = nxt - pr;
            let gap = miss / cap;
            score += gap * (58.0 + 46.0 * progress);
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // --- Mean-residual coupling: prefer tighter bins ---
    let rel_mean = bin_residual as f64 - mean_residual;
    score += 0.15 * rel_mean;

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // Fresh-bin residual divisibility: chain bet
        if next_item_size > 0 {
            let fresh_res = cap - item_size as f64;
            let nxt_f = next_item_size as f64;
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
        }
        // Avoid opening bins for tiny items when open bins are plentiful
        if item_norm < 0.12 && fitting_bins_count >= 2 {
            score += 20.0 * (1.0 - item_norm / 0.12) * (1.0 - progress);
        }
    } else {
        // Mid-band trap: residuals 11-24 are hard to fill later
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver > 0.0 && sliver < 0.05 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
            }
        }
    }

    // Small residual near end is a waste risk
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Late-stream consolidation
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit is strongly favored.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing),
    // penalize if post_residual is small but nonzero and next item can't use it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Small dead space that no future item (>=10) can use.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; scale with stream progress and open bins.
        score += 25.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If mean residual is large, prefer using open bins.
        score += mean_residual * 0.4;
        // But if item barely fits nowhere well (large item), new bin is fine.
        if item_size > 60 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with larger residual capacity utilization ratio.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.3 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: penalize wasted space, quadratically so tight fits win strongly.
    let mut score = post_norm * post_norm * 120.0;

    // Smooth progress coupling: later in the stream, waste is costlier (compounding).
    score += post_norm * (1.0 + progress * progress * 2.0) * 40.0;

    // Reward filling bins densely, scaled by how "big" the item is relative to capacity.
    score -= fit_ratio * fit_ratio * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + post_norm * 30.0;
    }

    // Prefer bins below the mean residual (consolidating slack), smoothly.
    score += (post - mean_residual) * 0.25;

    // Lookahead: if next item fits in the post-residual, reward leaving usable space;
    // otherwise penalize dead space that can't host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 10.0 * (nxt / cap);
        } else {
            score += 8.0 + post_norm * 20.0;
        }
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that decays
    // with stream progress (opening early is cheap, late is expensive).
    if bin_residual == bin_capacity {
        score = 25.0 + (1.0 - progress) * 15.0 - fit_ratio * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong best-fit bias toward tight fits
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residues divisible by large powers of 2
    // (or by 10) are more "usable" for future items; reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut h = 0u32;
        let mut x = pr;
        while x % 2 == 0 { x /= 2; h += 1; }
        // power-of-two smoothness bonus
        score -= 3.0 * h as f64;
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 5 == 0 { score -= 1.5; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        // tiny dead space classes are bad
        if pr < 10 { score += 25.0; }
        if pr >= 10 && pr <= 15 { score += 5.0; }
    } else {
        // perfect fill is ideal
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / 100.0);
        } else {
            // next item won't fit here; mildly penalize hoarding space it can't use
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is usually wasteful unless
    // current fit is terrible (large post_residual) or few bins fit item.
    if bin_residual == bin_capacity {
        // brand-new bin: neutral-ish score; penalize so it's chosen only when
        // open-bin fits are poor.
        score += 30.0 + 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items together in fresh bins
        }
        if fitting_bins_count <= 1 { score -= 20.0; }
    }

    // Progress-based mild regularization: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Encourage filling bins that are already quite full (small residual)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            if slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT177: exact-multiple chain on current item — guaranteed future fit
            if slack > 0.0 && slack % nxt == 0.0 && slack >= 2.0 * nxt {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // MUT177: off-by-few dead space above a multiple of next item is unusable
            if slack > 0.0 && slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // MUT177: lookahead coupling — current + next nearly fills residual
            let pair = item_size as f64 + nxt;
            if pr >= pair && pr - pair <= 6.0 {
                score -= 11.0 * (1.0 - (pr - pair) / 6.0) * (1.0 - 0.35 * progress);
            }
            // MUT177: dead-space ratio coupling
            if slack > 2.5 * item_size as f64 && item_norm > 0.05 && fitting_bins_count >= 2 {
                score += 3.5 * ((slack / item_size as f64) - 2.5).min(4.0) * (1.0 - 0.4 * progress);
            }
            // MUT177: multi-item chain planning (two/three-item lookahead)
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // MUT177: chain continuation via fleet mean residual
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            // MUT177: residual-continuation — post-residual tracking fleet mean keeps future fits alive
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
            // MUT177: tight-slack bonus with multiple fitting bins
            if slack >= 1.0 && slack <= 6.0 && fitting_bins_count >= 2 {
                score -= 12.0 * (1.0 - (slack - 1.0) / 5.0) * (1.0 - 0.3 * progress);
            }
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - miss / (nxt - pr + miss)) * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            // MUT177: fresh-bin residual divisibility — a leftover that is an exact multiple of the next item is a strong chain bet
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT177: pair-fit forecast — fresh bin should be able to host item + next item
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        // MUT177: avoid fresh bin for very large items when a next item also needs space
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        // MUT177: graded dead-space penalty proportional to excess over the next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT177: near-miss trap — residual just below next item wastes space when alternatives exist
        if next_item_size > 0 && pr > 0.0 && pr < (item_size as f64 + next_item_size as f64) && dead_frac > 0.12 && item_norm < 0.35 {
            score += 4.0 * dead_frac * (1.0 - 0.4 * progress);
        }
        // MUT177: penalize residuals below the fleet mean when the next item misses
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // while exact fits (post_residual == 0) are strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 12 {
        score += (13 - post_residual) as f64 * 8.0;
    }

    // Reward good fill ratio of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate (empty bin): make it attractive only when existing fits are poor
    // (many bins competing, i.e., low per-bin fit pressure) or dead space would be created.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        } else {
            // opening new bin is wasteful when item fits elsewhere; penalize moderately,
            // but allow it if it would create dead space in every existing bin.
            if post_residual == 0 || post_residual > 12 {
                score -= 5.0;
            } else {
                score += 20.0;
            }
            score += pressure * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual nicely, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 12.0;
        } else if gap <= 12 {
            score += gap as f64 * 1.5;
        } else {
            score -= 2.0;
        }
    }

    // Prefer bins tighter than the mean residual (well-utilized bins).
    score -= (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead with graded chain bonuses
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // residual divisibility: exact multiple of next item chains well
            if slack >= 2.0 * nxt && slack % nxt == 0.0 {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // off-by-few dead space above a multiple is unfillable
            if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // pair-fill: current + next leaves near-zero slack
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            // residual tracks fleet mean: future items keep fitting
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
        } else {
            let miss = nxt - pr;
            score += (miss / cap) * (58.0 + 46.0 * progress);
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // Penalize tiny dead space
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: adaptive gate based on pressure and item size
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // opening a bin whose fresh residual is an exact multiple of next item is a chain bet
        let fresh_res = cap - item_size as f64;
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
            score -= 12.0 * (1.0 - 0.3 * progress);
        }
        // avoid opening a bin whose fresh residual just barely misses the next item
        if nxt_f > 0.0 && fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
            score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
        }
        // large items late: avoid wasting open bins on them
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // mid-band trap: residuals 11..24 often become dead space
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            let dead_frac = norm_pr;
            if dead_frac > 0.15 && dead_frac < 0.35 {
                score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
            }
        }
    }

    // Mild consolidation preference
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack that still fits the next item is "useful" residual.
            score -= 40.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // Dead space relative to the next item.
            score += 25.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let avg_fair = 100.0 - (item_size as f64);
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is attractive if the next item also fits alongside here.
            if post_residual >= next_item_size {
                score -= 30.0;
            }
        }
        let _ = avg_fair;
    }

    // Slight preference for keeping residual away from awkward mid-range dead zones.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers are bad unless it was a perfect fit
        if post_residual <= 5 { score -= 100.0; }
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

