                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // exact multiple chain: residual divisible by next item
            if slack > 0.0 && slack % nxt == 0.0 && slack >= 2.0 * nxt {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // pair fill: current + next nearly fills the bin
            let pair = item_size as f64 + nxt;
            if pair <= pr && pr - pair <= 6.0 {
                score -= 8.0 * (1.0 - (pr - pair) / 6.0) * (1.0 - 0.5 * progress);
            }
            // off-by-few above a multiple: dead space nothing can fill
            if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // track the fleet mean residual for future fits
            if mean_residual > 0.0 {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
        } else {
            let miss = nxt - pr;
            score += (miss / cap) * (58.0 + 46.0 * progress);
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        // fresh-bin residual chain bet: leftover divisible by next item
        if next_item_size > 0 {
            let fresh = cap - item_size as f64;
            if fresh > 0.0 && fresh >= next_item_size as f64 && fresh % next_item_size as f64 == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
        // avoid opening a bin for a tiny item when many bins are open
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
    }

    // Consolidation pressure
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that cannot fit the next item's minimum size.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * post_residual as f64;
    }

    // Lookahead synergy: if the next item exactly fills the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead credit proportional to how much of the gap the next item uses.
        let use_frac = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * use_frac;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit is bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how many open bins exist and
        // how much slack is globally available.
        score += 20.0 + 1.5 * open_bins_count as f64;
        if (mean_residual - item_size as f64).abs() > 1e-9 && mean_residual >= item_size as f64 {
            score += 8.0; // an open bin could hold it reasonably well
        }
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight preference for bins below mean residual (balance the pool),
    // keeping some bins with large residual for future big items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time-horizon modulation: early on, be greedy (favor tight fits more);
    // later, be conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress) * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress;
    score += 0.5 * poly * cap;

    // Reward tight fits more strongly later in the stream (subtract)
    let tightness = 1.0 - norm_pr;
    score -= tightness * (1.0 + progress) * (1.0 + progress) * 10.0;

    // Penalize dead space relative to mean residual (smooth cubic)
    let mr = mean_residual / cap;
    let dev = norm_pr - mr;
    score += dev * dev * dev * 5.0 + dev * 3.0;

    // Lookahead: reward leaving room for next item, penalize wasting near-fit space
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= (1.0 - slack) * 6.0 * (1.0 + progress);
        } else {
            let gap = (ni - pr) / cap;
            score += gap * gap * 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Many open bins: mild penalty favoring consolidation into fuller bins
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // two-item chain: item + next both fit
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            }
            // divisibility chain: leftover exactly a multiple of next item
            if slack > 0.0 && slack % nxt == 0.0 && slack >= 2.0 * nxt {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // barely-above-multiple dead space
            if slack > 0.0 && slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // pair fill: item + next nearly fill the bin
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            // residual tracks fleet mean -> future fits keep existing
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // Penalize small unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: keep it neutral-ish, only chosen when no good fit exists
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        // fresh-bin residual divisibility: opening a bin whose leftover is an
        // exact multiple of the next item is a strong chain bet
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
        }
        // item barely misses mean residual: a fresh bin would trap it
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        if (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm > 0.55 {
            score += 14.0 * item_norm;
        }
    }

    // Mild preference for consolidating into fewer bins
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it lands in.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;
    let pr = post_residual;

    // Perfect-fill reward: exact division into capacity harmonics.
    if pr == 0 {
        score -= 60.0;
    } else if pr % quarter == 0 {
        score -= 25.0;
    } else if pr % fifth == 0 {
        score -= 15.0;
    } else if pr % tenth == 0 {
        score -= 8.0;
    } else {
        // Dead-space penalty for residuals in awkward small slivers.
        if pr < tenth {
            score += 30.0;
        } else if pr < fifth {
            score += 10.0;
        }
    }

    // Lookahead coupling: does the residual land in a class that next_item_size can reuse?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            // Reward when the next item also lands on a harmonic class after placement.
            if (pr - next_item_size) % tenth == 0 {
                score -= 12.0;
            } else {
                score -= 6.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to leftover waste.
            score += 10.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would be left very tight
    // or the stream is early and spread is desirable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when decent fits exist; relax late in the stream.
        score += 55.0 - 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // A fresh bin is good if the item is large relative to capacity.
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Prefer packing into bins whose residual is already near-mean (keeps bins homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for fewer open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.01;

    // Exact-fit tightness: reward small post residuals on harmonic boundaries only.
    if pr > 0 && pr <= tenth {
        score += 5.0; // sliver waste
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the next item are wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Dead space penalty, stronger for tiny unusable slivers.
            let dead = post_residual as f64;
            score += 12.0 + 0.5 * (next_item_size as f64 - dead);
            // Extra penalty if the dead gap is very small (< 10).
            if dead < 10.0 {
                score += 15.0;
            }
        } else if post_residual >= next_item_size {
            // Reward leaving a gap exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 - 0.05 * slack;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor compacting into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Reward bins whose residual is below the mean (tighter-than-average bins).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.15 * (mean_residual - res_f);
    } else {
        score += 0.10 * (res_f - mean_residual);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (item large relative to residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        let tight_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count as f64) <= 1.0 && (item_size as f64) > 0.6 * bin_capacity as f64;
        if tight_elsewhere {
            score -= 18.0;
        } else {
            // Penalize opening a new bin when decent fits exist.
            score += 30.0 + 2.0 * (fitting_bins_count as f64);
        }
    }

    // Late in the stream, prefer tighter packing (less fragmentation at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: smaller post residual relative to capacity is better.
        score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // Aggressive 2-step lookahead: reward if the NEXT item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // partial chaining: closer match is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item would NOT fit in the resulting residual: penalize wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Compare residual against mean residual: bins below mean residual are tighter,
    // prefer packing into tighter bins (best-fit flavor).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when other bins fit, unless current bins are very full.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0;
        // allow new bin if existing residuals are all too tight on average
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward for near-exact two-item packing.
            let two = item_size + next_item_size;
            if bin_residual >= two && (bin_residual - two) < 10 {
                score -= 10.0;
            }
        } else {
            // Leftover unusable by next item: mild penalty scaled by waste.
            let waste = next_item_size - post_residual;
            score += 0.05 * (waste as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    let pressure = (open_bins_count as f64) / (1.0 + step_index as f64);
    score += 2.0 * pressure * (post_residual as f64) / (bin_capacity as f64);

    // Global mean residual coupling: bins far from the mean get normalized.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: be more exploratory (favor new bins for large items);
    // late stream: consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score += 10.0 * progress - 5.0 * (1.0 - progress);
        if item_size > 60 {
            score -= 4.0; // big items start fresh bins more readily
        }
    } else {
        score -= 3.0 * progress;
    }

    // Slight preference for bins with larger residuals when item is large.
    score -= 0.02 * (bin_residual as f64) * (item_size as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / capacity;

    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it grows cubically
    score += 0.35 * (post / capacity).powf(3.0) * capacity;

    // Reward high fill ratio, amplified smoothly by stream progress
    score -= (1.0 + 2.0 * progress) * fill * fill * 8.0;

    // Coupling: post_residual vs next item — smooth compatibility term
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / capacity;
        let compat = (-gap * gap * 12.0).exp();
        score -= 6.0 * compat;
        score += 2.5 * (1.0 - (-gap.abs() * 6.0).exp());
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Penalize scattering when many bins are open; smooth in open_bins_count
    let spread = (open_bins_count as f64).ln1p();
    score += 1.2 * spread * (post / capacity);

    // Mean-residual alignment: prefer bins near the mean residual state
    let dev = (post - mean_residual) / capacity;
    score += 3.0 * dev * dev;

    // New-bin candidate: smooth penalty that relaxes late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 4.0 * spread;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class 0 (residual divisible by 10) is the most reusable slot size.
    let residual_class = (post_residual % 10) as f64;
    score += residual_class * 0.8;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Fractional capacity coupling: reward filling a large share of the bin.
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 15.0;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item exactly matches the post-residual (harmonic
    // pairing), this placement is perfect.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot use leftover: penalize large dead space.
            score += (post_residual as f64) * 0.15;
        }
        // Harmonic pairing on decade classes: next item fits a residual
        // rounded to the same class.
        if next_item_size / 10 == post_residual / 10 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - crowd * 2.0 - avg_tightness * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if post_residual >= item_size {
            score -= 5.0; // new bin can host the next item too
        }
    }

    // Late in the stream, tighten up: prefer closing bins well.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (10.0 - residual_class * 0.5);

    // Small tie-break noise-free deterministic nudge toward fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // sharpen mid-slack gradient with a continuous quadratic dead-space term
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            // exact-multiple chain bonus
            if slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // lookahead coupling — current item + next item exactly fills residual
            let pair = item_size as f64 + nxt;
            if pr >= pair && pr - pair <= 3.0 {
                score -= 11.0 * (1.0 - (pr - pair) / 3.0) * (1.0 - 0.35 * progress);
            }
            // dead-space ratio coupling
            if slack > 2.5 * item_size as f64 && item_norm > 0.05 && fitting_bins_count >= 2 {
                score += 3.5 * ((slack / item_size as f64) - 2.5).min(4.0) * (1.0 - 0.4 * progress);
            }
            // two-item chain planning
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // MUT180: exact multiple of next item guarantees a future chain fit
            if slack > 0.0 && slack % nxt == 0.0 && slack >= 2.0 * nxt {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // MUT180: penalize off-by-few residuals above a multiple of the next item
            if slack > 0.0 && slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // MUT180: residual-continuation — keep post-residual near fleet mean so future items keep fitting
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
            // MUT180: chain via mean residual
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - miss / (nxt - pr + miss)) * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if post_residual > 0 && post_residual < 10 {
        score += 100.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            // MUT180: fresh-bin leftover divisible by next item — strong chain bet
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT180: large item with next item nearly co-filling a fresh bin — avoid opening
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        // MUT180: item harmonically matches mean residual — prefer fresh bin pairing
        if fitting_bins_count >= 1 && mean_norm > 0.0 && item_norm > mean_norm * 0.8 && item_norm < mean_norm * 1.6 {
            score += 9.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        // graded dead-space penalty proportional to excess over the next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT180: trap band — residuals that almost (but not quite) fit the next item strand space
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        // MUT180: item smaller than dead space and next item can't fit — dead space is stranded
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small post_residuals that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 25.0 / (1.0 + tightness * 3.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure against accumulating many open bins: encourage filling existing bins
    // when the stream is far along.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 1.2 * progress);

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * -0.3 + mean_residual * -0.05;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 25.0; // no open bin has room worth using -> open new bin
        }
    }

    // Mild preference toward bins below mean residual (consolidate emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let fill = item_norm;

    let mut score = pr;
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 30.0 + cube * 40.0) * (0.5 + progress);

    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) * (0.5 + progress);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 160.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 20.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 14.0 * progress;
    } else if post_residual <= 35 {
        score += 5.0 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    score -= fill * fill * 25.0 * (1.0 - 0.5 * progress);

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 640.0;
        } else if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += gap * (50.0 + 48.0 * progress);
            if nxt <= 12.0 {
                score += 15.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            // MUT: if the fleet mean residual can still absorb next item, a near-miss here is cheaper
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 5.0 * (1.0 - miss.min(10.0) / 10.0) * (1.0 - progress);
            }
        } else {
            let slack = pr - nxt;
            if slack <= 4.0 {
                score -= 380.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 200.0;
            } else if slack <= 40.0 {
                score -= 95.0 * (1.0 - slack / cap);
            } else {
                let tight = 1.0 - slack / cap;
                score -= tight * 20.0 * (1.0 - progress);
            }
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            // exact-multiple chain bonus
            if slack > 0.0 && nxt > 0.0 && slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT: near-multiple penalty — leftover just above a multiple of next item is dead space
            if slack > 0.0 && slack >= 2.0 * nxt {
                let off = slack - (slack / nxt).floor() * nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // MUT: off-by-few dead space relative to current item too
            if slack > 0.0 && item_size > 1 && slack >= item_size as f64 {
                let off2 = slack - (slack / item_size as f64).floor() * item_size as f64;
                if off2 <= 1.0 {
                    score -= 4.0 * (1.0 - progress);
                }
            }
            // penalize leaving residual that next item almost (but not quite) fits
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
                score += (nxt - slack).min(10.0) * 2.2 * (1.0 - 0.5 * progress);
            }
            // Chain lookahead
            let after = slack;
            if after >= mean_residual.min(cap * 0.5) && after > 0.0 {
                score -= 34.0 * (after / cap);
            }
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            let quad_slack = pr - nxt - 3.0 * item_size as f64;
            if quad_slack >= 0.0 && quad_slack <= 2.0 && item_norm < 0.12 && progress < 0.7 {
                score -= 8.0 * (1.0 - quad_slack / 2.0);
            }
            let pair_fill = item_size as f64 + nxt;
            if pair_fill <= pr && pr - pair_fill <= 6.0 {
                score -= 7.0 * (1.0 - (pr - pair_fill) / 6.0) * (1.0 - 0.5 * progress);
            }
            // item + next exactly fills residual within 3 units
            if pr >= item_size as f64 + nxt && pr - (item_size as f64 + nxt) <= 3.0 {
                score -= 11.0 * (1.0 - (pr - (item_size as f64 + nxt)) / 3.0) * (1.0 - 0.35 * progress);
            }
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            if slack >= 0.0 && slack < 8.0 && item_norm < 0.10 {
                score -= 4.0 * (1.0 - slack / 8.0) * (1.0 - progress);
            }
            // dead-space ratio coupling
            if slack > 2.5 * item_size as f64 && item_norm > 0.05 && fitting_bins_count >= 2 {
                score += 3.5 * ((slack / item_size as f64) - 2.5).min(4.0) * (1.0 - 0.4 * progress);
            }
            // MUT: residual-continuation — prefer post-residuals tracking the fleet mean
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0 + 26.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 3.8 * norm_pr;
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    if bin_residual != bin_capacity && pr >= 8.0 && pr <= 20.0 {
        score += 10.0 + 6.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.5 - 1.6 * progress).exp());
        let size_just = 0.40 + 0.60 * fill;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        let mut new_score = 85.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd
            + cap * 0.1
            + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            new_score -= 220.0;
        }
        if next_item_size > 60 {
            new_score -= 32.0;
        }
        if fill > 0.85 {
            new_score += 34.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            new_score -= 24.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill < 0.5 {
            new_score += 16.0;
        }
        if pr > 0.0 && pr < 8.0 && next_item_size as f64 > pr {
            new_score -= 40.0 * (1.0 - progress);
        }
        if mean_norm < 0.06 && fill < 0.35 && progress > 0.25 {
            new_score -= 28.0 * (1.0 - mean_norm / 0.06);
        }
        if fill > 0.6 && progress > 0.5 {
            new_score -= 13.0 * fill;
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() < 3.0 && fitting_bins_count >= 1 {
            new_score -= 12.0 * (1.0 - progress);
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && fill < 0.6 {
            new_score += 18.0 * (1.0 - progress);
        }
        new_score += (open_bins_count as f64).min(30.0) * 1.2;
        new_score += 25.0 * progress * (1.0 - fill);
        if item_norm < 0.12 && open_bins_count >= 3 {
            new_score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        // fresh-bin residual forecasting
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                new_score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            // MUT: fresh-bin divisibility chain bet
            if fresh_res > 0.0 && fresh_res >= nxt_f && (fresh_res % nxt_f) == 0.0 && fitting_bins_count <= 1 {
                new_score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            new_score += 14.0 * (1.0 - 0.3 * progress);
        }
        score = new_score;
    } else {
        if next_item_size > 0 && pr >= next_item_size as f64 && pr - next_item_size as f64 <= 2.0 {
            score -= 18.0 * (1.0 - progress);
        }
        if pr > 20.0 && pr < 45.0 && next_item_size as f64 > pr {
            score += 6.5 * (1.0 - progress);
        }
        if post_residual == 0 && next_item_size > 0 && (next_item_size as f64) < cap * 0.2 {
            score -= 27.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after2 = pr - next_item_size as f64;
            if after2 > 0.0 && after2 <= 6.0 {
                score -= 22.0 * (1.0 - after2 / 6.0);
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.28 && next_item_size > 0 && (next_item_size as f64) > pr && pr >= item_size as f64 && item_norm < dead_frac - 0.03 {
            score -= 5.0 * (1.0 - item_norm / (dead_frac - 0.03)) * (1.0 - 0.6 * progress);
        }
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if pr > 30.0 && pr < 0.5 * cap && item_norm > 0.3 && item_size as f64 <= pr {
            score -= 5.0 * item_norm * (1.0 - progress);
        }
        // graded dead-space penalty proportional to excess over next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        // MUT: penalize residual below next item but above fleet mean usage threshold —
        // a sliver that neither next item nor mean-residual-sized items can fill
        if dead_frac > 0.0 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.5 {
            score += 6.0 * dead_frac * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item's size (this bin becomes "perfect" next step).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Exact match is a jackpot.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is dangerously close but insufficient
        // for next item (dead space trap).
        else if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean-residual coupling: filling a bin below average residual
    // is good (tightening the fat bins); filling above average is worse.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item leaves a large,
    // awkward residual that no lookahead can use, or late in the stream with
    // many open bins (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        // Default: new bin is expensive.
        score += 30.0;
        // But if this placement would strand a tiny unusable residual, allow it.
        if post_residual < 10 {
            score -= 45.0;
        }
        if awkward > 0.5 && progress > 0.5 && open_bins_count > 3 {
            score -= 35.0;
        }
    }

    // Mild penalty for leaving large residuals relative to capacity.
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the waste relative to item size, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving residual too small for the next item (dead space),
    // reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if leftover exactly chains with next item.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else if post_residual > 0 {
            // Dead space: waste that likely can never be used.
            let dead = post_residual as f64;
            score += 0.6 * dead * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: encourage consolidating into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 2.0 * pressure.min(10.0);

    // Early stream: be slightly conservative with near-full bins, keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 10 {
        score += 8.0 * (0.3 - progress) * 10.0;
    }

    // Mild preference for bins with residual above mean (balance usage).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Penalize new-bin candidate unless item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && fit_ratio > 0.8;
        if good_fit_exists || next_item_size == 0 {
            score += 100.0;
        } else {
            score += 15.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let prog_poly = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 6.0 * pr_norm * pr_norm * (1.0 + 3.0 * prog_poly);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= 14.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Perfect fill bonus (smooth via polynomial).
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 10.0 * (1.0 - (slack_after_next as f64 / cap)) * (0.5 + 0.5 * progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize creating dead space next item cannot use.
        score += 8.0 * pr_norm * (0.5 + 0.5 * progress);
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Penalize when many bins fit item (we can afford to be picky): favor smallest residual.
    if fitting_bins_count > 2 {
        score += 3.0 * pr_norm;
    }

    // Coupling with mean residual: prefer bins close to mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: make it unattractive unless post_residual would be huge and stream late.
    if bin_residual == bin_capacity {
        score += 20.0 - 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
