        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT182: fresh bin for oversized items when fleet residuals are small — good use of a new bin
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
        // MUT182: pair fits into fresh bin comfortably — reward opening for big pairs
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT182: trap band — residuals in 11..24 rarely fill; graded penalty
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        // MUT182: residual matches item size exactly — item would leave zero, strong
        if mean_norm > 0.0 && (item_size as f64 - pr).abs() <= 1.0 && item_size as f64 <= pr {
            score -= 8.0 * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 25
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;
    // Penalize post-residuals whose harmonic class is awkward (small non-zero residue)
    if pr > 0 {
        score += 2.0 * (10.0 - class10) / 10.0;
        if pr < 25 { score += 3.0; }
        else if pr < 50 { score += 1.0; }
    } else {
        score -= 8.0; // perfect fit is excellent
    }

    // Integer-division thresholds: post_residual bucket by pr / 10
    let bucket = pr / 10;
    score += bucket as f64 * 0.3;

    // Lookahead coupling: does next item fit into post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward if next item's size class matches residual class
            let gap = pr - next_item_size;
            if gap % 10 == 0 { score -= 4.0; }
            score -= 2.0 * (1.0 - gap as f64 / cap_f);
        } else {
            // next item won't fit here; penalize wasting a large residual
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin when current fit is terrible or few fitting bins remain
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (item_size as f64 / cap_f) < 0.5;
        if bad_fit && pr > 40 && open_bins_count > 2 {
            score -= 5.0 * (0.3 + 0.7 * progress);
        } else {
            score += 4.0;
        }
        // New bin is attractive when mean residual across open bins is small
        if mean_residual < 15.0 { score -= 3.0; }
    }

    // Slight preference for tighter bins (small residual before placement)
    score += 0.02 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small for the minimum
    // plausible future item are essentially wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 25.0 * (1.0 - tightness.min(1.0));
    }

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize creating many bins only mildly; prefer
    // filling existing bins when the count grows.
    score += (open_bins_count as f64) * 2.0;

    // Mean residual coupling: if the fleet of open bins already has lots of
    // slack, prefer bins that reduce dispersion (avoid clustering dead space).
    if mean_residual > post_residual as f64 {
        score += 8.0 * (mean_residual - post_residual as f64).min(30.0) / 30.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward;
    // if next item cannot fit, penalize leaving this residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no good fit
    // exists, i.e., when the item would leave large dead space everywhere.
    if bin_residual == bin_capacity {
        // New bin baseline: neutral residual (post_residual = capacity - item)
        // plus a mild opening cost, so it wins only when other bins score worse.
        score += 15.0;
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (explore); later, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
