                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            // MUT183: exact-multiple chain bonus — residual fits the next item an exact number of times
            if slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT183: guaranteed chain — residual is an exact multiple of next item with room for 2+
            if slack > 0.0 && slack % nxt == 0.0 && slack >= 2.0 * nxt {
