            if slack > nxt && slack < 2.0 * nxt && 2.0 * nxt - slack <= 4.0 && item_norm < 0.30 {
                score += (4.0 - (2.0 * nxt - slack)) * 3.0 * (1.0 - 0.5 * progress);
            }
            // MUT183: barely-too-small residual for the next item — penalize when alternatives exist
            if slack > 0.0 && slack < nxt && fitting_bins_count <= 2 {
