        // MUT183: tiny items on a fresh bin waste a whole bin — extra penalty when open bins are plentiful
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
