            if slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            // MUT183: near-multiple off-by-few dead space that nothing can fill
            if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // lookahead: current + next item nearly fills residual
            let pair = item_size as f64 + nxt;
            if pr >= pair && pr - pair <= 3.0 {
                score -= 11.0 * (1.0 - (pr - pair) / 3.0) * (1.0 - 0.35 * progress);
            }
            // dead-space ratio coupling
            if slack > 2.5 * item_size as f64 && item_norm > 0.05 && fitting_bins_count >= 2 {
                score += 3.5 * ((slack / item_size as f64) - 2.5).min(4.0) * (1.0 - 0.4 * progress);
            }
            // two-item chain planning
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // MUT183: triple chain — residual fits item+item+next almost exactly
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // MUT183: chain through fleet mean — residual covers next item plus mean residual
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            // MUT183: residual-continuation — post-residual tracking fleet mean keeps future fits alive
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
