        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT183: penalize a bin whose post-residual sits just below the next item while fleet mean is far larger
        if dead_frac > 0.18 && next_item_size > 0 && (next_item_size as f64) > pr && mean_residual > 0.0 && pr < mean_residual * 0.8 {
            score += 9.0 * (dead_frac - 0.18) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that no plausible item can use (items >= 1).
    if post_residual == 0 {
        score -= 25.0; // perfect closure is ideal
    } else if post_residual < 10 {
        score -= 8.0; // small unusable sliver
    } else if post_residual > 60 {
        score += 10.0 * (post_residual as f64 - 60.0) / 40.0; // large leftover keeps bin flexible but wastes
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted compatibility
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        let many_bins = open_bins_count as f64 > 2.0 + step_index as f64 / (total_items.max(1) as f64) * 5.0;
        let mut new_bin_score = 45.0;
        if crowded { new_bin_score -= 20.0; }
        if many_bins { new_bin_score += 10.0; }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 5.0; // fresh bin pairs well with a big next item
        }
        score += new_bin_score;
    } else {
        // Prefer bins whose residual is close to the mean (balance the pool),
        // scaled by stream progression (later: consolidate more aggressively).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 2.0 * deviation * (0.5 + progress);

        // Late in the stream, prefer filling bins nearly full to close them out.
        if progress > 0.7 {
            score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild preference for bins with fewer siblings when residuals are healthy (spread load).
    if open_bins_count > 0 && mean_residual > 40.0 {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

