        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT183: pair-fit forecast — fresh bin should be able to host item+next pair compactly
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        // MUT183: very large next item makes a fresh bin risky when fleet already holds space
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT183: mid-band trap — residuals of 11..24 rarely fit future items, discourage
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        // MUT183: residual that can hold next item plus a near-mean slot is a good continuation
        if next_item_size > 0 && mean_residual > 0.0 && pr >= next_item_size as f64 + mean_residual {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex to penalize large leftovers
    let mut score = pr + 30.0 * norm_pr * norm_pr;

    // Non-linear coupling with stream progress: early on, tolerate residual;
    // later, penalize residual more strongly (polynomial ramp).
    let ramp = 0.5 + 1.5 * progress * progress;
    score *= ramp;

    // Perfect fit reward (smooth, not piecewise)
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead coupling: reward if next item fits in post residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let smooth = (-gap / 20.0).exp();
        score -= 20.0 * smooth;
        // Penalize if post residual is just barely too small for next item
        let tease = (pr / nxt).max(0.0);
        let near_miss = (1.0 - tease).abs() * (pr < nxt) as i32 as f64;
        score += 8.0 * near_miss * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean-residual deviation: prefer bins whose residual deviates from mean
    // (keeps a spread of residual sizes, smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score -= 10.0 * dev * dev;

    // Many open bins: slight preference to fill existing ones
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 * fit_quality; // higher when existing bins would fit well
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 50.0 + 33.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * norm_pr * (1.0 + progress);
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 640.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 240.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            if slack > 6.0 && slack <= 55.0 {
                let t = (slack - 6.0) / 49.0;
                score -= 26.0 * t * (1.0 - t) * (1.0 - 0.25 * progress);
            }
            if slack > 55.0 && slack < 0.5 * cap {
                let t2 = (slack - 55.0) / (0.5 * cap - 55.0);
                score -= 14.0 * t2 * (1.0 - t2) * (1.0 - 0.3 * progress);
            }
            if slack >= nxt {
                let m3 = (slack / nxt).floor();
                if slack - m3 * nxt == 0.0 && m3 >= 1.0 {
                    score -= 7.0 * (1.0 - 0.3 * progress);
                }
            }
            let pair = item_size as f64 + nxt;
            if pr >= pair && pr - pair <= 3.0 {
                score -= 11.0 * (1.0 - (pr - pair) / 3.0) * (1.0 - 0.35 * progress);
            }
            if slack > 2.5 * item_size as f64 && item_norm > 0.05 && fitting_bins_count >= 2 {
                score += 3.5 * ((slack / item_size as f64) - 2.5).min(4.0) * (1.0 - 0.4 * progress);
            }
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // MUT184: three-item chain — residual fits item twice after next item almost exactly
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // MUT184: residual that is an exact multiple of the next item is a guaranteed chain
            if slack >= 2.0 * nxt && slack % nxt == 0.0 {
                score -= 9.0 * (1.0 - 0.25 * progress);
            }
            // MUT184: off-by-few above a multiple is dead space nothing can fill
            if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // MUT184: chain with mean residual — post-residual tracks fleet mean for future fits
            if mean_residual > 0.0 && pr >= nxt {
                let dev = (pr - mean_residual).abs();
                if dev < 0.08 * cap {
                    score -= 4.0 * (1.0 - dev / (0.08 * cap)) * (1.0 - 0.3 * progress);
                }
            }
            // MUT184: small-slack reward when fleet is crowded — lock in tight fits early
            if slack >= 1.0 && slack <= 6.0 && fitting_bins_count >= 2 {
                score -= 12.0 * (1.0 - (slack - 1.0) / 5.0) * (1.0 - 0.3 * progress);
            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            // MUT184: penalize near-miss harder when the fleet mean could already host the next item
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            // MUT184: fresh-bin divisibility — leftover an exact multiple of next item is a chain bet
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT184: encourage fresh bin for large items that pair with next item into a near-full bin
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        // MUT184: discourage fresh bin for very large items when next item is smaller (wastes fresh capacity)
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT184: trap band — residuals in [11,24] rarely get refilled; graded penalty
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        // MUT184: near-miss dead space — next item just misses the residual
        if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr && dead_frac > 0.15 && dead_frac < 0.35 {
            score += 5.0 * (dead_frac - 0.15) / 0.20 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (dead-space quantization)
    let pr = post_residual as i64;
    let residue = pr % 10;
    if post_residual > 0 {
        // Residues 1..9 are awkward dead space; 0 is perfectly packed
        score += match residue {
            0 => -25.0,
            1 | 9 => 6.0,
            2 | 8 => 4.5,
            3 | 7 => 3.0,
            4 | 6 => 1.5,
            _ => 0.0,
        };
    } else {
        // Perfect fill
        score -= 60.0;
    }

    // Integer-division thresholds: post_residual in capacity-fraction bands
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score -= 10.0; // small leftover is fine, bin nearly closed
    } else if post_residual <= half {
        score += 2.0;
    } else {
        score += 8.0; // large leftover = wasteful placement
    }

    // Lookahead coupling: does next item fit exactly or at all?
    if next_item_size > 0 {
        let ns = next_item_size as i64;
        if post_residual == 0 {
            score += 0.0;
        } else if (pr - ns) == 0 {
            score -= 35.0; // next item perfectly fills this bin
        } else if post_residual >= next_item_size {
            score -= 8.0; // keeps future options alive
        } else {
            score += 5.0; // next item cannot use this residual
        }
        // Harmonic pair: item_size + next_item_size divisible by 10 chunks
        if (item_size as i64 + ns) % 10 == 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // Empty bin baseline: competitive score relative to typical post_residual
        score = (bin_capacity - item_size) as f64 + 15.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits, must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item now, maybe big next: fresh bin useful
        }
    }

    // Stream progression: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Congestion: many open bins -> prefer tight fits to consolidate
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 1.5;
        score -= (mean_residual - post_residual as f64).abs() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: dead space that no future item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Penalize leaving a gap that cannot fit the next item (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage spreading into new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bin costly unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
    }

    // Mild preference for tighter bins (smaller residual before placement).
    score += (bin_residual as f64 - post_residual as f64 - item_size as f64).abs() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain perfect fit
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
            // combined residual after both items
            let combined = post_residual - next_item_size;
            score += combined as f64 * 0.3;
            if combined == 0 {
                score -= 300.0; // two-step perfect chain
            }
        } else {
            // next item won't fit here: penalize large dead space
            score += (post_residual as f64 - 10.0).max(0.0) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * big - 20.0;
    }

    // Penalize leaving tiny unusable residuals (below min item size 1..100 safety)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
