pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Reward near-perfect fits strongly (post_residual small relative to capacity)
    let perfect = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * perfect * perfect;

    // Penalize dead space that is too small to be useful for typical items
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / dead_threshold);
    }

    // Lookahead: if next item fits in the post residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra reward if next item exactly consumes residual
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits now but not after placement: mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many fitting bins: mild penalty to prefer tightest fit (score base already does this)
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: if mean residual across open bins is high, prefer consolidating
    // into existing bins rather than spreading; reward bins below mean residual
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0).min(2.0);
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // later, consolidate aggressively
    let exploration = (1.0 - t) * 15.0;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus exploration discount
        score += 45.0 - exploration;
        // Penalize opening a new bin if several bins already fit the item
        score += 10.0 * (fitting_bins_count as f64).min(4.0);
        // If next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 12.0;
        }
    } else {
        // Late stream: reward filling existing bins more
        score -= t * 10.0;
    }

    // Slight penalty for very empty existing bins (waste of an almost-full bin opportunity)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
