                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT185: trap band — mid residuals that few items can fill
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic in normalized post-residual
    score += 8.0 * norm_pr * norm_pr * cap;

    // Interaction with stream progress: tighter packing preferred later
    score += 6.0 * norm_pr * progress * cap;

    // Reward tight fits (small post_residual relative to item) via cubic term
    score -= 4.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr) * cap;

    // Penalize deviation from mean residual (polarization of bin states)
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap);
    }

    // Mild pressure against accumulating many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in small classes is worse
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if frac > 0.0 {
        // penalize small unusable slivers more than proportional
        if post_residual < 10 {
            score += 30.0;
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 30 {
            score += 4.0;
        }
    }

    // Reward leaving room for the next item exactly (harmonic pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // mild reward if next item still fits
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening new bins when many bins are already open with slack
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty grows with existing open slack
        score += 60.0 + mean_residual * 1.5;
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits, must open
        }
    } else {
        // using existing bin reduces open-bin pressure
        score -= 10.0;
    }

    // Progress-based mild tightening: later in stream, prefer tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_residual as f64 / cap);

    score
}

