    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            // MUT185: fresh-bin divisibility — leftover an exact multiple of next item is a chain bet
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
        }
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT185: fresh bin for a large item that pairs with the next item nearly filling capacity
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        if nxt_f > 0.0 && item_norm > 0.9 && nxt_f <= item_size as f64 {
            score -= 26.0 * (1.0 - progress);
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT185: trap-band penalty for residuals nothing common fits (11..24 dead zone)
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        // MUT185: item just below dead_frac — the bin can absorb it without stranding space
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 * (10.0 - post_residual as f64) / 10.0
        } else if post_residual < 20 {
            25.0 * (20.0 - post_residual as f64) / 10.0
        } else {
            0.0
        };
        score += dead;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins whose leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // leftover blocks the next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing residuals are large/fragmented.
        score += 40.0 + pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if mean_residual < item_size as f64 {
            score -= 25.0; // nothing fits well elsewhere
        }
    } else {
        score -= pressure * 0.5; // mild preference for existing bins
    }

    // Waste ratio penalty: fraction of the bin lost to dead space.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Early in stream, be conservative about fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && post_residual > 0 && post_residual < item_size.min(30) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item_norm = item_size as f64 / cap;
    let nxt = next_item_size as f64;
    let mut score = pr;

    // Exact / near-exact residual fills are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0 + 30.0 * progress;
    } else if post_residual <= 10 {
        score -= 45.0 + 32.0 * progress;
    } else if post_residual < 25 {
        score -= 6.0 + 13.0 * progress;
    } else if post_residual <= 35 {
        score += 5.5 * progress;
    } else {
        score += 2.0 * (pr / cap) * (1.0 + progress);
    }

    // Lookahead: reward when the next item fits well into post_residual.
    if nxt > 0.0 {
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 620.0;
            } else if slack <= 4.0 {
                score -= 440.0 - 15.0 * slack;
            } else if slack <= 15.0 {
                score -= 235.0;
            } else if slack <= 40.0 {
                score -= 98.0 * (1.0 - slack / cap);
            } else {
                score -= 42.0 * (1.0 - slack / cap);
            }
            // Two-item chain: current + next nearly fill the bin.
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            }
            // Residual that is an exact multiple of next item = guaranteed chain.
            if slack >= 2.0 * nxt && slack % nxt == 0.0 {
                score -= 9.0 * (1.0 - 0.25 * progress);
            } else if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // Residual just below next item wastes space if other bins exist.
            if pr > 0.0 && pr < nxt && nxt - pr <= 5.0 && fitting_bins_count > 1 {
                score += (5.0 - (nxt - pr)) * 7.0 * (1.0 - 0.4 * progress);
            }
            // Track fleet mean residual for future compatibility.
            if mean_residual > 0.0 && pr > mean_residual && pr - mean_residual < 0.12 * cap {
                score -= 7.0 * (1.0 - (pr - mean_residual) / (0.12 * cap)) * (1.0 - 0.4 * progress);
            }
        } else {
            let miss = nxt - pr;
            score += (miss / cap) * (58.0 + 46.0 * progress);
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
        }
    }

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        score += 80.0 * pressure * (0.40 + 0.60 * item_norm) * (1.0 - 0.3 * progress) + cap * 0.1;
        // Last-chance: no open bin fits -> fresh bin is fine.
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Big next item may warrant a fresh bin.
        if nxt > 60.0 {
            score -= 30.0;
        }
        // Fresh-bin residual divisibility: opening a bin whose leftover is an
        // exact multiple of the next item is a strong chain bet.
        let fresh_res = cap - item_size as f64;
        if nxt > 0.0 && fresh_res > 0.0 {
            if fresh_res >= nxt && fresh_res % nxt == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            } else if fresh_res < nxt && (nxt - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
        }
        // Large items prefer fresh bins.
        if item_norm > 0.85 {
            score += 32.0;
        }
        if item_norm > 0.95 && nxt > 0.0 && nxt >= item_size as f64 {
            score -= 20.0 * (1.0 - progress);
        }
        // Small items should not open bins.
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
    } else {
        // Existing bin: penalize leaving awkward mid-range residuals (traps).
        if post_residual >= 11 && post_residual <= 24 {
            let depth = 1.0 - ((pr - 11.0) / 13.0).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if post_residual > 0 && post_residual < 10 {
            score += 100.0 * (1.0 - progress);
        }
        // Filling a bin deeper is good when next item still fits.
        if nxt > 0.0 && pr >= nxt {
            let fill = (bin_residual as f64 - pr) / cap;
            score -= 14.0 * fill * (1.0 - 0.5 * progress);
            let sliver = pr / cap;
            if sliver < 0.05 && sliver > 0.0 {
                score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
            }
        }
        // Dead space the next item cannot use.
        let dead_frac = pr / cap;
        if dead_frac > 0.25 && nxt > 0.0 && nxt > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        // Last-chance bin: use it rather than open a new one.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Late-stream consolidation.
    score += (open_bins_count as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Exact 2-step chain (item + next fills bin completely)
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward tighter match, scaled by how much slack remains after
            let chain_waste = post_residual as f64 - next;
            score -= 300.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item won't fit in residual: penalize proportional to overshoot
            score += 150.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
        // mild penalty always for large unused gap relative to lookahead
        score += 0.05 * diff;
    }

    // Penalize post_residual that is small but nonzero (dead space nothing small can use later)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins with residual below mean residual (tighter bins first)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 400.0;
        // allow new bin late in stream if existing residuals are all poor
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.0; // new bin still fine for next item, but open bins preferred
        }
    }

    // Slight preference for filling bins early in the stream (keep flexibility later)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 30.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space nonlinearly: small post-residuals are fine, large ones waste capacity.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 - gap.min(15.0);
    }
    // If next item cannot use the leftover, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit elsewhere likely) or no open bin state is favorable.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0; // default cost of opening a new bin
        if large_item > 0.5 {
            score -= (large_item - 0.5) * 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in stream, opening bins is cheaper (build diversity of residuals).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Global state coupling: if mean residual is high, prefer bins that reduce fragmentation
    // (i.e., bins whose residual is close to item size).
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    let poly = prn * prn * (1.0 - t) - prn * t * t;
    score += 4.0 * poly * cap * 0.25;

    // Reward tight fits (low post residual) more strongly later in stream
    score -= 6.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + t);

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap * (1.0 + t);
        } else {
            score -= 3.0 * (1.0 - (pr - nxt).abs() / cap);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer bins with residuals below mean (consolidate waste)
    score += 2.0 * (pr - mean_residual) / cap;

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * t;

    // Slight preference for fuller bins overall
    score += prn * prn * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residual mod capacity classes
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Penalize residuals in "dead zones": small leftovers that few future items can use.
    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // classes 0..10
    match class {
        0 => score += 25.0,          // 0 residual: perfect fit, strongly reward
        1 => score -= 8.0,           // tiny 1..10 leftover: nearly perfect
        2 => score += 6.0,           // 10..20: awkward small dead space
        3 => score += 4.0,
        4 => score -= 2.0,           // 40..50: half-ish, still useful
        5 => score -= 5.0,           // 50..60: good for medium items
        6 => score -= 6.0,
        7 => score -= 4.0,
        8 => score += 3.0,           // 80..90: large residual means poor packing
        9 => score += 6.0,
        _ => {}                      // near-empty bin class
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 30.0;
        } else if nxt <= pr {
            // next item fits: reward proportionally to how well it fills
            score -= 10.0 * (nxt / pr.max(1.0));
        } else {
            // next item cannot fit here: penalize leaving residual just below nxt
            score += 8.0 * (1.0 - (pr / nxt).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless current bins are tight.
    if bin_residual == bin_capacity {
        score = cap + 15.0;
        if fitting_bins_count == 0 {
            score = 5.0; // no alternative: new bin is fine
        } else if mean_residual > 0.55 * cap {
            score -= 10.0; // plenty of slack spread around, new bin acceptable
        }
        // small stream-progress nudge: early on, keep bins consolidated
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += 0.15 * (pr - mean_residual);

    // Slight preference to fill fuller bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // plausible item are pure waste — penalize them heavily (non-linearly).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // General dead-space pressure: the smaller the post_residual relative to
    // capacity, the better the fit — reward tight fits super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize residuals that are unusable for the KNOWN next item: if the
    // lookahead cannot fit into this bin's post_residual, we create dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual remains usable: reward.
        score -= 4.0;
    }

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit
    // is mediocre; encourage using existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit. Make the empty bin moderately costly
    // by default, but cheaper when mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let default_cost = 20.0
            + 0.5 * open_bins_count as f64
            - mean_residual.min(bin_capacity as f64) * 0.15;
        score += default_cost.max(-15.0);
        // If next item is large and current item is small, new bin may be wise.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 12.0;
        }
    }

    // Mild late-stream conservatism: keep consolidation as stream ends.
    if progress > 0.8 {
        score += 0.15 * post_residual as f64;
    }

    score
}

