pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Post-residual could still fit next item: reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Penalize creating dead space that can't fit the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Small post-residual means tight fit; reward (classic best-fit)
    score -= 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 60.0 - 55.0 * pressure - 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if next item exactly fits the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
