            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack / 10.0);
        } else {
            // Wasted potential: post-residual too small for next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / 50.0).min(1.0);
