    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the current
    // fit is bad or the stream is early and many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 40.0 && post_residual < next_item_size.max(1);
        let penalty = if poor_fit || next_item_size == 0 { 60.0 } else { 25.0 + 40.0 * progress };
        score += penalty;
    }

    // Prefer filling bins that are already below-average residual (deeper bins first),
    // scaled by how many open bins exist (more competition => stronger sorting signal).
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 3.0 * residual_gap * (1.0 + (open_bins_count as f64 / 20.0).min(2.0));

    // Mild time-horizon term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

