    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        // base penalty keeps it a fallback
        score += 80.0 + cap * 0.1;
        // open a new bin when residual pressure is low and item is large
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress);
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        // fresh-bin residual divisibility: opening pays off when fresh residual
        // is a clean multiple of the next item
        let nxt_f = next_item_size as f64;
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 2.0 && nxt_f > 4.0 {
                score += 10.0 * (1.0 - (nxt_f - fresh_res) / 2.0) * (1.0 - 0.3 * progress);
            }
        }
        // small items should go into existing gaps, not a fresh bin
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        // large items late in stream: fresh bin is fine
        if item_norm > 0.55 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
    } else {
        // existing-bin refinements
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = pr / cap;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            score += 14.0 * dead_frac * dead_frac * (1.0 - 0.4 * progress);
        }
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
    }

    // Consolidation pressure
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
