            // MUT190: dead-space ratio coupling — slack far above current item size wastes space
            if slack > 2.5 * item_size as f64 && item_norm > 0.05 && fitting_bins_count >= 2 {
                score += 3.5 * ((slack / item_size as f64) - 2.5).min(4.0) * (1.0 - 0.4 * progress);
            }
            // MUT190: two-item chain planning (borrowed from best lineage)
            let two_slack = slack - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 16.0 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 12.0 && item_norm < 0.35 {
                score -= 6.0 * (1.0 - two_slack / 12.0) * (1.0 - progress);
            } else if two_slack > 12.0 && two_slack <= 20.0 && item_norm < 0.25 && progress < 0.6 {
                score -= 4.0 * (1.0 - two_slack / 20.0);
            }
            // MUT190: triple chain — residual holds next item plus two copies of current
            let tri_slack = pr - nxt - 2.0 * item_size as f64;
            if tri_slack >= 0.0 && tri_slack <= 3.0 && item_norm < 0.20 {
                score -= 10.0 * (1.0 - tri_slack / 3.0) * (1.0 - progress);
            }
            // MUT190: chain into the mean residual — residual covers next item + mean residual
            let chain_slack = pr - nxt - mean_residual;
            if chain_slack >= 0.0 && chain_slack <= 6.0 && item_norm < 0.35 {
                score -= 9.0 * (1.0 - chain_slack / 6.0) * (1.0 - 0.4 * progress);
            }
            // MUT190: near-multiple off-bonus — slack slightly over a multiple of next item
            if slack >= 2.0 * nxt {
                let off = slack % nxt;
                if off > 0.0 && off <= 3.0 {
                    score += 5.0 * (1.0 - off / 3.0) * (1.0 - 0.4 * progress);
                }
            }
            // MUT190: current-item multiple bonus — slack exactly fills copies of current item
            if item_size > 1 && slack % (item_size as f64) == 0.0 && slack >= 2.0 * item_size as f64 && item_norm < 0.25 {
                score -= 6.0 * (1.0 - 0.3 * progress);
            }
            // MUT190: mean-residual alignment bonus in the mid-slack band
            if mean_residual > 0.0 && slack > 20.0 && slack < 0.30 * cap && item_norm < 0.20 {
                let align = 1.0 - ((slack - mean_residual) / cap).abs() * 6.0;
                if align > 0.0 {
