            }
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * (58.0 + 46.0 * progress);
            if nxt <= 12.0 {
                score += 14.0 * (1.0 - progress);
            }
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (4.0 + 3.0 * progress);
            }
            if miss <= 3.0 && fitting_bins_count > 1 {
                score += (3.0 - miss) * 9.0 * (1.0 - 0.5 * progress);
            }
            if miss > 0.0 && open_bins_count >= 4 {
                score += miss.min(20.0) * 1.5 * (1.0 - progress);
            }
            // MUT190: near-miss amplification — residual misses the next item by a hair
            if miss <= 1.0 && fitting_bins_count > 1 {
                score += 8.0 * (1.0 - progress);
            }
            // MUT190: penalize residual that misses next item while the fleet mean could hold it
            if miss > 0.0 && mean_residual > 0.0 && mean_residual >= nxt {
                score += 6.0 * (1.0 - progress);
            }
        }
    }

    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (10.0 + 0.4 * open_bins_count.min(25) as f64);

    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = 1.0 / (1.0 + (mean_norm * 7.0 - 1.5 * progress).exp());
        let size_just = 0.40 + 0.60 * item_norm;
        let crowd = 1.0 + 0.05 * (open_bins_count as f64).min(20.0);
        score += 80.0 * pressure * size_just * (1.0 - 0.3 * progress) * crowd + cap * 0.1;
        if fitting_bins_count == 1 {
            score -= 215.0;
        }
        if next_item_size > 60 {
            score -= 30.0;
        }
        if item_norm > 0.85 {
            score += 32.0;
        }
        let mean_res_safe = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let ratio = item_size as f64 / mean_res_safe;
        if ratio > 1.3 {
            score -= 22.0 * (ratio - 1.3).min(2.0);
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && item_norm < 0.5 {
            score += 15.0;
        }
        if item_norm > 0.6 && progress > 0.5 {
            score -= 12.0 * item_norm;
        }
        let nxt_f = next_item_size as f64;
        // MUT190: fresh-bin residual forecasting — penalize fresh bin leaving a residual the next item almost fits
        if nxt_f > 0.0 {
            let fresh_res = cap - item_size as f64;
            if fresh_res > 0.0 && fresh_res < nxt_f && (nxt_f - fresh_res) <= 8.0 {
                score += 6.0 * (1.0 - (nxt_f - fresh_res) / 8.0) * (1.0 - 0.4 * progress);
            }
            // MUT190: reward fresh bin whose residual exactly holds multiples of the next item
            if fresh_res > 0.0 && fresh_res >= nxt_f && fresh_res % nxt_f == 0.0 && fitting_bins_count <= 1 {
                score -= 12.0 * (1.0 - 0.3 * progress);
            }
            // MUT190: reward fresh bin whose residual exactly holds copies of the current item
            if fresh_res > 0.0 && item_size > 1 && fresh_res % (item_size as f64) == 0.0 && item_norm < 0.30 && fresh_res >= 2.0 * item_size as f64 {
                score -= 8.0 * (1.0 - 0.3 * progress);
            }
        }
        // MUT190: tiny items on a fresh bin waste a whole bin — extra penalty when open bins are plentiful
        if item_norm < 0.12 && open_bins_count >= 3 {
            score += 10.0 * (1.0 - item_norm / 0.12) * (1.0 - 0.4 * progress);
        }
        // MUT190: discourage fresh bin when existing fleet already holds a residual near the next item
        if nxt_f > 0.0 && fitting_bins_count == 0 && mean_norm > 0.03 && mean_res_safe >= nxt_f {
            score += 14.0 * (1.0 - 0.3 * progress);
        }
        // MUT190: reward fresh bin when the item closely matches the mean residual (harmonious sizing)
        if nxt_f > 0.0 && mean_norm > 0.02 && (mean_residual - nxt_f).abs() < 4.0 && item_norm < 0.6 {
            score += 18.0 * (1.0 - progress);
        }
        if item_norm < 0.30 && fitting_bins_count >= 2 {
            score += 26.0 * (1.0 - item_norm / 0.30) * (1.0 - 0.4 * progress);
        }
        if item_norm < 0.08 && fitting_bins_count >= 2 && mean_norm > 0.10 {
            score += 20.0 * (1.0 - item_norm / 0.08) * (1.0 - progress);
        }
        if mean_norm > 0.0 && (item_size as f64 - mean_residual).abs() <= 1.0 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUT190: pair-fill fresh-bin discount — current + next item nearly fills a fresh bin
        if nxt_f > 0.0 && (item_size as f64 + nxt_f) <= cap * 0.98 && item_norm > 0.30 && mean_norm < 0.30 {
            score -= 6.0 * (1.0 - (item_size as f64 + nxt_f) / cap) * (1.0 - progress);
        }
        // MUT190: large next item arriving soon — prefer a fresh bin over fragmenting the fleet
        if nxt_f > 0.0 && nxt_f >= 0.75 * cap && item_norm > 0.5 {
            score -= 20.0 * item_norm;
        }
    } else {
        if pr >= 8.0 && pr <= 20.0 {
            score += 9.0 + 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let fill = (bin_residual as f64 - pr) / cap;
                score -= 14.0 * fill * (1.0 - 0.5 * progress);
                let sliver = pr / cap;
                if sliver < 0.05 && sliver > 0.0 {
                    score -= 6.0 * (1.0 - sliver / 0.05) * (1.0 - 0.5 * progress);
                }
                if fitting_bins_count > 3 && sliver < 0.02 {
                    score -= 10.0 * (1.0 - progress);
                }
                let after = pr - nxt;
                if after <= 2.0 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        let dead_frac = norm_pr;
        if dead_frac > 0.25 && next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
            score += 11.0 * dead_frac * (1.0 - progress);
        }
        // MUT190: graded dead-space penalty proportional to excess over the next item
        if dead_frac > 0.05 && next_item_size > 0 && pr > 0.0 {
            let excess = dead_frac - (next_item_size as f64 / cap);
            if excess > 0.0 && excess < 0.15 {
                score += 8.0 * excess * (1.0 - 0.35 * progress);
            }
        }
        if dead_frac > 0.35 && fitting_bins_count >= 2 {
            let usable_frac = 1.0 - dead_frac;
            score += 14.0 * dead_frac * (1.0 - usable_frac) * (1.0 - 0.4 * progress);
        }
        // MUT190: trap band — residuals in the 11–24 range are hard to fill later
        let trap_lo = 11.0;
        let trap_hi = 24.0;
        if post_residual >= trap_lo as u32 && post_residual <= trap_hi as u32 {
            let depth = 1.0 - ((pr - trap_lo) / (trap_hi - trap_lo)).abs();
            score += 7.0 * depth * (0.6 + 0.4 * (1.0 - progress));
        }
        if mean_residual > 0.0 && dead_frac > 0.1 {
            let align = 1.0 - ((pr - mean_residual) / cap).abs() * 4.0;
            if align > 0.0 {
                score -= 4.0 * align * (1.0 - progress) * (1.0 - progress);
            }
        }
        if dead_frac > 0.45 && item_norm < 0.5 && item_size as f64 <= pr {
            score -= 6.0 * (dead_frac - 0.45) * item_norm * (1.0 - 0.5 * progress);
        }
        if dead_frac > 0.10 && item_norm >= dead_frac && fitting_bins_count >= 2 {
            score += 6.0 * (item_norm - dead_frac) * (1.0 - 0.3 * progress);
        }
        // MUT190: dead space too small for the pair — discourage leaving unusable gaps
        if dead_frac > 0.12 && next_item_size > 0 && pr > 0.0 && pr < (item_size as f64 + next_item_size as f64) && item_norm < 0.35 {
            score += 4.0 * dead_frac * (1.0 - 0.4 * progress);
        }
        // MUT190: item just below dead space — a good squeeze, reward it
        if dead_frac > 0.3 && item_norm > dead_frac - 0.05 && item_norm < dead_frac {
            score -= 9.0 * (1.0 - progress);
        }
        // MUT190: late-stage deviation penalty — steer residuals back toward the fleet mean
        if progress > 0.6 && mean_residual > 0.0 && pr > 0.0 {
            let dev2 = (pr - mean_residual) / cap;
            if dev2 > 0.05 {
                score += 5.0 * dev2.min(0.3) * (progress - 0.6) * 2.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * norm_pr;

    // Tight-fit reward: cubic bonus for near-perfect fills
    let tightness = 1.0 - norm_pr;
    score -= 0.8 * tightness * tightness * tightness;

    // Lookahead: penalize residuals that cannot fit the next item, reward usable slack
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 0.5 * gap * gap * cap;
            // near-miss penalty: almost-fitting residuals are wasted capacity
            let miss = nxt - pr;
            if miss <= 6.0 {
                score += (6.0 - miss) * (0.8 + 0.6 * progress);
            }
        } else {
            let slack = pr - nxt;
            score -= 0.2 * (1.0 - slack / cap) * (1.0 - slack / cap);
            // multi-item lookahead: does residual after next item also fit current item?
            let two_slack = pr - nxt - item_size as f64;
            if two_slack >= 0.0 && two_slack <= 5.0 && item_norm < 0.45 {
                score -= 1.2 * (1.0 - two_slack / 5.0) * (1.0 - progress);
            } else if two_slack > 5.0 && two_slack <= 14.0 && item_norm < 0.35 {
                score -= 0.5 * (1.0 - two_slack / 14.0) * (1.0 - progress);
            }
            // exact divisibility: residual perfectly divisible by next item
            if nxt > 1.0 && slack >= 2.0 * nxt {
                let m = (slack / nxt).floor();
                if slack - m * nxt < 1.0 {
                    score -= 0.4 * (1.0 - progress);
                }
            }
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    // Mild pressure to consolidate when many bins are open
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 0.3 * open_norm * norm_pr;

    // Encourage matching the mean residual state (smooth coupling)
    let mean_norm = mean_residual / cap;
    score += 0.15 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // New-bin candidate: open only for large items or when open bins are poor hosts
    if bin_residual == bin_capacity {
        let fill_ratio = item_norm;
        let mut nb = 2.5 - 1.5 * fill_ratio * fill_ratio;
        // pressure: with many open bins holding mean residual >= item, opening is wasteful
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fill_ratio < 0.5 {
            nb += 1.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 && fill_ratio < 0.6 {
            nb -= 0.8;
        }
        if fitting_bins_count == 0 {
            nb -= 3.0;
        }
        if progress > 0.7 && fill_ratio < 0.3 {
            nb += 0.6;
        }
        score = nb;
    }

    score
